// Baza pytań – kwalifikacja MED.10 „Świadczenie usług w zakresie masażu” (technik masażysta 325402).
// MED10-001…205 i od MED10-353: pytania autorskie. MED10-206…352: pytania z poprzednich sesji egzaminu MED.10 (2021–2026). Źródła: wymagania-MED10.md
window.PYTANIA = [
  {"id": "MED10-001", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Podczas resuscytacji krążeniowo-oddechowej osoby dorosłej uciśnięcia klatki piersiowej i oddechy ratownicze wykonuje się w stosunku", "odpowiedzi": {"A": "15 : 2", "B": "30 : 2", "C": "5 : 1", "D": "30 : 1"}, "poprawna": "B", "wyjasnienie": "Wytyczne ERC i Polskiej Rady Resuscytacji zalecają u dorosłych 30 uciśnięć klatki piersiowej na 2 oddechy ratownicze.", "zrodlo": "MED.10.1.8"},
  {"id": "MED10-002", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Uciśnięcia klatki piersiowej u dorosłego podczas RKO powinny mieć głębokość", "odpowiedzi": {"A": "5–6 cm", "B": "2–3 cm", "C": "7–8 cm", "D": "3–4 cm"}, "poprawna": "A", "wyjasnienie": "Zalecana głębokość uciśnięć u dorosłych to 5–6 cm, z pełnym odprężeniem klatki piersiowej po każdym uciśnięciu.", "zrodlo": "MED.10.1.8"},
  {"id": "MED10-003", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Zalecana częstotliwość uciśnięć klatki piersiowej podczas RKO u dorosłego wynosi", "odpowiedzi": {"A": "60–80 na minutę", "B": "120–140 na minutę", "C": "100–120 na minutę", "D": "80–100 na minutę"}, "poprawna": "C", "wyjasnienie": "Wytyczne resuscytacji zalecają tempo 100–120 uciśnięć na minutę.", "zrodlo": "MED.10.1.8"},
  {"id": "MED10-004", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "W pozycji bocznej bezpiecznej należy ułożyć poszkodowanego, który", "odpowiedzi": {"A": "jest nieprzytomny i nie oddycha", "B": "jest przytomny i skarży się na ból w klatce piersiowej", "C": "jest przytomny i ma podejrzenie złamania kości udowej", "D": "jest nieprzytomny i oddycha prawidłowo"}, "poprawna": "D", "wyjasnienie": "Pozycja boczna bezpieczna chroni drogi oddechowe osoby nieprzytomnej, która oddycha. Osoba, która nie oddycha, wymaga RKO.", "zrodlo": "MED.10.1.8"},
  {"id": "MED10-005", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Pacjent po masażu gwałtownie wstał ze stołu, zbladł i zgłasza zawroty głowy oraz ciemnienie przed oczami. Masażysta powinien w pierwszej kolejności", "odpowiedzi": {"A": "ułożyć pacjenta na brzuchu z uniesioną głową", "B": "ułożyć pacjenta na plecach i unieść jego kończyny dolne", "C": "polecić pacjentowi szybki spacer po gabinecie", "D": "posadzić pacjenta i podać mu mocną kawę"}, "poprawna": "B", "wyjasnienie": "Objawy wskazują na zapaść ortostatyczną (stan przedomdleniowy). Ułożenie na plecach z uniesionymi nogami poprawia ukrwienie mózgu.", "zrodlo": "MED.10.1.8"},
  {"id": "MED10-006", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Przy obfitym krwawieniu z rany przedramienia pierwszą czynnością ratownika (po zabezpieczeniu się rękawiczkami) jest", "odpowiedzi": {"A": "założenie opaski uciskowej na szyję poszkodowanego", "B": "przemycie rany wodą utlenioną i pozostawienie jej odkrytej", "C": "bezpośredni ucisk rany jałowym opatrunkiem", "D": "podanie poszkodowanemu ciepłego napoju"}, "poprawna": "C", "wyjasnienie": "Podstawowym sposobem tamowania krwotoku zewnętrznego jest bezpośredni ucisk na ranę, np. opatrunkiem uciskowym.", "zrodlo": "MED.10.1.8"},
  {"id": "MED10-007", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Oparzenie termiczne dłoni gorącą wodą należy w pierwszej kolejności", "odpowiedzi": {"A": "obłożyć bezpośrednio kostkami lodu", "B": "posmarować masłem lub tłustym kremem", "C": "przebić powstałe pęcherze jałową igłą", "D": "schładzać chłodną, bieżącą wodą przez około 20 minut"}, "poprawna": "D", "wyjasnienie": "Chłodzenie bieżącą wodą ogranicza głębokość oparzenia i ból. Lód, tłuszcz i przebijanie pęcherzy są błędem.", "zrodlo": "MED.10.1.8"},
  {"id": "MED10-008", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Przy podejrzeniu złamania trzonu kości długiej kończyny należy unieruchomić", "odpowiedzi": {"A": "dwa sąsiednie stawy, między którymi znajduje się złamana kość", "B": "tylko miejsce złamania, bez stawów", "C": "wyłącznie staw położony poniżej złamania", "D": "całe ciało poszkodowanego na desce ortopedycznej"}, "poprawna": "A", "wyjasnienie": "Zasada unieruchamiania złamań kości długich obejmuje dwa sąsiednie stawy, co zapobiega przemieszczeniu odłamów.", "zrodlo": "MED.10.1.8"},
  {"id": "MED10-009", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Nagłe opadnięcie kącika ust, osłabienie jednej kończyny górnej i zaburzenia mowy mogą świadczyć o", "odpowiedzi": {"A": "hipoglikemii u osoby z cukrzycą", "B": "udarze mózgu", "C": "napadzie astmy oskrzelowej", "D": "zawale mięśnia sercowego"}, "poprawna": "B", "wyjasnienie": "To objawy oceniane w teście FAST (twarz, ręka, mowa, czas), typowe dla udaru mózgu.", "zrodlo": "MED.10.1.8"},
  {"id": "MED10-010", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Silny, gniotący ból za mostkiem, trwający ponad 20 minut i promieniujący do żuchwy oraz lewej kończyny górnej, wskazuje na", "odpowiedzi": {"A": "zapalenie nerwu łokciowego", "B": "udar niedokrwienny mózgu", "C": "zawał mięśnia sercowego", "D": "napad padaczkowy"}, "poprawna": "C", "wyjasnienie": "Długotrwały ból zamostkowy z promieniowaniem do żuchwy i lewej ręki to typowy objaw zawału serca. Należy wezwać pomoc (112/999).", "zrodlo": "MED.10.1.8"},
  {"id": "MED10-011", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Jednolity europejski numer alarmowy to", "odpowiedzi": {"A": "112", "B": "998", "C": "999", "D": "997"}, "poprawna": "A", "wyjasnienie": "112 działa w całej Unii Europejskiej. 997 to Policja, 998 Straż Pożarna, a 999 Pogotowie Ratunkowe.", "zrodlo": "MED.10.1.8"},
  {"id": "MED10-012", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Higieniczną dezynfekcję rąk preparatem alkoholowym wykonuje się metodą", "odpowiedzi": {"A": "Kocha, z użyciem szczoteczki", "B": "Semmelweisa, wyłącznie po zdjęciu rękawiczek", "C": "Listera, przez 5 sekund", "D": "Ayliffe’a, wcierając preparat przez co najmniej 30 sekund"}, "poprawna": "D", "wyjasnienie": "Standardem jest 6-etapowa technika Ayliffe’a. Preparat wciera się do wyschnięcia rąk, zwykle przez 30 sekund.", "zrodlo": "MED.10.1.7"},
  {"id": "MED10-013", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Antyseptyka to", "odpowiedzi": {"A": "niszczenie lub hamowanie rozwoju drobnoustrojów na skórze, błonach śluzowych i w ranach", "B": "niszczenie wszystkich form drobnoustrojów, łącznie z przetrwalnikami, na narzędziach", "C": "usuwanie widocznych zanieczyszczeń z powierzchni wodą z detergentem", "D": "postępowanie zapobiegające przedostaniu się drobnoustrojów do jałowych tkanek i sprzętu"}, "poprawna": "A", "wyjasnienie": "Antyseptyka dotyczy żywych tkanek. Aseptyka to zapobieganie zakażeniu, sterylizacja niszczy wszystkie formy drobnoustrojów, a mycie usuwa brud.", "zrodlo": "MED.10.1.7"},
  {"id": "MED10-014", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Proces niszczący wszystkie drobnoustroje wraz z ich formami przetrwalnikowymi to", "odpowiedzi": {"A": "dezynfekcja", "B": "sterylizacja", "C": "antyseptyka", "D": "pasteryzacja"}, "poprawna": "B", "wyjasnienie": "Tylko sterylizacja niszczy także przetrwalniki. Dezynfekcja ogranicza liczbę drobnoustrojów, ale nie gwarantuje zniszczenia spor.", "zrodlo": "MED.10.1.7"},
  {"id": "MED10-015", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Przed którą chorobą przenoszoną przez krew pracownik ochrony zdrowia może się chronić szczepieniem ochronnym?", "odpowiedzi": {"A": "Wirusowym zapaleniem wątroby typu C", "B": "Zakażeniem wirusem cytomegalii", "C": "Wirusowym zapaleniem wątroby typu B", "D": "Zakażeniem wirusem HIV"}, "poprawna": "C", "wyjasnienie": "Szczepionka istnieje przeciw WZW typu B. Przeciw WZW typu C i HIV szczepionek nie ma.", "zrodlo": "MED.10.1.4"},
  {"id": "MED10-016", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Po zakłuciu się igłą zanieczyszczoną krwią pacjenta pracownik powinien", "odpowiedzi": {"A": "zakleić ranę plastrem i zgłosić zdarzenie dopiero, gdy pojawią się objawy", "B": "przyłożyć lód i odczekać do końca zmiany przed zgłoszeniem", "C": "zatamować krwawienie opaską uciskową i kontynuować pracę", "D": "nie tamować krwawienia, przemyć miejsce wodą z mydłem i zgłosić ekspozycję przełożonemu"}, "poprawna": "D", "wyjasnienie": "Procedura poekspozycyjna: swobodny wypływ krwi, umycie i dezynfekcja oraz natychmiastowe zgłoszenie, bo profilaktyka (np. leki antyretrowirusowe) jest najskuteczniejsza w ciągu kilku godzin.", "zrodlo": "MED.10.1.7"},
  {"id": "MED10-017", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Znak nakazu w oznakowaniu BHP ma postać", "odpowiedzi": {"A": "zielonego prostokąta z białym piktogramem", "B": "niebieskiego koła z białym piktogramem", "C": "żółtego trójkąta z czarną obwódką", "D": "czerwonego koła z przekreślonym piktogramem"}, "poprawna": "B", "wyjasnienie": "Nakaz: niebieskie koło. Zakaz: czerwone koło z przekreśleniem. Ostrzeżenie: żółty trójkąt. Ewakuacja: zielony prostokąt.", "zrodlo": "MED.10.1.1"},
  {"id": "MED10-018", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Organem powołanym do nadzoru i kontroli przestrzegania prawa pracy, w tym przepisów BHP, jest", "odpowiedzi": {"A": "Urząd Dozoru Technicznego", "B": "Rzecznik Praw Pacjenta", "C": "Państwowa Inspekcja Pracy", "D": "Narodowy Fundusz Zdrowia"}, "poprawna": "C", "wyjasnienie": "PIP kontroluje przestrzeganie prawa pracy i BHP. UDT nadzoruje urządzenia techniczne, a NFZ finansuje świadczenia.", "zrodlo": "MED.10.1.2"},
  {"id": "MED10-019", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Zgodnie z zasadami ergonomii masażysta, wykonując techniki na dużych powierzchniach ciała, powinien", "odpowiedzi": {"A": "pracować w pozycji wykrocznej z wyprostowanymi plecami, wykorzystując ciężar ciała", "B": "ustawić stół jak najniżej i pracować w głębokim przysiadzie", "C": "stać ze złączonymi stopami i generować siłę głównie z nadgarstków", "D": "pochylać się nad pacjentem z kręgosłupem zgiętym w odcinku lędźwiowym"}, "poprawna": "A", "wyjasnienie": "Pozycja wykroczna i przenoszenie ciężaru ciała zmniejszają obciążenie kręgosłupa i rąk masażysty.", "zrodlo": "MED.10.1.5"},
  {"id": "MED10-020", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Pacjentowi z bólem kręgosłupa lędźwiowego po zabiegu w leżeniu tyłem należy pomóc zejść ze stołu", "odpowiedzi": {"A": "przez szybki skłon tułowia w przód z wyprostowanymi kolanami", "B": "przez bezpośrednie uniesienie tułowia do siadu prostego z pociąganiem za przedramiona", "C": "przez przetoczenie się na brzuch i zsunięcie nogami w dół", "D": "przez obrót na bok, opuszczenie nóg poza krawędź stołu i odepchnięcie się rękami do siadu"}, "poprawna": "D", "wyjasnienie": "Przejście do siadu przez leżenie bokiem minimalizuje obciążenie kręgosłupa lędźwiowego. To zasada bezpiecznego przemieszczania pacjenta.", "zrodlo": "MED.10.1.5"},
  {"id": "MED10-021", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Do patogenów alarmowych zalicza się", "odpowiedzi": {"A": "gronkowca złocistego opornego na metycylinę (MRSA)", "B": "pałeczki kwasu mlekowego z rodzaju Lactobacillus", "C": "gronkowca naskórkowego wrażliwego na antybiotyki", "D": "bakterie prawidłowej flory jamy ustnej"}, "poprawna": "A", "wyjasnienie": "Patogeny alarmowe to drobnoustroje szczególnie niebezpieczne lub wielooporne na antybiotyki, np. MRSA, które wymagają zgłoszenia i nadzoru.", "zrodlo": "MED.10.1.4"},
  {"id": "MED10-022", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Urządzenia elektrycznego pod napięciem nie wolno gasić", "odpowiedzi": {"A": "gaśnicą proszkową", "B": "gaśnicą gazową z czystym środkiem gaśniczym", "C": "wodą", "D": "gaśnicą śniegową (CO₂)"}, "poprawna": "C", "wyjasnienie": "Woda przewodzi prąd i grozi porażeniem gaszącego. Do urządzeń pod napięciem używa się gaśnic proszkowych lub śniegowych.", "zrodlo": "MED.10.1.1"},
  {"id": "MED10-023", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Główną funkcją mięśnia czworogłowego uda jest", "odpowiedzi": {"A": "przywodzenie uda", "B": "prostowanie stawu kolanowego", "C": "zginanie stawu kolanowego", "D": "rotacja wewnętrzna podudzia"}, "poprawna": "B", "wyjasnienie": "Mięsień czworogłowy uda to główny prostownik kolana. Jego głowa prosta dodatkowo zgina staw biodrowy.", "zrodlo": "MED.10.2.11"},
  {"id": "MED10-024", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Przyczep końcowy mięśnia dwugłowego ramienia znajduje się na", "odpowiedzi": {"A": "nadkłykciu przyśrodkowym kości ramiennej", "B": "guzowatości kości łokciowej", "C": "wyrostku łokciowym kości łokciowej", "D": "guzowatości kości promieniowej"}, "poprawna": "D", "wyjasnienie": "Mięsień dwugłowy ramienia kończy się na guzowatości kości promieniowej (i rozcięgnem na powięzi przedramienia). Na guzowatości łokciowej kończy się mięsień ramienny.", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-025", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Mięśniem prostującym staw łokciowy jest mięsień", "odpowiedzi": {"A": "ramienno-promieniowy", "B": "trójgłowy ramienia", "C": "ramienny", "D": "dwugłowy ramienia"}, "poprawna": "B", "wyjasnienie": "Mięsień trójgłowy ramienia (z przyczepem na wyrostku łokciowym) prostuje łokieć. Pozostałe wymienione mięśnie są zginaczami.", "zrodlo": "MED.10.2.11"},
  {"id": "MED10-026", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Mięsień najszerszy grzbietu wykonuje w stawie ramiennym", "odpowiedzi": {"A": "unoszenie łopatki i odwodzenie ramienia", "B": "odwodzenie i rotację zewnętrzną ramienia", "C": "zgięcie ramienia z rotacją zewnętrzną", "D": "przywodzenie, wyprost i rotację wewnętrzną ramienia"}, "poprawna": "D", "wyjasnienie": "Mięsień najszerszy grzbietu przyczepia się do grzebienia guzka mniejszego kości ramiennej. Przywodzi, prostuje i rotuje ramię do wewnątrz.", "zrodlo": "MED.10.2.11"},
  {"id": "MED10-027", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "W skład stożka rotatorów nie wchodzi mięsień", "odpowiedzi": {"A": "obły większy", "B": "podłopatkowy", "C": "podgrzebieniowy", "D": "nadgrzebieniowy"}, "poprawna": "A", "wyjasnienie": "Stożek rotatorów tworzą mięśnie: nadgrzebieniowy, podgrzebieniowy, obły mniejszy i podłopatkowy. Obły większy do niego nie należy.", "zrodlo": "MED.10.2.8"},
  {"id": "MED10-028", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Mięsień czworoboczny jest unerwiony przez nerw", "odpowiedzi": {"A": "grzbietowy łopatki", "B": "piersiowo-grzbietowy", "C": "dodatkowy (XI nerw czaszkowy)", "D": "piersiowy długi"}, "poprawna": "C", "wyjasnienie": "Mięsień czworoboczny (i mostkowo-obojczykowo-sutkowy) unerwia nerw dodatkowy. Nerw grzbietowy łopatki unerwia mięśnie równoległoboczne, a nerw piersiowy długi mięsień zębaty przedni.", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-029", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Nadgarstek człowieka zbudowany jest z", "odpowiedzi": {"A": "14 kości", "B": "8 kości", "C": "5 kości", "D": "7 kości"}, "poprawna": "B", "wyjasnienie": "Nadgarstek tworzy 8 kości ułożonych w dwóch szeregach. 5 to liczba kości śródręcza, 7 kości stępu, a 14 paliczków ręki.", "zrodlo": "MED.10.2.8"},
  {"id": "MED10-030", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Najbardziej wystający wyrostek kolczysty u podstawy szyi, łatwo wyczuwalny palpacyjnie, należy zwykle do kręgu", "odpowiedzi": {"A": "Th12", "B": "C4", "C": "C1", "D": "C7"}, "poprawna": "D", "wyjasnienie": "Kręg C7 nazywany jest kręgiem wystającym. Jego wyrostek kolczysty to ważny punkt orientacyjny w palpacji.", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-031", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Przy swobodnie opuszczonych kończynach górnych kąt dolny łopatki znajduje się na wysokości wyrostka kolczystego kręgu", "odpowiedzi": {"A": "Th3", "B": "Th12", "C": "Th7", "D": "L1"}, "poprawna": "C", "wyjasnienie": "Kąt dolny łopatki leży orientacyjnie na wysokości Th7, a grzebień łopatki na wysokości Th3.", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-032", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Linia łącząca najwyżej położone punkty grzebieni biodrowych przecina kręgosłup na wysokości kręgu", "odpowiedzi": {"A": "L4", "B": "Th12", "C": "S2", "D": "L1"}, "poprawna": "A", "wyjasnienie": "Linia międzygrzebieniowa wskazuje poziom L4 (L4/L5). Kolce biodrowe tylne górne leżą na wysokości S2.", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-033", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Staw biodrowy pod względem kształtu powierzchni stawowych jest stawem", "odpowiedzi": {"A": "obrotowym", "B": "zawiasowym", "C": "kulistym panewkowym", "D": "siodełkowym"}, "poprawna": "C", "wyjasnienie": "Głowa kości udowej osadzona jest głęboko w panewce, stąd staw kulisty panewkowy (orzechowy) o trzech osiach ruchu.", "zrodlo": "MED.10.2.8"},
  {"id": "MED10-034", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Przykładem stawu siodełkowego jest staw", "odpowiedzi": {"A": "nadgarstkowo-śródręczny kciuka", "B": "międzypaliczkowy bliższy palca II", "C": "promieniowo-łokciowy bliższy", "D": "ramienny"}, "poprawna": "A", "wyjasnienie": "Staw nadgarstkowo-śródręczny kciuka jest siodełkowy. Ramienny to staw kulisty, promieniowo-łokciowy bliższy obrotowy, a międzypaliczkowy zawiasowy.", "zrodlo": "MED.10.2.8"},
  {"id": "MED10-035", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Więzadło krzyżowe przednie stawu kolanowego ogranicza przede wszystkim", "odpowiedzi": {"A": "szpotawienie stawu kolanowego", "B": "przesuw piszczeli do przodu względem kości udowej", "C": "koślawienie stawu kolanowego", "D": "przesuw piszczeli do tyłu względem kości udowej"}, "poprawna": "B", "wyjasnienie": "Więzadło krzyżowe przednie (ACL) zapobiega przedniemu przemieszczeniu piszczeli. Tylne (PCL) ogranicza przesuw do tyłu, a więzadła poboczne ograniczają koślawienie i szpotawienie.", "zrodlo": "MED.10.2.8"},
  {"id": "MED10-036", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Naskórek zbudowany jest z nabłonka", "odpowiedzi": {"A": "wielowarstwowego płaskiego nierogowaciejącego", "B": "jednowarstwowego płaskiego", "C": "przejściowego", "D": "wielowarstwowego płaskiego rogowaciejącego"}, "poprawna": "D", "wyjasnienie": "Naskórek to nabłonek wielowarstwowy płaski rogowaciejący. Nabłonek nierogowaciejący wyściela np. jamę ustną, a przejściowy pęcherz moczowy.", "zrodlo": "MED.10.2.8"},
  {"id": "MED10-037", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Receptorami reagującymi na wibrację i silny ucisk, położonymi głęboko w skórze i tkance podskórnej, są", "odpowiedzi": {"A": "wolne zakończenia nerwowe", "B": "ciałka dotykowe (Meissnera)", "C": "ciałka blaszkowate (Vatera-Paciniego)", "D": "łąkotki dotykowe (Merkla)"}, "poprawna": "C", "wyjasnienie": "Ciałka Vatera-Paciniego odbierają wibrację i głęboki ucisk. Ciałka Meissnera reagują na lekki dotyk, a wolne zakończenia nerwowe głównie na ból i temperaturę.", "zrodlo": "MED.10.2.12"},
  {"id": "MED10-038", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Receptorem rejestrującym zmiany długości mięśnia i szybkość jego rozciągania jest", "odpowiedzi": {"A": "ciałko blaszkowate Paciniego", "B": "ciałko dotykowe Meissnera", "C": "narząd ścięgnisty Golgiego", "D": "wrzeciono nerwowo-mięśniowe"}, "poprawna": "D", "wyjasnienie": "Wrzeciona mięśniowe mierzą długość i tempo rozciągania mięśnia. Narząd ścięgnisty Golgiego rejestruje napięcie ścięgna.", "zrodlo": "MED.10.2.11"},
  {"id": "MED10-039", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Odruch kolanowy jest przykładem odruchu", "odpowiedzi": {"A": "monosynaptycznego na rozciąganie", "B": "polisynaptycznego zginania (obronnego)", "C": "warunkowego, wyuczonego", "D": "autonomicznego trzewno-trzewnego"}, "poprawna": "A", "wyjasnienie": "Uderzenie w więzadło rzepki rozciąga mięsień czworogłowy. Pobudzenie wrzecion przechodzi jedną synapsą w rdzeniu na motoneuron.", "zrodlo": "MED.10.2.12"},
  {"id": "MED10-040", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Drogą odśrodkową łuku odruchowego jest", "odpowiedzi": {"A": "neuron czuciowy (aferentny)", "B": "neuron ruchowy (eferentny) prowadzący impuls do efektora", "C": "receptor odbierający bodziec", "D": "neuron pośredniczący w rdzeniu kręgowym"}, "poprawna": "B", "wyjasnienie": "Łuk odruchowy tworzą kolejno: receptor, droga dośrodkowa (czuciowa), ośrodek, droga odśrodkowa (ruchowa) i efektor.", "zrodlo": "MED.10.2.12"},
  {"id": "MED10-041", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Skurcz mięśnia, w którym rośnie napięcie, a długość mięśnia pozostaje stała, to skurcz", "odpowiedzi": {"A": "auksotoniczny", "B": "ekscentryczny", "C": "izotoniczny", "D": "izometryczny"}, "poprawna": "D", "wyjasnienie": "W skurczu izometrycznym nie dochodzi do ruchu w stawie. Izotoniczny zmienia długość przy stałym napięciu, a ekscentryczny zachodzi przy wydłużaniu mięśnia.", "zrodlo": "MED.10.2.11"},
  {"id": "MED10-042", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Bezpośrednim sygnałem umożliwiającym połączenie aktyny z miozyną jest uwolnienie z siateczki sarkoplazmatycznej jonów", "odpowiedzi": {"A": "wapnia", "B": "chloru", "C": "sodu", "D": "potasu"}, "poprawna": "A", "wyjasnienie": "Jony Ca²⁺ wiążą się z troponiną i odsłaniają miejsca wiązania miozyny na aktynie, co inicjuje skurcz.", "zrodlo": "MED.10.2.11"},
  {"id": "MED10-043", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Włókna mięśniowe typu I (czerwone)", "odpowiedzi": {"A": "kurczą się szybko, pracują beztlenowo i szybko się męczą", "B": "kurczą się szybko, pracują tlenowo i mają mało mitochondriów", "C": "kurczą się wolno, pracują głównie tlenowo i są odporne na zmęczenie", "D": "nie zawierają mioglobiny i dominują w mięśniach sprinterów"}, "poprawna": "C", "wyjasnienie": "Włókna typu I są bogate w mioglobinę i mitochondria, więc są wytrzymałe. Dominują np. w mięśniach posturalnych i u maratończyków.", "zrodlo": "MED.10.2.10"},
  {"id": "MED10-044", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Przewód piersiowy uchodzi do", "odpowiedzi": {"A": "żyły głównej dolnej", "B": "lewego kąta żylnego", "C": "prawego kąta żylnego", "D": "zbiornika mleczu"}, "poprawna": "B", "wyjasnienie": "Przewód piersiowy zbiera chłonkę z większości ciała i uchodzi do lewego kąta żylnego (zbieg żyły szyjnej wewnętrznej i podobojczykowej). Zbiornik mleczu jest jego początkiem.", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-045", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Przewód chłonny prawy zbiera chłonkę z", "odpowiedzi": {"A": "całej prawej połowy ciała, łącznie z prawą kończyną dolną", "B": "lewej połowy głowy, szyi i lewej kończyny górnej", "C": "obu kończyn dolnych i jamy brzusznej", "D": "prawej połowy głowy i szyi, prawej kończyny górnej i prawej połowy klatki piersiowej"}, "poprawna": "D", "wyjasnienie": "Prawy przewód chłonny drenuje górną prawą ćwiartkę ciała. Pozostałe obszary drenuje przewód piersiowy.", "zrodlo": "MED.10.2.13"},
  {"id": "MED10-046", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Krew utlenowana z płuc wpływa do serca", "odpowiedzi": {"A": "żyłami płucnymi do lewego przedsionka", "B": "tętnicami płucnymi do prawego przedsionka", "C": "żyłami głównymi do prawego przedsionka", "D": "żyłami płucnymi do prawej komory"}, "poprawna": "A", "wyjasnienie": "Żyły płucne prowadzą krew utlenowaną do lewego przedsionka. Następnie płynie ona do lewej komory i aorty.", "zrodlo": "MED.10.2.13"},
  {"id": "MED10-047", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Tętno na nadgarstku najczęściej bada się na tętnicy", "odpowiedzi": {"A": "ramiennej", "B": "promieniowej", "C": "łokciowej", "D": "pachowej"}, "poprawna": "B", "wyjasnienie": "Tętnica promieniowa leży powierzchownie po stronie kciukowej nadgarstka i to tam najczęściej bada się tętno.", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-048", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Najdłuższą żyłą powierzchowną kończyny dolnej, biegnącą po jej stronie przyśrodkowej, jest żyła", "odpowiedzi": {"A": "podkolanowa", "B": "piszczelowa przednia", "C": "odpiszczelowa", "D": "odstrzałkowa"}, "poprawna": "C", "wyjasnienie": "Żyła odpiszczelowa biegnie od przyśrodkowej strony stopy do żyły udowej w pachwinie. Odstrzałkowa uchodzi do podkolanowej.", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-049", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Nerw kulszowy dzieli się (najczęściej w okolicy dołu podkolanowego) na nerwy", "odpowiedzi": {"A": "udowy i zasłonowy", "B": "piszczelowy i strzałkowy wspólny", "C": "piszczelowy i udowy", "D": "łydkowy i skórny boczny uda"}, "poprawna": "B", "wyjasnienie": "Nerw kulszowy pochodzi ze splotu krzyżowego i jest najgrubszym nerwem ciała. Rozdziela się na nerw piszczelowy i strzałkowy wspólny.", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-050", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Mięsień czworogłowy uda unerwiony jest przez nerw", "odpowiedzi": {"A": "kulszowy", "B": "pośladkowy górny", "C": "zasłonowy", "D": "udowy"}, "poprawna": "D", "wyjasnienie": "Nerw udowy ze splotu lędźwiowego unerwia mięsień czworogłowy i krawiecki. Nerw zasłonowy unerwia przywodziciele.", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-051", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Podstawowym mięśniem wdechowym jest", "odpowiedzi": {"A": "przepona", "B": "mięsień międzyżebrowy wewnętrzny", "C": "mięsień mostkowo-obojczykowo-sutkowy", "D": "mięsień prosty brzucha"}, "poprawna": "A", "wyjasnienie": "Przepona wykonuje większość pracy wdechowej. Mięsień mostkowo-obojczykowo-sutkowy jest pomocniczym mięśniem wdechowym, a międzyżebrowe wewnętrzne i mięśnie brzucha wspomagają wydech.", "zrodlo": "MED.10.2.13"},
  {"id": "MED10-052", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Przeponę unerwia nerw", "odpowiedzi": {"A": "piersiowy długi", "B": "błędny", "C": "przeponowy", "D": "międzyżebrowy XII"}, "poprawna": "C", "wyjasnienie": "Nerw przeponowy pochodzi ze splotu szyjnego (C3–C5). Dlatego uszkodzenie wysokiego odcinka rdzenia szyjnego może porazić oddychanie.", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-053", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Hormonem obniżającym stężenie glukozy we krwi jest", "odpowiedzi": {"A": "kortyzol", "B": "glukagon", "C": "insulina", "D": "adrenalina"}, "poprawna": "C", "wyjasnienie": "Insulinę wydzielają komórki B wysp trzustki i obniża ona glikemię. Glukagon, adrenalina i kortyzol podnoszą stężenie glukozy.", "zrodlo": "MED.10.2.13"},
  {"id": "MED10-054", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Parathormon wydzielany przez przytarczyce reguluje", "odpowiedzi": {"A": "gospodarkę wapniowo-fosforanową", "B": "stężenie glukozy we krwi", "C": "gospodarkę wodną przez zagęszczanie moczu", "D": "tempo podstawowej przemiany materii"}, "poprawna": "A", "wyjasnienie": "Parathormon podnosi stężenie wapnia we krwi. Gospodarkę wodną reguluje wazopresyna, a tempo przemiany materii hormony tarczycy.", "zrodlo": "MED.10.2.13"},
  {"id": "MED10-055", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Pobudzenie części przywspółczulnej autonomicznego układu nerwowego powoduje", "odpowiedzi": {"A": "przyspieszenie czynności serca i rozszerzenie oskrzeli", "B": "zwolnienie czynności serca i nasilenie perystaltyki jelit", "C": "wzrost ciśnienia tętniczego i rozpad glikogenu w wątrobie", "D": "rozszerzenie źrenic i zahamowanie perystaltyki"}, "poprawna": "B", "wyjasnienie": "Układ przywspółczulny odpowiada za odpoczynek i trawienie. Pozostałe reakcje są typowe dla pobudzenia współczulnego.", "zrodlo": "MED.10.2.12"},
  {"id": "MED10-056", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Płaszczyzna strzałkowa pośrodkowa dzieli ciało człowieka na część", "odpowiedzi": {"A": "bliższą i dalszą", "B": "przednią i tylną", "C": "górną i dolną", "D": "prawą i lewą"}, "poprawna": "D", "wyjasnienie": "Płaszczyzna strzałkowa przebiega od przodu do tyłu. Na część przednią i tylną dzieli płaszczyzna czołowa, a na górną i dolną poprzeczna.", "zrodlo": "MED.10.2.7"},
  {"id": "MED10-057", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Określenie topograficzne „dystalny” (dalszy) oznacza położony", "odpowiedzi": {"A": "bliżej linii pośrodkowej ciała", "B": "bliżej powierzchni ciała", "C": "dalej od tułowia lub nasady kończyny", "D": "bliżej głowy"}, "poprawna": "C", "wyjasnienie": "Dystalny to dalszy od tułowia, np. dłoń względem łokcia. Przeciwieństwem jest proksymalny (bliższy).", "zrodlo": "MED.10.2.7"},
  {"id": "MED10-058", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Ruch odwodzenia w stawie ramiennym (w pozycji anatomicznej) odbywa się w płaszczyźnie", "odpowiedzi": {"A": "strzałkowej, wokół osi podłużnej", "B": "czołowej, wokół osi strzałkowej", "C": "strzałkowej, wokół osi poprzecznej", "D": "poprzecznej, wokół osi podłużnej"}, "poprawna": "B", "wyjasnienie": "Odwodzenie i przywodzenie zachodzą w płaszczyźnie czołowej wokół osi strzałkowej. Zgięcie i wyprost zachodzą w płaszczyźnie strzałkowej wokół osi poprzecznej.", "zrodlo": "MED.10.2.11"},
  {"id": "MED10-059", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Powięź w układzie ruchu", "odpowiedzi": {"A": "wytwarza maź stawową odżywiającą chrząstkę", "B": "stanowi wyłącznie warstwę izolacyjną bez wpływu na ruch", "C": "jest odmianą tkanki kostnej usztywniającą mięsień", "D": "otacza mięśnie i ich grupy, przenosi napięcia i łączy struktury w łańcuchy funkcjonalne"}, "poprawna": "D", "wyjasnienie": "Powięź to tkanka łączna włóknista. Przenosi siły między mięśniami i decyduje o ciągłości napięć w ciele, na czym opiera się m.in. masaż tensegracyjny.", "zrodlo": "MED.10.2.8"},
  {"id": "MED10-060", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Powierzchnie stawowe większości stawów maziowych pokrywa chrząstka", "odpowiedzi": {"A": "szklista", "B": "sprężysta", "C": "kostniejąca", "D": "włóknista"}, "poprawna": "A", "wyjasnienie": "Chrząstka szklista pokrywa powierzchnie stawowe. Chrząstka włóknista buduje m.in. łąkotki i krążki międzykręgowe, a sprężysta małżowinę uszną.", "zrodlo": "MED.10.2.8"},
  {"id": "MED10-061", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Osłonka mielinowa włókna nerwowego", "odpowiedzi": {"A": "wytwarza neuroprzekaźnik w synapsie", "B": "spowalnia przewodzenie impulsu", "C": "odbiera bodźce ze środowiska zewnętrznego", "D": "przyspiesza przewodzenie impulsu (przewodzenie skokowe)"}, "poprawna": "D", "wyjasnienie": "Mielina izoluje akson, dzięki czemu impuls przeskakuje między przewężeniami Ranviera, co znacznie przyspiesza przewodzenie.", "zrodlo": "MED.10.2.10"},
  {"id": "MED10-062", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Prawidłowa kolejność podstawowych technik w masażu klasycznym to", "odpowiedzi": {"A": "głaskanie – rozcieranie – oklepywanie – ugniatanie – wibracja", "B": "rozcieranie – głaskanie – ugniatanie – wibracja – oklepywanie", "C": "głaskanie – rozcieranie – ugniatanie – oklepywanie – wibracja", "D": "głaskanie – ugniatanie – rozcieranie – oklepywanie – wibracja"}, "poprawna": "C", "wyjasnienie": "Masaż klasyczny prowadzi się od technik powierzchownych do głębszych. Rozpoczyna się i kończy głaskaniem.", "zrodlo": "MED.10.2.15"},
  {"id": "MED10-063", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Masaż klasyczny rozpoczyna się techniką głaskania, ponieważ", "odpowiedzi": {"A": "rozbija zrosty w głębokich warstwach tkanek", "B": "przyzwyczaja receptory skóry do dotyku i przygotowuje tkanki do dalszych technik", "C": "pozwala ocenić siłę mięśniową w skali Lovetta", "D": "najsilniej pobudza mięśnie do skurczu"}, "poprawna": "B", "wyjasnienie": "Głaskanie jest techniką powierzchowną i łagodną. Zapoznaje pacjenta z dotykiem masażysty i poprawia odpływ żylny i limfatyczny.", "zrodlo": "MED.10.2.15"},
  {"id": "MED10-064", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Technika polegająca na uchwyceniu mięśnia, uniesieniu go od podłoża i wyciskaniu ruchem przypominającym wyżymanie to", "odpowiedzi": {"A": "ugniatanie", "B": "roztrząsanie", "C": "rozcieranie", "D": "wałkowanie"}, "poprawna": "A", "wyjasnienie": "Ugniatanie oddziałuje głównie na tkankę mięśniową: poprawia jej ukrwienie i odżywienie oraz usuwa produkty przemiany materii.", "zrodlo": "MED.10.2.15"},
  {"id": "MED10-065", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Techniką masażu klasycznego szczególnie przydatną w okolicy stawów i w miejscach zrostów tkanki podskórnej jest", "odpowiedzi": {"A": "rozcieranie", "B": "głaskanie", "C": "roztrząsanie", "D": "oklepywanie"}, "poprawna": "A", "wyjasnienie": "Rozcieranie (ruchy koliste lub spiralne z przesuwaniem tkanek względem podłoża) rozluźnia zrosty i poprawia elastyczność tkanek okołostawowych.", "zrodlo": "MED.10.2.15"},
  {"id": "MED10-066", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Oklepywania nie wykonuje się w okolicy", "odpowiedzi": {"A": "mięśni pośladkowych", "B": "lędźwiowej nad nerkami", "C": "tylnej grupy mięśni uda", "D": "mięśni łydki"}, "poprawna": "B", "wyjasnienie": "Okolica nerek jest wrażliwa na wstrząsy, dlatego techniki uderzeniowe są tam przeciwwskazane. Oklepywanie stosuje się na dużych grupach mięśniowych.", "zrodlo": "MED.10.2.15"},
  {"id": "MED10-067", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Głaskanie w masażu klasycznym kończyn wykonuje się", "odpowiedzi": {"A": "odsercowo, od tułowia ku palcom", "B": "w dowolnym kierunku, bo nie wpływa ono na krążenie", "C": "poprzecznie do przebiegu włókien mięśniowych", "D": "dosercowo, zgodnie z kierunkiem odpływu krwi żylnej i chłonki"}, "poprawna": "D", "wyjasnienie": "Głaskanie dosercowe ułatwia odpływ krwi żylnej i chłonki, dlatego zawsze prowadzi się je w kierunku serca.", "zrodlo": "MED.10.2.15"},
  {"id": "MED10-068", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Roztrząsanie stosuje się w celu", "odpowiedzi": {"A": "wywołania silnego przekrwienia skóry", "B": "rozbicia zrostów w obrębie torebki stawowej", "C": "rozluźnienia mięśni i obniżenia ich napięcia", "D": "zwiększenia napięcia mięśnia przed wysiłkiem siłowym"}, "poprawna": "C", "wyjasnienie": "Roztrząsanie wykonuje się na rozluźnionym mięśniu lub kończynie. Działa uspokajająco i rozluźniająco.", "zrodlo": "MED.10.2.15"},
  {"id": "MED10-069", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Bezpośrednim miejscowym efektem prawidłowo wykonanego masażu klasycznego jest", "odpowiedzi": {"A": "przekrwienie skóry i wzrost jej ciepłoty", "B": "obniżenie temperatury masowanych tkanek", "C": "zwężenie naczyń skórnych i zblednięcie skóry", "D": "wzrost napięcia spoczynkowego masowanych mięśni"}, "poprawna": "A", "wyjasnienie": "Masaż rozszerza naczynia włosowate i uwalnia substancje naczyniorozszerzające (np. histaminę), co daje rumień i ocieplenie skóry.", "zrodlo": "MED.10.2.15"},
  {"id": "MED10-070", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Naświetlanie lampą Sollux (promieniowanie podczerwone) wykonane przed masażem ma na celu", "odpowiedzi": {"A": "wywołanie rumienia fotochemicznego", "B": "ogrzanie i rozluźnienie tkanek, co ułatwia wykonanie masażu", "C": "zwężenie naczyń krwionośnych skóry", "D": "znieczulenie okolicy przez działanie zimna"}, "poprawna": "B", "wyjasnienie": "Promieniowanie podczerwone działa cieplnie: rozszerza naczynia i zmniejsza napięcie mięśni. Rumień fotochemiczny wywołuje promieniowanie UV.", "zrodlo": "MED.10.2.16"},
  {"id": "MED10-071", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Masażu nie wykonuje się na okolicy ciała bezpośrednio po", "odpowiedzi": {"A": "naświetlaniu lampą Sollux", "B": "zabiegu cieplnym z użyciem okładu żelowego", "C": "naświetlaniu promieniowaniem UV w dawce rumieniowej", "D": "kąpieli wirowej kończyny"}, "poprawna": "C", "wyjasnienie": "Skóra po dawce rumieniowej UV jest podrażniona i nadwrażliwa. Zabiegi cieplne natomiast dobrze przygotowują tkanki do masażu.", "zrodlo": "MED.10.2.16"},
  {"id": "MED10-072", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Krioterapia miejscowa ma działanie przede wszystkim", "odpowiedzi": {"A": "rozgrzewające i przekrwienne", "B": "zwiększające napięcie mięśni spastycznych", "C": "pobudzające wydzielanie potu", "D": "przeciwbólowe i przeciwobrzękowe"}, "poprawna": "D", "wyjasnienie": "Zimno zmniejsza przewodnictwo nerwowe i przepuszczalność naczyń, więc działa przeciwbólowo i ogranicza obrzęk.", "zrodlo": "MED.10.2.16"},
  {"id": "MED10-073", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Prądy TENS stosuje się w fizykoterapii głównie w celu", "odpowiedzi": {"A": "przeciwbólowym", "B": "stymulacji mięśni całkowicie odnerwionych", "C": "wprowadzenia leku przez skórę", "D": "głębokiego przegrzania tkanek"}, "poprawna": "A", "wyjasnienie": "TENS (przezskórna elektryczna stymulacja nerwów) działa przeciwbólowo, m.in. przez mechanizm bramki kontrolnej. Lek wprowadza jonoforeza, a przegrzewa diatermia.", "zrodlo": "MED.10.2.16"},
  {"id": "MED10-074", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Przeciwwskazaniem do zabiegów elektroterapii w okolicy klatki piersiowej jest", "odpowiedzi": {"A": "przebyte przed laty skręcenie stawu skokowego", "B": "wszczepiony stymulator (rozrusznik) serca", "C": "zwiększone napięcie mięśni przykręgosłupowych", "D": "nadwaga"}, "poprawna": "B", "wyjasnienie": "Prąd elektryczny może zakłócić pracę rozrusznika serca, dlatego jest to przeciwwskazanie do elektroterapii.", "zrodlo": "MED.10.2.16"},
  {"id": "MED10-075", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Ćwiczenia czynne w odciążeniu stosuje się, gdy siła mięśnia w skali Lovetta wynosi", "odpowiedzi": {"A": "3", "B": "5", "C": "2", "D": "0"}, "poprawna": "C", "wyjasnienie": "Przy sile 2 mięsień wykonuje pełny ruch tylko po wyeliminowaniu grawitacji. Przy sile 0 stosuje się ćwiczenia bierne, przy 3 czynne wolne, a przy 4–5 z oporem.", "zrodlo": "MED.10.2.16"},
  {"id": "MED10-076", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Pacjentowi z kończyną unieruchomioną w opatrunku gipsowym w celu zapobiegania zanikom mięśni zaleca się ćwiczenia", "odpowiedzi": {"A": "redresyjne", "B": "czynne z oporem w pełnym zakresie ruchu", "C": "bierne w unieruchomionym stawie", "D": "izometryczne"}, "poprawna": "D", "wyjasnienie": "Ćwiczenia izometryczne napinają mięsień bez ruchu w stawie, więc można je wykonywać w opatrunku gipsowym.", "zrodlo": "MED.10.2.16"},
  {"id": "MED10-077", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Zawód technika masażysty jest od 2024 r. regulowany przepisami ustawy", "odpowiedzi": {"A": "o zawodach lekarza i lekarza dentysty", "B": "o Państwowym Ratownictwie Medycznym", "C": "o niektórych zawodach medycznych", "D": "o zawodzie fizjoterapeuty"}, "poprawna": "C", "wyjasnienie": "Ustawa z 17 sierpnia 2023 r. o niektórych zawodach medycznych (w życiu od 26 marca 2024 r.) objęła m.in. zawód technika masażysty.", "zrodlo": "MED.10.2.1"},
  {"id": "MED10-078", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Zgodnie z ustawą o prawach pacjenta i Rzeczniku Praw Pacjenta dokumentację medyczną przechowuje się co do zasady przez", "odpowiedzi": {"A": "5 lat od dnia ostatniego zabiegu", "B": "50 lat od dnia urodzenia pacjenta", "C": "10 lat od dnia założenia dokumentacji", "D": "20 lat od końca roku kalendarzowego, w którym dokonano ostatniego wpisu"}, "poprawna": "D", "wyjasnienie": "Ogólny okres przechowywania dokumentacji medycznej to 20 lat od końca roku ostatniego wpisu. Dla niektórych przypadków przepisy przewidują wyjątki.", "zrodlo": "MED.10.2.5"},
  {"id": "MED10-079", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Instytucją finansującą świadczenia zdrowotne w ramach powszechnego ubezpieczenia zdrowotnego jest", "odpowiedzi": {"A": "Zakład Ubezpieczeń Społecznych", "B": "Narodowy Fundusz Zdrowia", "C": "Państwowa Inspekcja Sanitarna", "D": "Rzecznik Praw Pacjenta"}, "poprawna": "B", "wyjasnienie": "NFZ zawiera umowy z podmiotami leczniczymi i płaci za świadczenia. ZUS pobiera składkę zdrowotną, ale nie finansuje świadczeń.", "zrodlo": "MED.10.2.2"},
  {"id": "MED10-080", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Badania przesiewowe, np. mammografia, są przykładem profilaktyki", "odpowiedzi": {"A": "II fazy (wczesne wykrywanie choroby)", "B": "III fazy (zapobieganie powikłaniom i rehabilitacja)", "C": "fazy wczesnej (kształtowanie środowiska przed pojawieniem się czynników ryzyka)", "D": "I fazy (zapobieganie zachorowaniu)"}, "poprawna": "A", "wyjasnienie": "Profilaktyka II fazy wykrywa chorobę we wczesnym, często bezobjawowym stadium. I faza zapobiega zachorowaniu, a III ogranicza skutki choroby.", "zrodlo": "MED.10.2.6"},
  {"id": "MED10-081", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Dokumentem uznawanym za podstawę współczesnej koncepcji promocji zdrowia jest", "odpowiedzi": {"A": "Konwencja Genewska", "B": "Karta Praw Pacjenta", "C": "Karta Ottawska (1986)", "D": "Deklaracja Helsińska"}, "poprawna": "C", "wyjasnienie": "Karta Ottawska WHO zdefiniowała promocję zdrowia jako proces umożliwiania ludziom zwiększenia kontroli nad własnym zdrowiem. Deklaracja Helsińska dotyczy etyki badań medycznych.", "zrodlo": "MED.10.2.6"},
  {"id": "MED10-082", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "W przypadku uzasadnionego podejrzenia przemocy domowej przedstawiciel ochrony zdrowia wszczyna procedurę", "odpowiedzi": {"A": "„Białej Karty”", "B": "„Niebieskiej Karty”", "C": "„Karty DiLO”", "D": "„Zielonej Karty”"}, "poprawna": "B", "wyjasnienie": "Procedura „Niebieskiej Karty” wynika z ustawy o przeciwdziałaniu przemocy domowej i obejmuje m.in. ochronę zdrowia. Karta DiLO dotyczy szybkiej ścieżki onkologicznej.", "zrodlo": "MED.10.2.17"},
  {"id": "MED10-083", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Oznaczenie normy „PN-EN ISO” informuje, że jest to norma", "odpowiedzi": {"A": "europejska, która nie obowiązuje w Polsce", "B": "zakładowa, ustalona przez producenta sprzętu", "C": "wyłącznie polska, bez odpowiednika europejskiego", "D": "międzynarodowa, przyjęta jako europejska i wprowadzona do zbioru Polskich Norm"}, "poprawna": "D", "wyjasnienie": "Przedrostki pokazują drogę normy: ISO (międzynarodowa) → EN (europejska) → PN (Polska Norma, wydawana przez PKN).", "zrodlo": "MED.10.2.18"},
  {"id": "MED10-084", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Wykonując masaż u osoby w podeszłym wieku, masażysta powinien", "odpowiedzi": {"A": "zmniejszyć siłę bodźców ze względu na cienką skórę i możliwą osteoporozę", "B": "stosować wyłącznie techniki głębokie, aby skrócić zabieg", "C": "pominąć wywiad, bo nie wpływa on na przebieg zabiegu", "D": "zwiększyć intensywność oklepywania, by pobudzić krążenie"}, "poprawna": "A", "wyjasnienie": "U osób starszych skóra jest cieńsza, a kości często osłabione, dlatego masaż powinien być łagodniejszy, a wywiad szczególnie dokładny.", "zrodlo": "MED.10.2.14"},
  {"id": "MED10-085", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Tajemnica zawodowa masażysty obejmuje informacje o pacjencie uzyskane w związku z wykonywaniem zawodu i", "odpowiedzi": {"A": "wygasa z chwilą zakończenia serii zabiegów", "B": "obowiązuje wyłącznie w publicznych podmiotach leczniczych", "C": "nie dotyczy rozmów z rodziną pacjenta", "D": "może być uchylona tylko w przypadkach przewidzianych przepisami prawa"}, "poprawna": "D", "wyjasnienie": "Informacje o stanie zdrowia są danymi szczególnie chronionymi (RODO, ustawa o prawach pacjenta). Tajemnica obowiązuje także po zakończeniu terapii.", "zrodlo": "MED.10.2.1"},
  {"id": "MED10-086", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Bezwzględnym przeciwwskazaniem do masażu klasycznego jest", "odpowiedzi": {"A": "stan gorączkowy", "B": "przewlekły ból okolicy lędźwiowej", "C": "obniżone napięcie mięśniowe", "D": "stan po zdjęciu unieruchomienia gipsowego"}, "poprawna": "A", "wyjasnienie": "Gorączka świadczy o ostrym procesie chorobowym. Masaż, zwiększając krążenie, mógłby nasilić stan zapalny i obciążyć organizm.", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-087", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Masaż kończyny dolnej jest przeciwwskazany u pacjenta ze", "odpowiedzi": {"A": "przykurczem mięśni kulszowo-goleniowych", "B": "zanikiem mięśni po unieruchomieniu", "C": "świeżą zakrzepicą żył głębokich", "D": "stanem po skręceniu stawu skokowego w okresie podostrym"}, "poprawna": "C", "wyjasnienie": "Masaż przy świeżej zakrzepicy grozi oderwaniem skrzepliny i zatorowością płucną.", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-088", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Bezwzględnym przeciwwskazaniem do manualnego drenażu limfatycznego jest", "odpowiedzi": {"A": "obrzęk pourazowy po skręceniu stawu skokowego", "B": "zdekompensowana niewydolność serca z obrzękami", "C": "obrzęk limfatyczny kończyny górnej po mastektomii", "D": "obrzęk tłuszczowy (lipoedema)"}, "poprawna": "B", "wyjasnienie": "Drenaż zwiększa powrót płynów do krążenia, co przy niewydolnym sercu grozi przeciążeniem i obrzękiem płuc. Pozostałe obrzęki są wskazaniami.", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-089", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Reumatoidalne zapalenie stawów zwykle rozpoczyna się od", "odpowiedzi": {"A": "symetrycznego zajęcia drobnych stawów rąk i stóp", "B": "zajęcia stawów krzyżowo-biodrowych i kręgosłupa", "C": "ostrego bólu stawu śródstopno-paliczkowego palucha", "D": "zmian w jednym stawie kolanowym po urazie"}, "poprawna": "A", "wyjasnienie": "RZS to przewlekła choroba autoimmunologiczna z symetrycznym zapaleniem drobnych stawów i długą sztywnością poranną. Stawy krzyżowo-biodrowe są typowe dla ZZSK, a paluch dla dny moczanowej.", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-090", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Obraz „kręgosłupa bambusowego” w badaniu radiologicznym jest charakterystyczny dla", "odpowiedzi": {"A": "osteoporozy", "B": "choroby Scheuermanna", "C": "zesztywniającego zapalenia stawów kręgosłupa", "D": "skoliozy idiopatycznej"}, "poprawna": "C", "wyjasnienie": "W ZZSK dochodzi do kostnienia więzadeł i stawów kręgosłupa, co na zdjęciu daje obraz kija bambusowego.", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-091", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Przyczyną dny moczanowej jest", "odpowiedzi": {"A": "autoimmunologiczne zapalenie błony maziowej stawów", "B": "zwyrodnienie chrząstki stawowej z przeciążenia", "C": "niedobór witaminy D prowadzący do rozmiękania kości", "D": "odkładanie się kryształów moczanu sodu w tkankach przy podwyższonym stężeniu kwasu moczowego"}, "poprawna": "D", "wyjasnienie": "Hiperurykemia prowadzi do krystalizacji moczanów w stawach, najczęściej w stawie śródstopno-paliczkowym palucha.", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-092", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Dla choroby zwyrodnieniowej stawów typowy jest", "odpowiedzi": {"A": "nagły, bardzo silny ból z zaczerwienieniem i gorączką", "B": "ból nasilający się przy obciążaniu stawu i krótka (do ok. 30 min) sztywność poranna", "C": "symetryczny obrzęk drobnych stawów rąk z guzkami podskórnymi", "D": "ból spoczynkowy w nocy z wielogodzinną sztywnością poranną"}, "poprawna": "B", "wyjasnienie": "W chorobie zwyrodnieniowej ból ma charakter mechaniczny, a sztywność po odpoczynku jest krótka. Długa sztywność poranna wskazuje na choroby zapalne.", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-093", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Typowym złamaniem w przebiegu osteoporozy jest złamanie", "odpowiedzi": {"A": "kompresyjne trzonu kręgu", "B": "wyrostka łokciowego po bezpośrednim uderzeniu", "C": "kości łódeczkowatej u młodego sportowca", "D": "zmęczeniowe kości śródstopia u biegacza"}, "poprawna": "A", "wyjasnienie": "Złamania osteoporotyczne to m.in. kompresyjne złamania kręgów, złamania szyjki kości udowej i dalszej nasady kości promieniowej, powstające przy niewielkim urazie.", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-094", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Skolioza to", "odpowiedzi": {"A": "spłaszczenie fizjologicznych krzywizn w płaszczyźnie strzałkowej", "B": "trójpłaszczyznowe skrzywienie kręgosłupa z bocznym odchyleniem i rotacją kręgów", "C": "nadmierne pogłębienie kifozy piersiowej", "D": "pogłębienie lordozy lędźwiowej"}, "poprawna": "B", "wyjasnienie": "Skolioza to boczne skrzywienie kręgosłupa z rotacją. Pozostałe odpowiedzi opisują wady w płaszczyźnie strzałkowej: plecy okrągłe, wklęsłe i płaskie.", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-095", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "W masażu u pacjenta ze skoliozą po stronie wklęsłej skrzywienia stosuje się techniki", "odpowiedzi": {"A": "uciskowe na wyrostki kolczyste, by przesunąć kręgi", "B": "pobudzające, ponieważ mięśnie są tam rozciągnięte i osłabione", "C": "rozluźniające, ponieważ mięśnie są tam przykurczone", "D": "wyłącznie oklepywanie, aby wzmocnić mięśnie"}, "poprawna": "C", "wyjasnienie": "Po stronie wklęsłej mięśnie są skrócone, więc się je rozluźnia. Po stronie wypukłej są rozciągnięte i osłabione, więc się je pobudza.", "zrodlo": "MED.10.3.4"},
  {"id": "MED10-096", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "U pacjenta z plecami okrągłymi masażem rozluźniającym należy przede wszystkim opracować mięśnie", "odpowiedzi": {"A": "czworoboczny (część dolną)", "B": "prostownik grzbietu w odcinku piersiowym", "C": "równoległoboczne", "D": "piersiowe większe i mniejsze"}, "poprawna": "D", "wyjasnienie": "W plecach okrągłych mięśnie klatki piersiowej są przykurczone, a mięśnie grzbietu i ściągające łopatki rozciągnięte i osłabione, więc się je pobudza.", "zrodlo": "MED.10.3.4"},
  {"id": "MED10-097", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Spastyczność mięśni po udarze mózgu wynika z uszkodzenia", "odpowiedzi": {"A": "dolnego (obwodowego) neuronu ruchowego", "B": "złącza nerwowo-mięśniowego", "C": "nerwów czuciowych skóry", "D": "górnego (ośrodkowego) neuronu ruchowego"}, "poprawna": "D", "wyjasnienie": "Uszkodzenie dróg ruchowych w OUN znosi hamujący wpływ na odruchy rdzeniowe, co daje wzmożone napięcie typu spastycznego i wygórowane odruchy.", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-098", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "W masażu kończyny z niedowładem spastycznym po udarze mózgu należy unikać", "odpowiedzi": {"A": "delikatnego roztrząsania", "B": "powolnego, rytmicznego głaskania", "C": "oklepywania i intensywnego ugniatania mięśni spastycznych", "D": "ułożenia kończyny w pozycji przeciwdziałającej spastyczności"}, "poprawna": "C", "wyjasnienie": "Silne bodźce mechaniczne mogą nasilić spastyczność, dlatego na mięśnie spastyczne stosuje się techniki łagodne i rozluźniające.", "zrodlo": "MED.10.3.4"},
  {"id": "MED10-099", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Porażenie wiotkie charakteryzuje się", "odpowiedzi": {"A": "objawem Babińskiego i klonusem stopy", "B": "obniżonym napięciem mięśni, osłabieniem lub zniesieniem odruchów i zanikami mięśni", "C": "sztywnością typu rury ołowianej i drżeniem spoczynkowym", "D": "wzmożonym napięciem typu scyzorykowego i wygórowaniem odruchów"}, "poprawna": "B", "wyjasnienie": "Porażenie wiotkie wynika z uszkodzenia obwodowego neuronu ruchowego. Objaw Babińskiego wskazuje na uszkodzenie ośrodkowe, a sztywność z drżeniem na chorobę Parkinsona.", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-100", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Do głównych objawów choroby Parkinsona należą", "odpowiedzi": {"A": "drżenie spoczynkowe, sztywność mięśniowa i spowolnienie ruchowe", "B": "porażenie wiotkie kończyn dolnych i zaburzenia czucia", "C": "męczliwość mięśni nasilająca się w ciągu dnia i opadanie powiek", "D": "napadowy ból jednej połowy twarzy"}, "poprawna": "A", "wyjasnienie": "Chorobę Parkinsona wywołuje zanik neuronów dopaminergicznych istoty czarnej. Męczliwość z opadaniem powiek to objaw miastenii, a napadowy ból twarzy to neuralgia nerwu trójdzielnego.", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-101", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Stwardnienie rozsiane jest chorobą polegającą na", "odpowiedzi": {"A": "kostnieniu więzadeł kręgosłupa", "B": "zwyrodnieniu neuronów dopaminergicznych istoty czarnej", "C": "blokowaniu złącza nerwowo-mięśniowego przez przeciwciała", "D": "demielinizacji włókien nerwowych w ośrodkowym układzie nerwowym"}, "poprawna": "D", "wyjasnienie": "W SM ogniska demielinizacji w mózgu i rdzeniu dają różnorodne objawy neurologiczne o rzutowo-remisyjnym przebiegu.", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-102", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Objaw „ręki opadającej” jest typowy dla uszkodzenia nerwu", "odpowiedzi": {"A": "łokciowego", "B": "pośrodkowego", "C": "promieniowego", "D": "pachowego"}, "poprawna": "C", "wyjasnienie": "Nerw promieniowy unerwia prostowniki nadgarstka i palców. Uszkodzenie nerwu łokciowego daje rękę szponiastą, a pośrodkowego rękę błogosławiącą (małpią).", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-103", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Opadanie stopy i chód „koguci” (brodzący) świadczą o uszkodzeniu nerwu", "odpowiedzi": {"A": "strzałkowego wspólnego", "B": "zasłonowego", "C": "piszczelowego", "D": "udowego"}, "poprawna": "A", "wyjasnienie": "Nerw strzałkowy unerwia mięśnie zginające grzbietowo stopę. Przy jego porażeniu pacjent wysoko unosi kolano, by nie zahaczać stopą o podłoże.", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-104", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Rwa kulszowa najczęściej jest wynikiem", "odpowiedzi": {"A": "zapalenia nerwu udowego po infekcji wirusowej", "B": "ucisku korzeni nerwowych L5–S1 przez przepuklinę krążka międzykręgowego", "C": "ucisku nerwu pośrodkowego w kanale nadgarstka", "D": "zmian zwyrodnieniowych stawu kolanowego"}, "poprawna": "B", "wyjasnienie": "Ból promieniujący wzdłuż tylnej strony kończyny dolnej wynika najczęściej z dyskopatii w dolnym odcinku lędźwiowym, która uciska korzenie tworzące nerw kulszowy.", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-105", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Zespół cieśni kanału nadgarstka spowodowany jest uciskiem nerwu", "odpowiedzi": {"A": "mięśniowo-skórnego", "B": "promieniowego", "C": "łokciowego", "D": "pośrodkowego"}, "poprawna": "D", "wyjasnienie": "Nerw pośrodkowy przechodzi pod troczkiem zginaczy. Ucisk daje drętwienie palców I–III i osłabienie mięśni kłębu kciuka.", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-106", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "„Łopatka skrzydłowata” (odstająca przyśrodkowym brzegiem od klatki piersiowej) jest typowym objawem uszkodzenia nerwu", "odpowiedzi": {"A": "mięśniowo-skórnego", "B": "nadłopatkowego", "C": "piersiowego długiego", "D": "pachowego"}, "poprawna": "C", "wyjasnienie": "Nerw piersiowy długi unerwia mięsień zębaty przedni, który dociska łopatkę do klatki piersiowej.", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-107", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "W przypadku żylaków kończyn dolnych masażysta", "odpowiedzi": {"A": "wykonuje głaskanie odsercowe całej kończyny", "B": "omija okolice zmienionych żylakowo naczyń i nie stosuje na nie technik uciskowych", "C": "oklepuje okolice żylaków, aby wzmocnić ściany naczyń", "D": "intensywnie rozciera żylaki w celu ich zmniejszenia"}, "poprawna": "B", "wyjasnienie": "Silny ucisk może uszkodzić zmienione ściany żył i sprzyjać zakrzepicy, dlatego okolice żylaków się omija, a kończynę masuje się delikatnie, dosercowo.", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-108", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Chromanie przestankowe (ból łydki zmuszający do zatrzymania się podczas chodu) jest typowym objawem", "odpowiedzi": {"A": "miażdżycy zarostowej tętnic kończyn dolnych", "B": "przewlekłej niewydolności żylnej", "C": "zapalenia rozcięgna podeszwowego", "D": "obrzęku limfatycznego kończyny dolnej"}, "poprawna": "A", "wyjasnienie": "Zwężone tętnice nie dostarczają podczas wysiłku wystarczającej ilości krwi do mięśni. Ból ustępuje po krótkim odpoczynku.", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-109", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Drenaż ułożeniowy połączony z oklepywaniem klatki piersiowej stosuje się w celu", "odpowiedzi": {"A": "zwiększenia napięcia przepony", "B": "ułatwienia usuwania zalegającej wydzieliny z drzewa oskrzelowego", "C": "podwyższenia ciśnienia tętniczego", "D": "poprawy krążenia w kończynach dolnych"}, "poprawna": "B", "wyjasnienie": "Ułożenie z wykorzystaniem grawitacji i wstrząsy mechaniczne przesuwają wydzielinę do dużych oskrzeli, skąd łatwiej ją odkrztusić (np. w mukowiscydozie, rozstrzeniach oskrzeli).", "zrodlo": "MED.10.3.7"},
  {"id": "MED10-110", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "W astmie oskrzelowej masaż klatki piersiowej ma przede wszystkim", "odpowiedzi": {"A": "zwiększyć napięcie mięśni szyi i obręczy barkowej", "B": "wywołać skurcz oskrzeli w celu ich wzmocnienia", "C": "rozluźnić pomocnicze mięśnie oddechowe i ułatwić oddychanie", "D": "zastąpić leczenie farmakologiczne"}, "poprawna": "C", "wyjasnienie": "U chorych na astmę mięśnie pomocnicze oddychania są przeciążone i napięte. Masaż je rozluźnia i wspiera ćwiczenia oddechowe, ale nie zastępuje leków.", "zrodlo": "MED.10.3.5"},
  {"id": "MED10-111", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Masaż powłok brzusznych w zaparciach atonicznych wykonuje się zgodnie z przebiegiem jelita grubego, czyli", "odpowiedzi": {"A": "przeciwnie do ruchu wskazówek zegara: w górę po lewej stronie i w dół po prawej", "B": "wyłącznie poprzecznie, od lewej do prawej strony", "C": "promieniście od pępka na zewnątrz", "D": "zgodnie z ruchem wskazówek zegara: w górę po prawej stronie, poprzecznie i w dół po lewej"}, "poprawna": "D", "wyjasnienie": "Okrężnica wstępująca leży po prawej, poprzeczna biegnie w lewo, a zstępująca w dół po lewej, więc masaż zgodnie z ruchem wskazówek zegara wspiera pasaż treści jelitowej.", "zrodlo": "MED.10.3.4"},
  {"id": "MED10-112", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Do klasycznych objawów miejscowego stanu zapalnego nie należy", "odpowiedzi": {"A": "zblednięcie i ochłodzenie skóry", "B": "obrzęk", "C": "ból", "D": "zaczerwienienie"}, "poprawna": "A", "wyjasnienie": "Klasyczne objawy zapalenia to zaczerwienienie, ocieplenie, obrzęk, ból i upośledzenie funkcji.", "zrodlo": "MED.10.3.1"},
  {"id": "MED10-113", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Zanik mięśni z bezczynności polega na", "odpowiedzi": {"A": "zmniejszeniu objętości włókien mięśniowych wskutek ich długotrwałego nieużywania", "B": "zwiększeniu liczby komórek mięśniowych", "C": "zastąpieniu tkanki mięśniowej tkanką nabłonkową", "D": "obumarciu komórek mięśniowych z powodu niedokrwienia"}, "poprawna": "A", "wyjasnienie": "Atrofia z bezczynności występuje np. po unieruchomieniu kończyny. Rozrost to hiperplazja, przemiana tkanki to metaplazja, a obumarcie to martwica.", "zrodlo": "MED.10.3.1"},
  {"id": "MED10-114", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Obrzęk limfatyczny różni się od obrzęku żylnego tym, że", "odpowiedzi": {"A": "zawsze ustępuje całkowicie po nocnym odpoczynku", "B": "jest bogatobiałkowy i z czasem prowadzi do włóknienia tkanek", "C": "występuje wyłącznie obustronnie i symetrycznie", "D": "jest ubogobiałkowy i nie zmienia skóry"}, "poprawna": "B", "wyjasnienie": "Zalegająca w tkankach chłonka zawiera dużo białka, co pobudza rozrost tkanki łącznej i twardnienie obrzęku.", "zrodlo": "MED.10.3.1"},
  {"id": "MED10-115", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "W ostrej fazie (pierwsze 24–72 godziny) po skręceniu stawu skokowego", "odpowiedzi": {"A": "stosuje się okłady rozgrzewające i saunę", "B": "wykonuje się intensywne rozcieranie stawu", "C": "unika się masażu okolicy urazu, a kończynę odciąża się, uciska i unosi", "D": "zaleca się bieganie dla szybszego wchłonięcia krwiaka"}, "poprawna": "C", "wyjasnienie": "W ostrej fazie urazu masaż i ciepło nasilają krwawienie i obrzęk. Postępowanie obejmuje ochronę, odciążenie, ucisk i uniesienie kończyny.", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-116", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Po zdjęciu opatrunku gipsowego masaż kończyny ma na celu przede wszystkim", "odpowiedzi": {"A": "zastąpienie kinezyterapii", "B": "wywołanie przekrwienia w miejscu złamania silnym oklepywaniem", "C": "zwiększenie sztywności stawów w celu stabilizacji zrostu", "D": "poprawę ukrwienia, zmniejszenie obrzęku i przygotowanie tkanek do ćwiczeń"}, "poprawna": "D", "wyjasnienie": "Po unieruchomieniu występują zaniki, obrzęk i ograniczenie ruchomości. Masaż przygotowuje tkanki do ćwiczeń, które są podstawą usprawniania.", "zrodlo": "MED.10.3.7"},
  {"id": "MED10-117", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Do miejscowych przeciwwskazań masażu należy", "odpowiedzi": {"A": "dojrzała blizna po zabiegu operacyjnym sprzed roku", "B": "czyraczność (ropne zmiany skórne) w masowanej okolicy", "C": "sucha skóra", "D": "przykurcz mięśniowy"}, "poprawna": "B", "wyjasnienie": "Ropne zmiany skórne grożą rozsiewem zakażenia. Dojrzała blizna i przykurcz są wskazaniami do masażu.", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-118", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "W zespole wielodyscyplinarnym osobą odpowiedzialną za postawienie rozpoznania i zlecenie leczenia jest", "odpowiedzi": {"A": "lekarz", "B": "opiekun medyczny", "C": "technik masażysta", "D": "terapeuta zajęciowy"}, "poprawna": "A", "wyjasnienie": "Lekarz stawia diagnozę i wystawia skierowanie lub zlecenie. Masażysta wykonuje zabiegi zgodnie ze zleceniem i informuje zespół o reakcjach pacjenta.", "zrodlo": "MED.10.3.6"},
  {"id": "MED10-119", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Masaż izometryczny polega na", "odpowiedzi": {"A": "wykonywaniu ruchów biernych w stawie z jednoczesną trakcją", "B": "masowaniu całkowicie rozluźnionych mięśni w wodzie", "C": "ucisku punktów spustowych do ustąpienia bólu", "D": "wykonywaniu technik masażu na mięśniu napinanym izometrycznie przez pacjenta"}, "poprawna": "D", "wyjasnienie": "W masażu izometrycznym pacjent napina mięsień bez ruchu w stawie, a masażysta wykonuje techniki na napiętym mięśniu. Stosuje się go m.in. przy osłabieniu siły po urazie stawu.", "zrodlo": "MED.10.3.4"},
  {"id": "MED10-120", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Masaż tensegracyjny opiera się na założeniu, że", "odpowiedzi": {"A": "chłonka płynie tylko pod wpływem siły grawitacji", "B": "każdy mięsień działa niezależnie, więc wystarczy masować miejsce bólu", "C": "napięcia przenoszą się przez połączone mięśnie, powięzi i więzadła tworzące jeden układ, dlatego opracowuje się cały układ", "D": "przyczyną bólu jest wyłącznie zablokowany staw, który należy nastawić"}, "poprawna": "C", "wyjasnienie": "Tensegracja zakłada ciągłość napięć w ciele. Dysfunkcja jednego elementu (np. mięśnia dwugłowego uda) wpływa na cały układ, np. więzadła krzyżowo-guzowego.", "zrodlo": "MED.10.3.4"},
  {"id": "MED10-121", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Masaż podwodny polega na", "odpowiedzi": {"A": "przepuszczaniu pęcherzyków powietrza przez wodę w wannie", "B": "zawijaniu ciała w mokre, zimne prześcieradło", "C": "masowaniu ciała strumieniem wody kierowanym pod jej powierzchnią w wannie, w której zanurzony jest pacjent", "D": "polewaniu ciała naprzemiennie ciepłą i zimną wodą z odległości"}, "poprawna": "C", "wyjasnienie": "W masażu podwodnym strumień wody pod ciśnieniem działa na tkanki zanurzonego pacjenta. Pęcherzyki powietrza to kąpiel perełkowa, a naprzemienne polewanie to bicze szkockie.", "zrodlo": "MED.10.3.4"},
  {"id": "MED10-122", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Bicz szkocki to zabieg wodoleczniczy polegający na", "odpowiedzi": {"A": "kąpieli z wirującą wodą dla kończyn górnych", "B": "kąpieli całkowitej w wodzie z dodatkiem soli jodobromowej", "C": "masażu ręcznym wykonywanym pod natryskiem", "D": "polewaniu ciała strumieniem wody pod ciśnieniem, naprzemiennie ciepłej i zimnej"}, "poprawna": "D", "wyjasnienie": "Naprzemienne bodźce termiczne silnie pobudzają krążenie i układ nerwowy. To przykład zabiegu w środowisku wodnym oddziałującego na całe ciało.", "zrodlo": "MED.10.3.5"},
  {"id": "MED10-123", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Wskazaniem do wykonania masażu Shantala jest", "odpowiedzi": {"A": "gorączka i infekcja u niemowlęcia", "B": "wspieranie rozwoju i relaksacja zdrowego niemowlęcia oraz budowanie więzi z rodzicem", "C": "świeże zmiany skórne o charakterze ropnym", "D": "stan bezpośrednio po szczepieniu z odczynem miejscowym"}, "poprawna": "B", "wyjasnienie": "Shantala to tradycyjny hinduski masaż niemowląt, spopularyzowany przez F. Leboyera. Gorączka, infekcje i zmiany skórne są przeciwwskazaniami.", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-124", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Siła mięśnia oceniona na 3 w skali Lovetta oznacza, że pacjent", "odpowiedzi": {"A": "wykonuje pełny zakres ruchu pokonując grawitację, bez dodatkowego oporu", "B": "napina mięsień bez widocznego ruchu", "C": "wykonuje ruch wyłącznie w odciążeniu", "D": "pokonuje umiarkowany opór zewnętrzny"}, "poprawna": "A", "wyjasnienie": "Skala Lovetta (0–5): 1 to napięcie bez ruchu, 2 ruch w odciążeniu, 3 ruch przeciw grawitacji, 4 przeciw umiarkowanemu oporowi, 5 siła prawidłowa.", "zrodlo": "MED.10.4.1"},
  {"id": "MED10-125", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Do pomiaru zakresu ruchu w stawie stosuje się", "odpowiedzi": {"A": "dynamometr", "B": "spirometr", "C": "goniometr", "D": "fałdomierz"}, "poprawna": "C", "wyjasnienie": "Goniometr mierzy kąty ruchu. Dynamometr mierzy siłę, fałdomierz grubość fałdu skórno-tłuszczowego, a spirometr parametry oddechowe.", "zrodlo": "MED.10.4.1"},
  {"id": "MED10-126", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Długość względną kończyny dolnej mierzy się od", "odpowiedzi": {"A": "guza kulszowego do guza piętowego", "B": "kolca biodrowego przedniego górnego do kostki przyśrodkowej", "C": "krętarza większego kości udowej do kostki bocznej", "D": "pępka do kostki przyśrodkowej"}, "poprawna": "B", "wyjasnienie": "Pomiar od kolca biodrowego przedniego górnego to długość względna. Od krętarza większego do kostki bocznej mierzy się długość bezwzględną.", "zrodlo": "MED.10.4.1"},
  {"id": "MED10-127", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Aby ocenić obrzęk kończyny i skuteczność serii zabiegów drenażu, masażysta", "odpowiedzi": {"A": "ocenia obrzęk tylko wzrokowo, bez pomiarów", "B": "porównuje masę ciała pacjenta przed zabiegiem i po nim", "C": "mierzy obwód jedynie w najszerszym miejscu, każdorazowo innym", "D": "mierzy obwody kończyny w tych samych, wyznaczonych punktach przed serią i po niej"}, "poprawna": "D", "wyjasnienie": "Powtarzalne pomiary obwodów w stałych punktach (np. co kilka centymetrów od wyznaczonego punktu kostnego) pozwalają obiektywnie ocenić zmiany obrzęku.", "zrodlo": "MED.10.4.1"},
  {"id": "MED10-128", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Dodatni objaw Stemmera (niemożność uchwycenia fałdu skóry na grzbietowej powierzchni II palca stopy) wskazuje na", "odpowiedzi": {"A": "obrzęk limfatyczny", "B": "obrzęk żylny w przebiegu niewydolności serca", "C": "odwodnienie organizmu", "D": "zapalenie stawu skokowego"}, "poprawna": "A", "wyjasnienie": "Objaw Stemmera jest typowy dla obrzęku chłonnego, w którym skóra i tkanka podskórna ulegają pogrubieniu i włóknieniu.", "zrodlo": "MED.10.4.1"},
  {"id": "MED10-129", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Celem wywiadu przeprowadzanego przed zabiegiem masażu jest przede wszystkim", "odpowiedzi": {"A": "wykluczenie przeciwwskazań i zebranie informacji potrzebnych do zaplanowania zabiegu", "B": "ustalenie wysokości opłaty za zabieg", "C": "ocena siły mięśniowej w skali Lovetta", "D": "ustalenie rozpoznania choroby zamiast lekarza"}, "poprawna": "A", "wyjasnienie": "Wywiad dotyczy dolegliwości, chorób, przyjmowanych leków i przebytych zabiegów. Na jego podstawie masażysta planuje bezpieczny zabieg.", "zrodlo": "MED.10.4.1"},
  {"id": "MED10-130", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Punkt spustowy to", "odpowiedzi": {"A": "skupisko węzłów chłonnych w dole pachowym", "B": "nadwrażliwe miejsce w napiętym paśmie mięśnia, którego ucisk wywołuje ból miejscowy lub rzutowany", "C": "miejsce wyczuwalnego tętna na tętnicy powierzchownej", "D": "obszar skóry nadwrażliwy w chorobie narządu wewnętrznego"}, "poprawna": "B", "wyjasnienie": "Aktywne punkty spustowe powodują ból spontaniczny i rzutowany. Obszar skóry z nadwrażliwością przy chorobie narządu to strefa Heada.", "zrodlo": "MED.10.4.1"},
  {"id": "MED10-131", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Powierzchowne węzły chłonne pachwinowe można wyczuć", "odpowiedzi": {"A": "na przyśrodkowej powierzchni podudzia", "B": "w okolicy kości krzyżowej", "C": "poniżej więzadła pachwinowego, w obrębie trójkąta udowego", "D": "w dole podkolanowym"}, "poprawna": "C", "wyjasnienie": "Węzły pachwinowe powierzchowne leżą wzdłuż więzadła pachwinowego i przy ujściu żyły odpiszczelowej. Zbierają chłonkę z kończyny dolnej i dolnej części tułowia.", "zrodlo": "MED.10.4.1"},
  {"id": "MED10-132", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Podczas masażu grzbietu w leżeniu przodem, w celu rozluźnienia mięśni, wałek umieszcza się", "odpowiedzi": {"A": "pod karkiem", "B": "pod dołami podkolanowymi", "C": "pod łokciami", "D": "pod stawami skokowymi (grzbietami stóp)"}, "poprawna": "D", "wyjasnienie": "Wałek pod stawami skokowymi lekko zgina kolana, odciąża okolicę lędźwiową i rozluźnia mięśnie łydek. Pod kolanami kładzie się go w leżeniu tyłem.", "zrodlo": "MED.10.4.2"},
  {"id": "MED10-133", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Podczas masażu powłok brzusznych pacjent leży tyłem z", "odpowiedzi": {"A": "kończynami dolnymi zgiętymi w stawach biodrowych i kolanowych", "B": "głową odchyloną maksymalnie do tyłu", "C": "rękami założonymi za głowę", "D": "kończynami dolnymi wyprostowanymi i odwiedzionymi"}, "poprawna": "A", "wyjasnienie": "Zgięcie w stawach biodrowych i kolanowych (np. wałek pod kolanami) rozluźnia powłoki brzuszne i ułatwia głębsze opracowanie brzucha.", "zrodlo": "MED.10.4.2"},
  {"id": "MED10-134", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "U pacjenta z nadmierną potliwością skóry jako środek poślizgowy najlepiej zastosować", "odpowiedzi": {"A": "wazelinę", "B": "oliwkę", "C": "maść rozgrzewającą", "D": "talk"}, "poprawna": "D", "wyjasnienie": "Talk pochłania wilgoć. Oleje stosuje się raczej przy skórze suchej.", "zrodlo": "MED.10.4.3"},
  {"id": "MED10-135", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Masaż kończyny z obrzękiem pourazowym (masaż ssący) rozpoczyna się od odcinka", "odpowiedzi": {"A": "przeciwległej, zdrowej kończyny", "B": "obrzękniętego, z największym uciskiem", "C": "bliższego (proksymalnego), aby udrożnić odpływ z części dalszej", "D": "dalszego (dystalnego), od palców ku tułowiu"}, "poprawna": "C", "wyjasnienie": "Opróżnienie odcinka bliższego „zasysa” płyn z obszarów dalszych. Dopiero później opracowuje się okolicę obrzęku.", "zrodlo": "MED.10.4.3"},
  {"id": "MED10-136", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Jeżeli w trakcie masażu pacjent zgłasza nasilający się ból, nudności i zawroty głowy, masażysta powinien", "odpowiedzi": {"A": "zignorować objawy, bo są typową reakcją na masaż", "B": "przerwać zabieg, ocenić stan pacjenta i odnotować zdarzenie w dokumentacji", "C": "zmienić technikę na oklepywanie i kontynuować", "D": "dokończyć zabieg szybciej i z większą siłą"}, "poprawna": "B", "wyjasnienie": "Masażysta stale obserwuje pacjenta i modyfikuje lub przerywa zabieg przy niepokojących objawach. Reakcje odnotowuje się w karcie zabiegów.", "zrodlo": "MED.10.4.4"},
  {"id": "MED10-137", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Do podstawowych chwytów manualnego drenażu limfatycznego metodą Voddera należą", "odpowiedzi": {"A": "głaskanie, rozcieranie, ugniatanie i oklepywanie", "B": "krążki stacjonarne oraz ruchy pompujące, czerpiące i obrotowe", "C": "ugniatanie poprzeczne, wałkowanie i roztrząsanie", "D": "chwyty okostnowe, tarcie poprzeczne i wibracja punktowa"}, "poprawna": "B", "wyjasnienie": "Chwyty Voddera są powolne, rytmiczne i delikatne, z fazą ucisku i rozluźnienia. Pobudzają kurczliwość naczyń chłonnych.", "zrodlo": "MED.10.4.7"},
  {"id": "MED10-138", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Ucisk stosowany w manualnym drenażu limfatycznym powinien być", "odpowiedzi": {"A": "silny, aż do wyraźnego zaczerwienienia skóry", "B": "zmienny, z gwałtownymi szarpnięciami tkanek", "C": "maksymalny, jaki pacjent jest w stanie wytrzymać", "D": "delikatny, niewywołujący bólu ani przekrwienia skóry"}, "poprawna": "D", "wyjasnienie": "Naczynia chłonne włosowate są bardzo delikatne. Zbyt silny ucisk przekrwia tkanki, zwiększa filtrację i może nasilić obrzęk.", "zrodlo": "MED.10.4.7"},
  {"id": "MED10-139", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Manualny drenaż limfatyczny rozpoczyna się zwykle od opracowania", "odpowiedzi": {"A": "obszaru obrzęku, od palców w kierunku tułowia", "B": "węzłów chłonnych podkolanowych", "C": "okolicy szyi i dołów nadobojczykowych, w pobliżu ujścia przewodów chłonnych do kątów żylnych", "D": "okolicy lędźwiowej i pośladków"}, "poprawna": "C", "wyjasnienie": "Najpierw udrażnia się centralne drogi odpływu (kąty żylne). Dopiero potem opracowuje się kolejne regiony, przesuwając się ku obrzękowi.", "zrodlo": "MED.10.4.7"},
  {"id": "MED10-140", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "U pacjentki z obrzękiem kończyny górnej po usunięciu węzłów chłonnych pachowych chłonkę kieruje się", "odpowiedzi": {"A": "przez zespolenia skórne do węzłów pachowych strony przeciwnej i węzłów pachwinowych tej samej strony", "B": "w kierunku usuniętych węzłów pachowych, zwiększając ucisk", "C": "do węzłów chłonnych podkolanowych", "D": "w kierunku palców dłoni"}, "poprawna": "A", "wyjasnienie": "Po usunięciu węzłów chłonkę przekierowuje się do zdrowych, sprawnie działających grup węzłowych przez zespolenia między kwadrantami tułowia.", "zrodlo": "MED.10.4.7"},
  {"id": "MED10-141", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "W skład kompleksowej terapii przeciwobrzękowej wchodzą", "odpowiedzi": {"A": "kąpiel wirowa w gorącej wodzie, sauna i ćwiczenia siłowe", "B": "masaż klasyczny, krioterapia i ultradźwięki", "C": "manualny drenaż limfatyczny, kompresjoterapia, ćwiczenia i pielęgnacja skóry", "D": "oklepywanie, diatermia krótkofalowa i okłady borowinowe"}, "poprawna": "C", "wyjasnienie": "Kompleksowa terapia przeciwobrzękowa łączy drenaż, bandażowanie lub odzież uciskową, ćwiczenia (z oddechowymi) i pielęgnację skóry. Uczy się też autodrenażu.", "zrodlo": "MED.10.4.8"},
  {"id": "MED10-142", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "W fazie intensywnej leczenia obrzęku limfatycznego stosuje się bandażowanie wielowarstwowe bandażami", "odpowiedzi": {"A": "gipsowymi", "B": "krótkociągliwymi", "C": "elastycznymi rurkowymi w jednej warstwie", "D": "długociągliwymi"}, "poprawna": "B", "wyjasnienie": "Bandaże krótkociągliwe dają niskie ciśnienie spoczynkowe i wysokie robocze podczas pracy mięśni, co wspomaga odpływ chłonki.", "zrodlo": "MED.10.4.8"},
  {"id": "MED10-143", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Elementem terapii ułożeniowej w obrzęku limfatycznym kończyny jest", "odpowiedzi": {"A": "ułożenie kończyny powyżej poziomu serca", "B": "ułożenie kończyny zwieszonej poza krawędź łóżka", "C": "ogrzewanie kończyny termoforem", "D": "długotrwałe stanie bez ruchu"}, "poprawna": "A", "wyjasnienie": "Uniesienie kończyny wykorzystuje grawitację do ułatwienia odpływu chłonki i krwi żylnej.", "zrodlo": "MED.10.4.8"},
  {"id": "MED10-144", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Masaż łącznotkankowy według Dicke rozpoczyna się zawsze od tzw. małej budowy (podstawowej), wykonywanej w okolicy", "odpowiedzi": {"A": "klatki piersiowej", "B": "karku i obręczy barkowej", "C": "stóp", "D": "krzyżowo-lędźwiowej"}, "poprawna": "D", "wyjasnienie": "Zasadą masażu łącznotkankowego jest rozpoczynanie od budowy podstawowej w okolicy krzyżowo-lędźwiowej, co przygotowuje układ wegetatywny do dalszych bodźców.", "zrodlo": "MED.10.4.9"},
  {"id": "MED10-145", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Typowym odczuciem pacjenta podczas prawidłowo wykonanego masażu łącznotkankowego jest", "odpowiedzi": {"A": "brak jakichkolwiek odczuć", "B": "uczucie cięcia lub drapania paznokciem", "C": "uczucie głębokiego, tępego ucisku na kość", "D": "uczucie silnego mrowienia w odległych częściach ciała"}, "poprawna": "B", "wyjasnienie": "Pociągnięcia opuszkami palców napinają tkankę łączną, co pacjent odbiera jako cięcie lub drapanie. To dowód na właściwą technikę.", "zrodlo": "MED.10.4.9"},
  {"id": "MED10-146", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Masaż okostnowy polega na", "odpowiedzi": {"A": "rytmicznym, punktowym ucisku na okostną w miejscach, gdzie kość leży płytko pod skórą", "B": "szybkim oklepywaniu dużych grup mięśniowych", "C": "biernym rozciąganiu torebki stawowej", "D": "przesuwaniu skóry względem powięzi pociągnięciami palców"}, "poprawna": "A", "wyjasnienie": "Rytmiczny ucisk okostnej wywołuje odruchowe reakcje miejscowe i w narządach powiązanych segmentarnie.", "zrodlo": "MED.10.4.9"},
  {"id": "MED10-147", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Strefy Heada to", "odpowiedzi": {"A": "obszary unerwienia poszczególnych nerwów obwodowych", "B": "punkty spustowe w mięśniach szkieletowych", "C": "obszary skóry wykazujące nadwrażliwość w przebiegu chorób narządów wewnętrznych unerwionych z tego samego segmentu", "D": "miejsca palpacji węzłów chłonnych"}, "poprawna": "C", "wyjasnienie": "Wspólne unerwienie segmentarne skóry i narządu sprawia, że choroba narządu daje odczyny w odpowiadającym mu obszarze skóry.", "zrodlo": "MED.10.4.9"},
  {"id": "MED10-148", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Masaż segmentarny oddziałuje na narządy wewnętrzne poprzez", "odpowiedzi": {"A": "zwiększenie odpływu chłonki z narządu", "B": "bezpośredni ucisk na narząd przez powłoki ciała", "C": "pobudzenie receptorów słuchu i wzroku", "D": "połączenia odruchowe w obrębie tego samego segmentu rdzenia kręgowego"}, "poprawna": "D", "wyjasnienie": "Bodźce działające na skórę, tkankę łączną i mięśnie danego segmentu odruchowo wpływają na narządy unerwione z tego segmentu.", "zrodlo": "MED.10.4.9"},
  {"id": "MED10-149", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Dermatom to", "odpowiedzi": {"A": "grupa mięśni unerwiona przez jeden nerw obwodowy", "B": "urządzenie do pomiaru grubości skóry", "C": "fragment kości unerwiony z jednego segmentu", "D": "obszar skóry unerwiony czuciowo przez jeden nerw rdzeniowy (jeden segment rdzenia)"}, "poprawna": "D", "wyjasnienie": "Mapy dermatomów wykorzystuje się w diagnostyce neurologicznej i w masażu segmentarnym. Grupa mięśni z jednego segmentu to miotom, a fragment kości to sklerotom.", "zrodlo": "MED.10.4.9"},
  {"id": "MED10-150", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Twórcą koncepcji podziału ciała na 10 podłużnych stref, wykorzystanej później w refleksoterapii stóp, był", "odpowiedzi": {"A": "Emil Vodder", "B": "Pehr Henrik Ling", "C": "William Fitzgerald", "D": "Elisabeth Dicke"}, "poprawna": "C", "wyjasnienie": "Fitzgerald opisał terapię strefową, którą E. Ingham rozwinęła w mapy refleksów stóp. Dicke stworzyła masaż łącznotkankowy, Vodder drenaż limfatyczny, a Ling masaż szwedzki.", "zrodlo": "MED.10.4.9"},
  {"id": "MED10-151", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "W masażu Shantala jako pierwszą opracowuje się zwykle", "odpowiedzi": {"A": "stopy", "B": "klatkę piersiową", "C": "plecy", "D": "twarz"}, "poprawna": "B", "wyjasnienie": "Klasyczna sekwencja Shantala zaczyna się od klatki piersiowej, potem obejmuje kończyny górne, brzuch, kończyny dolne i plecy. Twarz opracowuje się na końcu.", "zrodlo": "MED.10.4.11"},
  {"id": "MED10-152", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Masaż Shantala wykonuje się", "odpowiedzi": {"A": "u niemowlęcia, w ciepłym pomieszczeniu, z użyciem ciepłego oleju", "B": "wyłącznie u dzieci w wieku szkolnym, przez ubranie", "C": "u niemowlęcia bezpośrednio po karmieniu, w chłodnym pomieszczeniu", "D": "u niemowlęcia z gorączką, aby obniżyć temperaturę"}, "poprawna": "A", "wyjasnienie": "Masaż Shantala wykonuje rodzic lub masażysta u rozebranego niemowlęcia, w cieple i spokoju, nie bezpośrednio po posiłku.", "zrodlo": "MED.10.4.11"},
  {"id": "MED10-153", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Długotrwałe ułożenie kobiety w zaawansowanej ciąży na plecach jest niewskazane z powodu ryzyka", "odpowiedzi": {"A": "zwichnięcia stawu krzyżowo-biodrowego", "B": "nadmiernego wzrostu ciśnienia w tętnicach płucnych", "C": "ucisku macicy na żyłę główną dolną i spadku ciśnienia tętniczego", "D": "nagłego wzrostu stężenia glukozy we krwi"}, "poprawna": "C", "wyjasnienie": "Ciężarna macica może uciskać żyłę główną dolną (zespół żyły głównej dolnej), co zmniejsza powrót żylny i powoduje zawroty głowy oraz spadek ciśnienia.", "zrodlo": "MED.10.4.11"},
  {"id": "MED10-154", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Podczas masażu kobiety w ciąży należy unikać", "odpowiedzi": {"A": "delikatnego głaskania kończyn dolnych", "B": "silnych technik uciskowych i uderzeniowych w okolicy brzucha", "C": "ułożenia na boku z poduszką między kolanami", "D": "masażu karku w pozycji siedzącej"}, "poprawna": "B", "wyjasnienie": "Brzuch ciężarnej masuje się bardzo delikatnie albo wcale. Bezpieczne są łagodne techniki w ułożeniu na boku lub w siadzie.", "zrodlo": "MED.10.4.11"},
  {"id": "MED10-155", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Po zakończeniu zabiegu masażu aparatem wibracyjnym należy", "odpowiedzi": {"A": "przechowywać końcówki w kieszeni fartucha", "B": "umyć aparat pod bieżącą wodą bez odłączania od sieci", "C": "pozostawić aparat włączony do następnego pacjenta", "D": "wyłączyć aparat, odłączyć go od zasilania i zdezynfekować końcówki"}, "poprawna": "D", "wyjasnienie": "Kolejność obsługi aparatu zapewnia bezpieczeństwo elektryczne i higienę. Końcówki mające kontakt ze skórą dezynfekuje się po każdym pacjencie.", "zrodlo": "MED.10.4.12"},
  {"id": "MED10-156", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Manualny drenaż limfatyczny wykonuje się", "odpowiedzi": {"A": "bez środków poślizgowych, aby dłonie przesuwały skórę, a nie się po niej ślizgały", "B": "z maścią rozgrzewającą dla przekrwienia tkanek", "C": "przez grube ubranie pacjenta", "D": "z dużą ilością oliwki, aby dłonie swobodnie się ślizgały"}, "poprawna": "A", "wyjasnienie": "Chwyty drenażu rozciągają skórę i pobudzają naczynia chłonne. Śliski środek uniemożliwiłby przesuwanie skóry.", "zrodlo": "MED.10.4.7"},
  {"id": "MED10-157", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Masaż blizny pooperacyjnej można rozpocząć", "odpowiedzi": {"A": "tylko wtedy, gdy blizna jest zaczerwieniona i sącząca", "B": "wyłącznie po upływie 5 lat od zabiegu", "C": "w pierwszej dobie po operacji, przed zdjęciem szwów", "D": "po całkowitym zagojeniu rany, gdy nie ma strupów ani wydzieliny"}, "poprawna": "D", "wyjasnienie": "Mobilizacja blizny wymaga zamkniętej rany. Wcześniejszy masaż grozi rozejściem się brzegów i zakażeniem.", "zrodlo": "MED.10.4.3"},
  {"id": "MED10-158", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Prawidłowa linia pionu ciała oglądana z boku przechodzi przez", "odpowiedzi": {"A": "kąt dolny łopatki, kolec biodrowy przedni górny i guz piętowy", "B": "guzowatość potyliczną, wyrostki kolczyste kręgów i szparę pośladkową", "C": "płatek ucha, wyrostek barkowy, krętarz większy, nieco przed osią stawu kolanowego i przed kostką boczną", "D": "nos, mostek, pępek i spojenie łonowe"}, "poprawna": "C", "wyjasnienie": "Ocena pionu w płaszczyźnie strzałkowej pozwala wykryć np. wysunięcie głowy, plecy okrągłe czy przeprosty kolan. Linia przez wyrostki kolczyste dotyczy oceny z tyłu.", "zrodlo": "MED.10.4.1"},
  {"id": "MED10-159", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "W karcie zabiegów pacjenta masażysta potwierdza wykonanie każdego zabiegu", "odpowiedzi": {"A": "datą i własnym podpisem", "B": "podpisem pacjenta, bez daty", "C": "wyłącznie ustnie, informując lekarza", "D": "pieczęcią placówki wystawioną na koniec serii"}, "poprawna": "A", "wyjasnienie": "Karta zabiegów jest dokumentacją medyczną. Każdy wykonany zabieg dokumentuje się datą i podpisem osoby wykonującej.", "zrodlo": "MED.10.4.3"},
  {"id": "MED10-160", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Najdogodniejszą pozycją do masażu karku i obręczy barkowej poza stołem jest", "odpowiedzi": {"A": "stanie w lekkim pochyleniu do przodu", "B": "siad na krześle do masażu z oparciem dla klatki piersiowej i głowy", "C": "leżenie tyłem z głową zwisającą poza stół", "D": "klęk podparty na macie"}, "poprawna": "B", "wyjasnienie": "Krzesło do masażu podpiera tułów i głowę, dzięki czemu mięśnie karku i obręczy barkowej są rozluźnione.", "zrodlo": "MED.10.4.2"},
  {"id": "MED10-161", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Przed rozpoczęciem masażu masażysta informuje pacjenta", "odpowiedzi": {"A": "o niczym, aby nie wywoływać niepokoju", "B": "o planowanym przebiegu zabiegu i możliwych reakcjach organizmu", "C": "wyłącznie o cenie zabiegu", "D": "o rozpoznaniu, które sam ustalił na podstawie palpacji"}, "poprawna": "B", "wyjasnienie": "Pacjent ma prawo do informacji. Wiedza o przebiegu zabiegu i możliwych odczuciach, np. przekrwieniu czy bolesności, zwiększa jego poczucie bezpieczeństwa.", "zrodlo": "MED.10.4.2"},
  {"id": "MED10-162", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "W refleksoterapii stóp ucisk okolicy palucha odnosi się według map refleksów przede wszystkim do", "odpowiedzi": {"A": "kończyn dolnych", "B": "pęcherza moczowego", "C": "jelita grubego", "D": "głowy"}, "poprawna": "D", "wyjasnienie": "Na mapach refleksów stopa odwzorowuje ciało: palce, a zwłaszcza paluch, odpowiadają głowie, a pięta okolicy miednicy.", "zrodlo": "MED.10.4.9"},
  {"id": "MED10-163", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Masaż kobiety w okresie połogu po porodzie siłami natury może obejmować", "odpowiedzi": {"A": "łagodny masaż relaksacyjny pleców i kończyn oraz pracę nad napięciem obręczy barkowej", "B": "masaż piersi przy gorączce i zapaleniu gruczołu piersiowego", "C": "intensywne oklepywanie okolicy krzyżowej przy krwawieniu", "D": "silny masaż brzucha w pierwszych dniach po porodzie"}, "poprawna": "A", "wyjasnienie": "W połogu masaż łagodzi przeciążenia (np. obręczy barkowej przy karmieniu). Ostre stany zapalne i krwawienia są przeciwwskazaniem.", "zrodlo": "MED.10.4.11"},
  {"id": "MED10-164", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "U zawodnika w stanie gorączki startowej (nadmiernego pobudzenia) przed zawodami stosuje się masaż", "odpowiedzi": {"A": "pobudzający, z przewagą oklepywania", "B": "drenaż limfatyczny trwający 60 minut", "C": "uspokajający, wolny i rytmiczny, z przewagą głaskania", "D": "masaż izometryczny z maksymalnym napięciem"}, "poprawna": "C", "wyjasnienie": "Gorączka startowa to nadmierne pobudzenie, więc masaż przedstartowy ma uspokoić. Przy apatii startowej stosuje się masaż pobudzający.", "zrodlo": "MED.10.5.2"},
  {"id": "MED10-165", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "U zawodnika w stanie apatii startowej przed zawodami stosuje się masaż przedstartowy", "odpowiedzi": {"A": "uspokajający, z wolnym głaskaniem", "B": "manualny drenaż limfatyczny", "C": "pobudzający, wykonywany w szybkim tempie, z oklepywaniem i wibracją", "D": "relaksacyjny gorącymi kamieniami"}, "poprawna": "C", "wyjasnienie": "Apatia startowa to obniżona gotowość. Szybkie, energiczne techniki pobudzają układ nerwowy i mięśnie.", "zrodlo": "MED.10.5.2"},
  {"id": "MED10-166", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "Masaż przedstartowy charakteryzuje się", "odpowiedzi": {"A": "czasem trwania powyżej 60 minut", "B": "krótkim czasem trwania i wykonaniem niedługo przed startem", "C": "wykonaniem tylko w dniu poprzedzającym zawody", "D": "stosowaniem wyłącznie technik głębokiego ugniatania"}, "poprawna": "B", "wyjasnienie": "Masaż przedstartowy trwa zwykle kilka do kilkunastu minut i uzupełnia rozgrzewkę. Długi masaż mógłby zmęczyć lub nadmiernie rozluźnić zawodnika.", "zrodlo": "MED.10.5.2"},
  {"id": "MED10-167", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "Masaż międzystartowy wykonuje się", "odpowiedzi": {"A": "w przerwach między startami lub konkurencjami, aby przyspieszyć wypoczynek i utrzymać gotowość", "B": "w okresie przejściowym, gdy zawodnik nie trenuje", "C": "zamiast rozgrzewki przed pierwszym startem", "D": "tylko po zakończeniu całego sezonu startowego"}, "poprawna": "A", "wyjasnienie": "Krótki masaż między startami wspomaga regenerację zmęczonych mięśni i utrzymuje je w gotowości do kolejnego wysiłku.", "zrodlo": "MED.10.5.2"},
  {"id": "MED10-168", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "W masażu powysiłkowym (odnowy) po intensywnych zawodach dominują techniki", "odpowiedzi": {"A": "punktowego ucisku okostnej", "B": "intensywnego oklepywania i siekania", "C": "silnego rozcierania poprzecznego mięśni", "D": "głaskania, delikatnego ugniatania i roztrząsania"}, "poprawna": "D", "wyjasnienie": "Po dużym wysiłku mięśnie są zmęczone i wrażliwe. Łagodne techniki poprawiają krążenie i rozluźniają, nie powodując dodatkowych mikrourazów.", "zrodlo": "MED.10.5.2"},
  {"id": "MED10-169", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "Celem masażu treningowego jest", "odpowiedzi": {"A": "wywołanie zmęczenia przed zawodami", "B": "zastąpienie treningu u zawodnika kontuzjowanego", "C": "wspomaganie procesu treningowego i przygotowanie organizmu do większych obciążeń", "D": "leczenie świeżych naderwań mięśni"}, "poprawna": "C", "wyjasnienie": "Masaż treningowy towarzyszy treningowi w okresie przygotowawczym. Wspiera adaptację organizmu i regenerację między jednostkami treningowymi.", "zrodlo": "MED.10.5.2"},
  {"id": "MED10-170", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "Makrocykl treningowy dzieli się na okresy", "odpowiedzi": {"A": "tlenowy, beztlenowy i mieszany", "B": "rehabilitacyjny, profilaktyczny i leczniczy", "C": "rozgrzewki, części głównej i schładzania", "D": "przygotowawczy, startowy i przejściowy"}, "poprawna": "D", "wyjasnienie": "Rozgrzewka, część główna i schładzanie to części jednostki treningowej, a nie okresy makrocyklu.", "zrodlo": "MED.10.5.1"},
  {"id": "MED10-171", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "Masaż podtrzymujący stosuje się przede wszystkim", "odpowiedzi": {"A": "w okresie przejściowym lub w przerwie w treningach, aby utrzymać sprawność tkanek", "B": "wyłącznie w ostrej fazie urazu", "C": "w przerwie między biegami eliminacyjnymi", "D": "bezpośrednio przed startem, aby pobudzić zawodnika"}, "poprawna": "A", "wyjasnienie": "Gdy obciążenia treningowe spadają (okres przejściowy, przerwa, uraz innej okolicy), masaż pomaga utrzymać ukrwienie i elastyczność mięśni.", "zrodlo": "MED.10.5.2"},
  {"id": "MED10-172", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "Przeciwwskazaniem do masażu sportowego jest", "odpowiedzi": {"A": "zwiększone napięcie mięśni po wysiłku", "B": "świeże naderwanie mięśnia z krwiakiem", "C": "opóźniona bolesność mięśni po treningu", "D": "zmęczenie po zawodach"}, "poprawna": "B", "wyjasnienie": "W świeżym urazie z krwiakiem masaż nasiliłby krwawienie. Zmęczenie i bolesność powysiłkowa są wskazaniami do masażu odnowy.", "zrodlo": "MED.10.5.1"},
  {"id": "MED10-173", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "Opóźniona bolesność mięśni (DOMS) pojawia się typowo", "odpowiedzi": {"A": "po 24–72 godzinach od nietypowego lub intensywnego wysiłku, zwłaszcza z pracą ekscentryczną", "B": "wyłącznie u osób nietrenujących, nigdy u sportowców", "C": "tylko po wysiłku w wodzie", "D": "natychmiast w trakcie wysiłku i znika po minucie"}, "poprawna": "A", "wyjasnienie": "Bolesność wynika z mikrouszkodzeń włókien mięśniowych i stanu zapalnego. Masaż powysiłkowy może zmniejszyć jej odczuwanie.", "zrodlo": "MED.10.5.1"},
  {"id": "MED10-174", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "Wykonując masaż przedstartowy w niskiej temperaturze otoczenia, masażysta", "odpowiedzi": {"A": "rozbiera zawodnika całkowicie, by zahartować organizm", "B": "stosuje okłady z lodu na mięśnie przed startem", "C": "rezygnuje z rozgrzewki i wykonuje wyłącznie głaskanie przez 1 minutę", "D": "stosuje środki rozgrzewające i odsłania tylko aktualnie masowaną okolicę"}, "poprawna": "D", "wyjasnienie": "W chłodzie trzeba chronić zawodnika przed wychłodzeniem i dobrać środki wspomagające masaż (np. rozgrzewające) do warunków.", "zrodlo": "MED.10.5.2"},
  {"id": "MED10-175", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "Celem masażu w okresie przygotowawczym, przy dużych obciążeniach treningowych, jest przede wszystkim", "odpowiedzi": {"A": "utrzymanie sprawności podczas całkowitej przerwy w treningu", "B": "przyspieszenie regeneracji i zapobieganie przeciążeniom", "C": "maksymalne pobudzenie przed startem", "D": "leczenie świeżych urazów"}, "poprawna": "B", "wyjasnienie": "W okresie przygotowawczym zawodnik trenuje z dużą objętością, więc masaż wspiera wypoczynek i chroni przed przeciążeniami.", "zrodlo": "MED.10.5.1"},
  {"id": "MED10-176", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "Masaż powysiłkowy po zawodach wykonuje się", "odpowiedzi": {"A": "w trakcie wysiłku, bez przerywania biegu", "B": "dopiero po tygodniu od zawodów", "C": "po wyrównaniu oddechu i tętna oraz po kąpieli lub natrysku", "D": "natychmiast po przekroczeniu mety, zanim zawodnik złapie oddech"}, "poprawna": "C", "wyjasnienie": "Zawodnik powinien najpierw ochłonąć, a natrysk lub kąpiel oczyszczają skórę i rozluźniają mięśnie przed masażem odnowy.", "zrodlo": "MED.10.5.2"},
  {"id": "MED10-177", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "W masażu gorącymi kamieniami jako kamieni ciepłych używa się najczęściej", "odpowiedzi": {"A": "bazaltu", "B": "marmuru", "C": "kryształu górskiego", "D": "piaskowca"}, "poprawna": "A", "wyjasnienie": "Bazalt (skała wulkaniczna) dobrze kumuluje ciepło. Marmur stosuje się jako kamienie zimne.", "zrodlo": "MED.10.6.1"},
  {"id": "MED10-178", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "Przed położeniem gorącego kamienia na ciele pacjenta masażysta powinien", "odpowiedzi": {"A": "położyć kamień od razu po wyjęciu z wrzącej wody", "B": "rozgrzać kamień w kuchence mikrofalowej do 100°C", "C": "sprawdzić temperaturę kamienia na własnej skórze i dostosować ją do odczuć pacjenta", "D": "położyć kamień bezpośrednio na odcinku kręgosłupa bez kontroli temperatury"}, "poprawna": "C", "wyjasnienie": "Ryzyko oparzenia jest główną zasadą bezpieczeństwa tego masażu. Temperaturę kontroluje masażysta i zgłasza pacjent.", "zrodlo": "MED.10.6.2"},
  {"id": "MED10-179", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "Przeciwwskazaniem do masażu gorącymi kamieniami jest", "odpowiedzi": {"A": "przewlekłe zmęczenie i stres", "B": "uczucie zimnych dłoni i stóp", "C": "napięcie mięśni grzbietu u pracownika biurowego", "D": "zaburzenie czucia temperatury, np. w neuropatii cukrzycowej"}, "poprawna": "D", "wyjasnienie": "Pacjent bez prawidłowego czucia ciepła nie zgłosi zbyt wysokiej temperatury, co grozi oparzeniem.", "zrodlo": "MED.10.6.3"},
  {"id": "MED10-180", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "Masaż biurowy wykonuje się", "odpowiedzi": {"A": "na stole, z dużą ilością oleju, po rozebraniu pacjenta", "B": "przez ubranie, bez środków poślizgowych, na specjalnym krześle", "C": "wyłącznie w leżeniu przodem, przez 90 minut", "D": "w wannie z wodą, z użyciem strumienia wody"}, "poprawna": "B", "wyjasnienie": "Masaż biurowy (na krześle) jest krótki, dotyczy głównie karku, pleców, ramion i głowy, i można go wykonać w miejscu pracy.", "zrodlo": "MED.10.6.1"},
  {"id": "MED10-181", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "W masażu relaksacyjnym masażysta stosuje", "odpowiedzi": {"A": "krótkie, energiczne roztrząsanie przed wysiłkiem", "B": "szybkie oklepywanie i siekanie", "C": "silny ucisk punktów spustowych do granicy bólu", "D": "wolne, rytmiczne techniki z przewagą głaskania, bez gwałtownych bodźców"}, "poprawna": "D", "wyjasnienie": "Masaż relaksacyjny ma wyciszyć układ nerwowy, więc unika się technik pobudzających.", "zrodlo": "MED.10.6.2"},
  {"id": "MED10-182", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "Optymalne warunki w gabinecie do masażu relaksacyjnego to", "odpowiedzi": {"A": "głośna muzyka o szybkim rytmie", "B": "ciepłe pomieszczenie, stonowane oświetlenie i cisza lub spokojna muzyka", "C": "otwarte okno i przeciąg dla dotlenienia", "D": "chłodne pomieszczenie i jasne światło jarzeniowe"}, "poprawna": "B", "wyjasnienie": "Komfort termiczny i ograniczenie bodźców sprzyjają rozluźnieniu. Wychłodzenie powoduje napięcie mięśni.", "zrodlo": "MED.10.6.3"},
  {"id": "MED10-183", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "Olejki eteryczne stosowane w masażu prozdrowotnym", "odpowiedzi": {"A": "nakłada się nierozcieńczone bezpośrednio na skórę", "B": "stosuje się wyłącznie u niemowląt", "C": "rozcieńcza się w oleju bazowym przed naniesieniem na skórę", "D": "podaje się pacjentowi do picia"}, "poprawna": "C", "wyjasnienie": "Nierozcieńczone olejki eteryczne mogą podrażniać lub uczulać skórę, dlatego dodaje się je w niewielkim stężeniu do oleju bazowego.", "zrodlo": "MED.10.6.3"},
  {"id": "MED10-184", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "Masażu prozdrowotnego nie wykonuje się u osoby", "odpowiedzi": {"A": "pod wpływem alkoholu", "B": "odczuwającej napięcie mięśni karku", "C": "zmęczonej po pracy", "D": "zestresowanej przed egzaminem"}, "poprawna": "A", "wyjasnienie": "Alkohol rozszerza naczynia i zaburza ocenę odczuć. Spożycie alkoholu jest przeciwwskazaniem do zabiegu.", "zrodlo": "MED.10.6.3"},
  {"id": "MED10-185", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "Masaż profilaktyczny u osoby zdrowej ma na celu przede wszystkim", "odpowiedzi": {"A": "zapobieganie przeciążeniom i dolegliwościom oraz utrzymanie dobrej kondycji tkanek", "B": "leczenie ostrych stanów zapalnych", "C": "leczenie zakrzepicy żył głębokich", "D": "zastąpienie aktywności fizycznej"}, "poprawna": "A", "wyjasnienie": "Masaż profilaktyczny działa zapobiegawczo, np. u osób pracujących w wymuszonej pozycji. Nie zastępuje ruchu.", "zrodlo": "MED.10.6.1"},
  {"id": "MED10-186", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "U pracownika biurowego, który wiele godzin pracuje przy komputerze, masaż profilaktyczny powinien objąć przede wszystkim", "odpowiedzi": {"A": "mięśnie brzucha", "B": "mięśnie karku i obręczy barkowej", "C": "mięśnie przedniej strony uda", "D": "mięśnie łydki i stopy"}, "poprawna": "B", "wyjasnienie": "Praca siedząca z wysuniętą głową przeciąża mięśnie karku i obręczy barkowej (m.in. czworoboczny, dźwigacz łopatki).", "zrodlo": "MED.10.6.3"},
  {"id": "MED10-187", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "Jako środek poślizgowy w masażu relaksacyjnym osoby z suchą skórą najlepiej sprawdzi się", "odpowiedzi": {"A": "spirytus salicylowy", "B": "żel chłodzący z mentolem", "C": "olej roślinny (np. ze słodkich migdałów)", "D": "talk"}, "poprawna": "C", "wyjasnienie": "Olej nawilża i natłuszcza skórę oraz zapewnia płynność ruchów. Talk i spirytus dodatkowo wysuszają skórę.", "zrodlo": "MED.10.6.3"},
  {"id": "MED10-188", "dzial": "MED.10.7 Język obcy zawodowy", "pytanie": "Angielskie słowo „effleurage” oznacza technikę masażu, która po polsku nazywa się", "odpowiedzi": {"A": "wibracja", "B": "ugniatanie", "C": "oklepywanie", "D": "głaskanie"}, "poprawna": "D", "wyjasnienie": "Effleurage to głaskanie, kneading ugniatanie, tapotement oklepywanie, a vibration wibracja.", "zrodlo": "MED.10.7.1"},
  {"id": "MED10-189", "dzial": "MED.10.7 Język obcy zawodowy", "pytanie": "Angielskie słowo „kneading” oznacza", "odpowiedzi": {"A": "rozcieranie", "B": "roztrząsanie", "C": "głaskanie", "D": "ugniatanie"}, "poprawna": "D", "wyjasnienie": "Kneading (od „knead” – zagniatać ciasto) to ugniatanie. Rozcieranie to friction, a roztrząsanie to shaking.", "zrodlo": "MED.10.7.1"},
  {"id": "MED10-190", "dzial": "MED.10.7 Język obcy zawodowy", "pytanie": "Technika określana w języku angielskim jako „tapotement” to", "odpowiedzi": {"A": "głaskanie", "B": "drenaż limfatyczny", "C": "oklepywanie", "D": "ugniatanie"}, "poprawna": "C", "wyjasnienie": "Tapotement (z francuskiego) to grupa technik uderzeniowych, czyli oklepywanie.", "zrodlo": "MED.10.7.1"},
  {"id": "MED10-191", "dzial": "MED.10.7 Język obcy zawodowy", "pytanie": "Masażysta prosi pacjenta: „Please lie on your stomach”. Pacjent powinien", "odpowiedzi": {"A": "położyć się na boku", "B": "położyć się na brzuchu", "C": "położyć się na plecach", "D": "usiąść na krześle"}, "poprawna": "B", "wyjasnienie": "Lie on your stomach znaczy „połóż się na brzuchu”. Na plecach to on your back, a na boku to on your side.", "zrodlo": "MED.10.7.2"},
  {"id": "MED10-192", "dzial": "MED.10.7 Język obcy zawodowy", "pytanie": "Pacjent mówi podczas masażu: „I feel dizzy”. Oznacza to, że", "odpowiedzi": {"A": "ma zawroty głowy", "B": "czuje się dobrze", "C": "jest głodny", "D": "jest mu zimno"}, "poprawna": "A", "wyjasnienie": "Dizzy znaczy „mający zawroty głowy”. To sygnał, by przerwać zabieg i ocenić stan pacjenta.", "zrodlo": "MED.10.7.2"},
  {"id": "MED10-193", "dzial": "MED.10.7 Język obcy zawodowy", "pytanie": "Angielskie określenie „shoulder blade” oznacza", "odpowiedzi": {"A": "kość ramienną", "B": "mostek", "C": "obojczyk", "D": "łopatkę"}, "poprawna": "D", "wyjasnienie": "Shoulder blade (scapula) to łopatka. Obojczyk to collarbone (clavicle), a mostek to breastbone (sternum).", "zrodlo": "MED.10.7.1"},
  {"id": "MED10-194", "dzial": "MED.10.7 Język obcy zawodowy", "pytanie": "Wyrażenie „lymph node” oznacza", "odpowiedzi": {"A": "węzeł chłonny", "B": "ścięgno mięśnia", "C": "naczynie krwionośne", "D": "zakończenie nerwowe"}, "poprawna": "A", "wyjasnienie": "Lymph node to węzeł chłonny, a lymphatic drainage to drenaż limfatyczny.", "zrodlo": "MED.10.7.1"},
  {"id": "MED10-195", "dzial": "MED.10.8 Kompetencje personalne i społeczne", "pytanie": "Pacjent proponuje masażyście dodatkową opłatę za wykonanie masażu mimo przeciwwskazania. Masażysta powinien", "odpowiedzi": {"A": "wykonać zabieg z mniejszą siłą bez informowania pacjenta", "B": "odmówić wykonania zabiegu i wyjaśnić pacjentowi powód", "C": "wykonać zabieg, ale nie wpisywać go do dokumentacji", "D": "wykonać zabieg, bo pacjent wyraził zgodę"}, "poprawna": "B", "wyjasnienie": "Bezpieczeństwo pacjenta i etyka zawodowa są ważniejsze od oczekiwań klienta. Odmowę trzeba uzasadnić.", "zrodlo": "MED.10.8.2"},
  {"id": "MED10-196", "dzial": "MED.10.8 Kompetencje personalne i społeczne", "pytanie": "Masażysta zapewnia poszanowanie intymności pacjenta przez", "odpowiedzi": {"A": "polecenie pacjentowi całkowitego rozebrania się bez względu na okolicę zabiegu", "B": "pozostawianie drzwi gabinetu otwartych w trakcie zabiegu", "C": "okrywanie ręcznikiem lub prześcieradłem okolic ciała, które nie są masowane", "D": "prowadzenie rozmów o pacjencie z innymi pacjentami"}, "poprawna": "C", "wyjasnienie": "Odsłania się tylko masowaną okolicę. To wyraz szacunku dla godności pacjenta i dba o jego komfort cieplny.", "zrodlo": "MED.10.8.2"},
  {"id": "MED10-197", "dzial": "MED.10.8 Kompetencje personalne i społeczne", "pytanie": "Parafrazowanie wypowiedzi pacjenta jest elementem", "odpowiedzi": {"A": "komunikacji niewerbalnej", "B": "aktywnego słuchania", "C": "komunikacji agresywnej", "D": "manipulacji"}, "poprawna": "B", "wyjasnienie": "Powtórzenie własnymi słowami tego, co powiedział pacjent, potwierdza zrozumienie i pokazuje zainteresowanie rozmówcą.", "zrodlo": "MED.10.8.8"},
  {"id": "MED10-198", "dzial": "MED.10.8 Kompetencje personalne i społeczne", "pytanie": "Do objawów wypalenia zawodowego należą", "odpowiedzi": {"A": "wzrost motywacji, zaangażowania i satysfakcji z pracy", "B": "chęć ciągłego podnoszenia kwalifikacji", "C": "wyczerpanie emocjonalne, dystans wobec pacjentów i obniżone poczucie dokonań", "D": "lepsza koncentracja i większa cierpliwość"}, "poprawna": "C", "wyjasnienie": "Model C. Maslach opisuje trzy wymiary wypalenia: wyczerpanie emocjonalne, depersonalizację i obniżone poczucie osiągnięć zawodowych.", "zrodlo": "MED.10.8.6"},
  {"id": "MED10-199", "dzial": "MED.10.8 Kompetencje personalne i społeczne", "pytanie": "Postawa asertywna polega na", "odpowiedzi": {"A": "wyrażaniu własnych opinii i potrzeb z jednoczesnym szacunkiem dla rozmówcy", "B": "unikaniu wyrażania własnego zdania w każdej sytuacji", "C": "zgadzaniu się na wszystkie prośby pacjentów", "D": "narzucaniu innym swojego zdania"}, "poprawna": "A", "wyjasnienie": "Asertywność to postawa pośrednia między uległością a agresją. Pomaga m.in. odmówić pacjentowi bez urażania go.", "zrodlo": "MED.10.8.8"},
  {"id": "MED10-200", "dzial": "MED.10.8 Kompetencje personalne i społeczne", "pytanie": "Cechą wysokiej jakości usługi masażu jest", "odpowiedzi": {"A": "wykonywanie identycznego masażu u każdego pacjenta", "B": "rezygnacja z wywiadu w celu oszczędzenia czasu", "C": "jak najkrótszy czas zabiegu bez względu na zlecenie", "D": "dostosowanie zabiegu do potrzeb i stanu pacjenta przy zachowaniu zasad bezpieczeństwa i higieny"}, "poprawna": "D", "wyjasnienie": "Wysoka jakość oznacza indywidualne podejście, profesjonalizm, bezpieczeństwo i satysfakcję pacjenta.", "zrodlo": "MED.10.8.1"},
  {"id": "MED10-201", "dzial": "MED.10.9 Organizacja pracy małych zespołów", "pytanie": "Przydzielając zadania członkom zespołu, kierownik powinien przede wszystkim uwzględnić", "odpowiedzi": {"A": "kompetencje i kwalifikacje poszczególnych osób", "B": "staż pracy wyłącznie w danej placówce", "C": "wiek pracowników", "D": "sympatie osobiste"}, "poprawna": "A", "wyjasnienie": "Dobór osób do zadań według kompetencji zapewnia jakość i bezpieczeństwo usług.", "zrodlo": "MED.10.9.2"},
  {"id": "MED10-202", "dzial": "MED.10.9 Organizacja pracy małych zespołów", "pytanie": "Cykl Deminga (PDCA), stosowany w doskonaleniu jakości pracy, obejmuje kolejno etapy", "odpowiedzi": {"A": "wykonaj – sprawdź – zaplanuj – zakończ", "B": "zaplanuj – wykonaj – sprawdź – działaj", "C": "zaplanuj – deleguj – kontroluj – nagradzaj", "D": "sprawdź – zaplanuj – działaj – wykonaj"}, "poprawna": "B", "wyjasnienie": "PDCA (Plan – Do – Check – Act) to cykl ciągłego doskonalenia: po sprawdzeniu efektów wprowadza się usprawnienia i zaczyna kolejny cykl.", "zrodlo": "MED.10.9.5"},
  {"id": "MED10-203", "dzial": "MED.10.9 Organizacja pracy małych zespołów", "pytanie": "Narzędziem do graficznego przedstawienia harmonogramu zadań zespołu w czasie jest", "odpowiedzi": {"A": "skala Lovetta", "B": "diagram kołowy budżetu", "C": "piramida Maslowa", "D": "wykres Gantta"}, "poprawna": "D", "wyjasnienie": "Wykres Gantta pokazuje zadania jako paski na osi czasu, co ułatwia planowanie pracy zespołu.", "zrodlo": "MED.10.9.1"},
  {"id": "MED10-204", "dzial": "MED.10.9 Organizacja pracy małych zespołów", "pytanie": "Ocena jakości wykonania zadań przez zespół polega przede wszystkim na", "odpowiedzi": {"A": "liczeniu godzin spędzonych w pracy", "B": "ocenie opartej wyłącznie na opinii najstarszego pracownika", "C": "porównaniu uzyskanych rezultatów z ustalonymi wcześniej kryteriami i standardami", "D": "porównaniu wyników z innymi placówkami bez kryteriów"}, "poprawna": "C", "wyjasnienie": "Rzetelna ocena jakości wymaga jasnych kryteriów, np. standardów procedur, opinii pacjentów i liczby powikłań.", "zrodlo": "MED.10.9.4"},
  {"id": "MED10-205", "dzial": "MED.10.9 Organizacja pracy małych zespołów", "pytanie": "Kierując pracą zespołu w gabinecie masażu, kierownik ustala kolejność zadań przede wszystkim według", "odpowiedzi": {"A": "losowego przydziału", "B": "pilności i ważności zadań oraz harmonogramu przyjęć pacjentów", "C": "preferencji pracownika z najdłuższym stażem", "D": "alfabetycznej kolejności nazwisk pracowników"}, "poprawna": "B", "wyjasnienie": "Planowanie kolejności według priorytetów i harmonogramu zapewnia płynność pracy i terminowość świadczeń.", "zrodlo": "MED.10.9.3"},
  {"id": "MED10-206", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Która z wymienionych struktur układu nerwowego doprowadza bodźce do ciała komórki?", "odpowiedzi": {"A": "Akson", "B": "Neuryt", "C": "Neuron", "D": "Dendryt"}, "poprawna": "D", "wyjasnienie": "Dendryty przewodzą impulsy do ciała komórki nerwowej, a akson (neuryt) odprowadza je od ciała komórki. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, styczeń 2026).", "zrodlo": "MED.10.2.8"},
  {"id": "MED10-207", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Jeśli przyczepy będącego w czynnym napięciu mięśnia oddalają się od siebie, to praca tego mięśnia ma charakter", "odpowiedzi": {"A": "statyczny", "B": "izometryczny", "C": "ekscentryczny", "D": "koncentryczny"}, "poprawna": "C", "wyjasnienie": "Gdy napięty mięsień wydłuża się (przyczepy się oddalają), wykonuje pracę ekscentryczną, np. czworogłowy uda przy schodzeniu ze schodów. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, czerwiec 2022, czerwiec 2024).", "zrodlo": "MED.10.2.11"},
  {"id": "MED10-208", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Przyczep końcowy mięśnia piersiowego większego znajduje się", "odpowiedzi": {"A": "na guzku większym kości ramiennej", "B": "na guzku mniejszym kości ramiennej", "C": "na grzebieniu guzka większego kości ramiennej", "D": "na grzebieniu guzka mniejszego kości ramiennej"}, "poprawna": "C", "wyjasnienie": "Mięsień piersiowy większy kończy się na grzebieniu guzka większego kości ramiennej. Na grzebieniu guzka mniejszego przyczepia się m.in. najszerszy grzbietu. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, czerwiec 2022, czerwiec 2024).", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-209", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Który mięsień między innymi ma swój przyczep na tylnej części kości piszczelowej i strzałkowej?", "odpowiedzi": {"A": "Półścięgnisty", "B": "Płaszczkowaty", "C": "Brzuchaty łydki", "D": "Prostownik długi palców"}, "poprawna": "B", "wyjasnienie": "Mięsień płaszczkowaty rozpoczyna się na tylnej powierzchni górnej części kości strzałkowej i na linii mięśnia płaszczkowatego kości piszczelowej. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, styczeń 2021, czerwiec 2023, styczeń 2024, czerwiec 2026).", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-210", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Unerwienie czuciowe skóry twarzy zapewniają włókna nerwu", "odpowiedzi": {"A": "błędnego", "B": "twarzowego", "C": "trójdzielnego", "D": "dodatkowego"}, "poprawna": "C", "wyjasnienie": "Czucie skóry twarzy zapewnia nerw trójdzielny (V). Nerw twarzowy (VII) jest głównie ruchowy dla mięśni mimicznych. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, czerwiec 2023, czerwiec 2026).", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-211", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Przeciwskazaniami do stosowania drenażu limfatycznego są utrwalone obrzęki powstałe", "odpowiedzi": {"A": "po kontuzjach i urazach mięśni", "B": "po kontuzjach i urazach stawów", "C": "po amputacji gruczołu piersiowego", "D": "w przebiegu ostrych stanów zapalnych nerek"}, "poprawna": "D", "wyjasnienie": "Ostre stany zapalne, w tym nerek, są przeciwwskazaniem do drenażu limfatycznego. Obrzęki pourazowe i po mastektomii są typowymi wskazaniami. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, czerwiec 2023, czerwiec 2026).", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-212", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Przeciwwskazaniem do masażu segmentarnego w chorobach żołądka jest", "odpowiedzi": {"A": "ropień żołądka", "B": "przewlekły nieżyt żołądka", "C": "zaburzenie napięcia ścian żołądka", "D": "zaburzenie czynności wydzielniczej żołądka"}, "poprawna": "A", "wyjasnienie": "Ropień to ostry proces ropny, więc masaż jest przeciwwskazany. Zaburzenia czynnościowe żołądka są wskazaniem do masażu segmentarnego. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021).", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-213", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Przeciwwskazaniem do stosowania masażu izometrycznego jest", "odpowiedzi": {"A": "osłabienie siły mięśniowej", "B": "obniżenie masy mięśniowej", "C": "zanik mięśniowy na tle neurologicznym", "D": "zanik mięśniowy na tle długotrwałego unieruchomienia"}, "poprawna": "C", "wyjasnienie": "Masaż izometryczny wymaga świadomego napięcia mięśnia. Przy zaniku pochodzenia neurologicznego (uszkodzone unerwienie) nie jest skuteczny. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, czerwiec 2022, czerwiec 2023, czerwiec 2024, czerwiec 2026).", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-214", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Dla której pary mięśni, uwzględniając zasadę warstwowości, wskazano prawidłową kolejność ich opracowywania podczas masażu klasycznego?", "odpowiedzi": {"A": "Mięsień ramienny, a następnie mięsień dwugłowy ramienia", "B": "Mięsień płaszczkowaty, a następnie mięsień brzuchaty łydki", "C": "Mięsień nadgrzebieniowy, a następnie mięsień czworoboczny", "D": "Mięsień pośladkowy wielki, a następnie mięsień gruszkowaty"}, "poprawna": "D", "wyjasnienie": "Zasada warstwowości: najpierw opracowuje się mięśnie powierzchowne, potem głębsze. Pośladkowy wielki leży nad gruszkowatym, w pozostałych parach kolejność jest odwrócona. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, styczeń 2021, czerwiec 2022, czerwiec 2023, czerwiec 2024, czerwiec 2026, styczeń 2026).", "zrodlo": "MED.10.4.5"},
  {"id": "MED10-215", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Podczas wykonywania drenażu limfatycznego masażysta powinien stosować zasadę", "odpowiedzi": {"A": "stopniowego rozgrzewania tkanek w trakcie całego zabiegu masażu", "B": "opracowania zbiorczych pni chłonnych głębokich na początku zabiegu", "C": "intensywnego rozgrzania tkanek na początku i na końcu zabiegu masażu", "D": "opracowania regionalnych węzłów chłonnych na początku i na końcu zabiegu"}, "poprawna": "D", "wyjasnienie": "W drenażu limfatycznym opracowuje się regionalne węzły chłonne na początku (udrożnienie odpływu) i na końcu zabiegu. Tkanek się nie rozgrzewa. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, czerwiec 2022, styczeń 2026).", "zrodlo": "MED.10.4.7"},
  {"id": "MED10-216", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Reakcją organizmu na prawidłowo wykonany masaż klasyczny jest", "odpowiedzi": {"A": "poprawienie odżywienia mięśni", "B": "spowolnienie procesu rogowacenia naskórka", "C": "poprawienie agregacji komórek tłuszczowych", "D": "spowolnienie procesu regeneracji kości po złamaniu"}, "poprawna": "A", "wyjasnienie": "Masaż klasyczny poprawia ukrwienie, a przez to odżywienie i dotlenienie mięśni. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, czerwiec 2022, czerwiec 2023, czerwiec 2024, czerwiec 2026).", "zrodlo": "MED.10.3.5"},
  {"id": "MED10-217", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Masaż izometryczny głowy przyśrodkowej mięśnia czworogłowego uda należy wykonać u pacjenta w pozycji leżącej", "odpowiedzi": {"A": "tyłem z klinem pod stawami skokowymi", "B": "tyłem z klinem pod stawami kolanowymi", "C": "przodem z klinem pod stawami skokowymi", "D": "na boku z klinem pomiędzy kończynami dolnymi"}, "poprawna": "B", "wyjasnienie": "Klin pod kolanami ustawia staw w lekkim zgięciu, co ułatwia izometryczne napinanie mięśnia czworogłowego (w tym głowy przyśrodkowej) w leżeniu tyłem. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, czerwiec 2023, czerwiec 2026).", "zrodlo": "MED.10.4.2"},
  {"id": "MED10-218", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Pozycja siedząca nie może być zastosowana podczas masażu u pacjentów z rozpoznaniem", "odpowiedzi": {"A": "kręczu szyi", "B": "przykurczu Volkmana", "C": "porażenia nerwu twarzowego", "D": "przewlekłego stanu rwy kulszowej"}, "poprawna": "D", "wyjasnienie": "Pozycja siedząca zwiększa obciążenie krążków lędźwiowych i napięcie nerwu kulszowego, dlatego przy rwie kulszowej masuje się pacjenta w leżeniu. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, czerwiec 2023, czerwiec 2026, styczeń 2026).", "zrodlo": "MED.10.4.2"},
  {"id": "MED10-219", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Struktura anatomiczna nazywana „gęsią stopą” znajduje się na", "odpowiedzi": {"A": "bocznej powierzchni końca dalszego kości strzałkowej", "B": "bocznej powierzchni końca bliższego kości strzałkowej", "C": "przyśrodkowej powierzchni końca dalszego kości piszczelowej", "D": "przyśrodkowej powierzchni końca bliższego kości piszczelowej"}, "poprawna": "D", "wyjasnienie": "„Gęsia stopa” to wspólny przyczep ścięgien mięśni krawieckiego, smukłego i półścięgnistego na przyśrodkowej powierzchni bliższego końca piszczeli. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, styczeń 2026).", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-220", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Przyczep więzadła właściwego rzepki można zlokalizować palpacyjnie na", "odpowiedzi": {"A": "głowie strzałki", "B": "guzowatości kości piszczelowej", "C": "powierzchni rzepkowej kości udowej", "D": "wyniosłości międzykłykciowej kości piszczelowej"}, "poprawna": "B", "wyjasnienie": "Więzadło rzepki biegnie od wierzchołka rzepki do guzowatości kości piszczelowej, którą łatwo wyczuć poniżej kolana. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, styczeń 2026).", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-221", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Podczas badania opuszkami palców okolicy bolesnej może wystąpić reakcja miejscowa w postaci", "odpowiedzi": {"A": "wzrostu temperatury", "B": "obniżonego napięcia", "C": "wzmożonego napięcia", "D": "obniżenia temperatury"}, "poprawna": "C", "wyjasnienie": "Palpacja bolesnej okolicy często wywołuje obronne, wzmożone napięcie mięśni. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, czerwiec 2022, czerwiec 2023, czerwiec 2024, czerwiec 2026).", "zrodlo": "MED.10.4.1"},
  {"id": "MED10-222", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Pomiar obwodu wykorzystuje się podczas oceny", "odpowiedzi": {"A": "siły mięśni", "B": "ruchomości stawu", "C": "skrócenia kończyny dolnej", "D": "ruchomości klatki piersiowej"}, "poprawna": "D", "wyjasnienie": "Ruchomość klatki piersiowej ocenia się, mierząc jej obwód taśmą przy maksymalnym wdechu i wydechu. Siłę ocenia się testem Lovetta, a zakres ruchu goniometrem. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, czerwiec 2023, czerwiec 2026).", "zrodlo": "MED.10.4.1"},
  {"id": "MED10-223", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Do oceny ograniczenia elastyczności w obrębie tkanki łącznej podskórnej i powięzi należy użyć", "odpowiedzi": {"A": "kresy diagnostycznej Dicke i rolowania", "B": "techniki igłowej i dotykania grzbietową stroną ręki", "C": "rozcierania pionowo ustawionymi palcami i wibracji", "D": "chwytu na mięsień najdłuższy grzbietu i głaskania powierzchownego"}, "poprawna": "A", "wyjasnienie": "Kresa diagnostyczna Dicke i rolowanie fałdu skórnego pozwalają ocenić przesuwalność tkanki podskórnej i powięzi. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, czerwiec 2022, czerwiec 2024).", "zrodlo": "MED.10.4.1"},
  {"id": "MED10-224", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "W masażu tensegracyjnym, przeprowadzając ocenę wrażliwości uciskowej na kości grochowatej, masażysta będzie wykonywał ucisk", "odpowiedzi": {"A": "na kończynie górnej, w okolicy nadgarstka pod kłębem kciuka", "B": "na kończynie górnej, w okolicy nadgarstka pod kłębikiem palca małego", "C": "na podeszwie stopy, po stronie przyśrodkowej nad głową pierwszej kości śródstopia", "D": "na stronie bocznej stopy, w połowie odległości między kostką boczną goleni a kością piętową"}, "poprawna": "B", "wyjasnienie": "Kość grochowata leży po stronie dłoniowej nadgarstka, u podstawy kłębika (strona palca małego). Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, czerwiec 2022, czerwiec 2024).", "zrodlo": "MED.10.4.10"},
  {"id": "MED10-225", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Uszkodzenie układu piramidowego powoduje", "odpowiedzi": {"A": "porażenie wiotkie", "B": "porażenie spastyczne", "C": "zniesienie siły mięśniowej", "D": "toniczne napięcie mięśniowe"}, "poprawna": "B", "wyjasnienie": "Uszkodzenie drogi piramidowej (ośrodkowego neuronu ruchowego) powoduje porażenie spastyczne. Porażenie wiotkie wynika z uszkodzenia obwodowego. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, styczeń 2026).", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-226", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Zmiany demielinizacyjne w ośrodkowym układzie nerwowym są typową cechą charakterystyczną dla", "odpowiedzi": {"A": "udaru mózgu", "B": "wiądu rdzenia", "C": "choroby Parkinsona", "D": "stwardnienia rozsianego"}, "poprawna": "D", "wyjasnienie": "Ogniska demielinizacji w mózgu i rdzeniu kręgowym są typowe dla stwardnienia rozsianego. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, styczeń 2022, czerwiec 2023, czerwiec 2025, czerwiec 2026, styczeń 2026).", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-227", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Zespół objawów w postaci nagłego bólu okolicy lędźwiowej, promieniującego do pośladka, tylnej powierzchni uda i podudzia oraz stopy nazywa się", "odpowiedzi": {"A": "rwą udową", "B": "rwą kulszową", "C": "zablokowaniem stawów międzywyrostkowych", "D": "zablokowaniem stawów krzyżowo-biodrowych"}, "poprawna": "B", "wyjasnienie": "Ból z okolicy lędźwiowej promieniujący do pośladka, tylnej strony uda, podudzia i stopy odpowiada przebiegowi nerwu kulszowego. Rwa udowa promieniuje na przednią stronę uda. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, styczeń 2024).", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-228", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "W leczeniu przewlekłego zapalenia oskrzeli zalecany jest masaż", "odpowiedzi": {"A": "limfatyczny brzucha i klatki piersiowej", "B": "limfatyczny grzbietu i klatki piersiowej", "C": "klasyczny pobudzający mięśnie klatki piersiowej", "D": "klasyczny rozluźniający mięśnie klatki piersiowej"}, "poprawna": "D", "wyjasnienie": "W przewlekłym zapaleniu oskrzeli mięśnie klatki piersiowej i pomocnicze mięśnie oddechowe są przeciążone. Rozluźniający masaż klasyczny ułatwia oddychanie. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, czerwiec 2023, czerwiec 2026).", "zrodlo": "MED.10.3.7"},
  {"id": "MED10-229", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Który rodzaj masażu jest najbardziej efektywny u pacjenta z osłabioną siłą mięśniową?", "odpowiedzi": {"A": "Stawowy", "B": "Okostnowy", "C": "Segmentarny", "D": "Izometryczny"}, "poprawna": "D", "wyjasnienie": "Masaż izometryczny łączy techniki masażu z czynnym napinaniem mięśnia, dlatego jest najskuteczniejszy przy osłabionej sile mięśniowej. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, czerwiec 2023, czerwiec 2026).", "zrodlo": "MED.10.3.4"},
  {"id": "MED10-230", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Którą technikę masażu należy zastosować w celu usprawnienia funkcjonowania pochewek ścięgnistych?", "odpowiedzi": {"A": "Głaskanie okrężne", "B": "Wibrację poprzeczną", "C": "Rozcieranie poprzeczne", "D": "Ugniatanie ze skręceniem"}, "poprawna": "C", "wyjasnienie": "Rozcieranie poprzeczne (do przebiegu ścięgna) poprawia ślizg ścięgna w pochewce i przeciwdziała zrostom. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, czerwiec 2022, czerwiec 2024).", "zrodlo": "MED.10.2.15"},
  {"id": "MED10-231", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Masując mięsień czworogłowy uda należy między innymi opracować jego przyczep na", "odpowiedzi": {"A": "guzowatości kości piszczelowej", "B": "powierzchni wewnętrznej rzepki", "C": "krętarzu mniejszym kości udowej", "D": "kłykciu bocznym kości piszczelowej"}, "poprawna": "A", "wyjasnienie": "Mięsień czworogłowy kończy się przez rzepkę i więzadło rzepki na guzowatości kości piszczelowej. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, styczeń 2024).", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-232", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Masując grzbiet nie opracowuje się mięśnia", "odpowiedzi": {"A": "dźwigacza łopatki", "B": "prostownika grzbietu", "C": "najszerszego grzbietu", "D": "biodrowo-lędźwiowego"}, "poprawna": "D", "wyjasnienie": "Mięsień biodrowo-lędźwiowy leży w jamie brzusznej i na przedniej stronie uda, więc nie opracowuje się go w masażu grzbietu. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, styczeń 2024).", "zrodlo": "MED.10.4.5"},
  {"id": "MED10-233", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Masaż tylnej części uda powinien obejmować mięsień", "odpowiedzi": {"A": "krawiecki", "B": "półścięgnisty", "C": "przywodziciel długi", "D": "zasłaniacz zewnętrzny"}, "poprawna": "B", "wyjasnienie": "Półścięgnisty należy do mięśni kulszowo-goleniowych tylnej strony uda. Krawiecki i przywodziciel długi leżą z przodu i przyśrodkowo. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, styczeń 2024).", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-234", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Podczas drenażu limfatycznego transport płynu tkankowego do naczyń chłonnych włosowatych odbywa się dzięki", "odpowiedzi": {"A": "działaniu siły grawitacji", "B": "pracy mięśni gładkich ścian naczyń chłonnych", "C": "ruchom oddechowym klatki piersiowej i przepony", "D": "różnicy ciśnień między przestrzenią pozanaczyniową a światłem naczyń"}, "poprawna": "D", "wyjasnienie": "Płyn tkankowy wnika do naczyń chłonnych włosowatych dzięki różnicy ciśnień. Dalszy transport zapewnia skurcz ścian naczyń chłonnych (limfangionów). Pytanie z egzaminu MED.10 (sesja: czerwiec 2021).", "zrodlo": "MED.10.3.5"},
  {"id": "MED10-235", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "Które objawy wskazują na przetrenowanie organizmu sportowca?", "odpowiedzi": {"A": "Przyrost wagi ciała, wzmożona aktywność psychoruchowa, bóle", "B": "Duża tolerancja na wysiłek, wzmożone łaknienie, wyrównany nastrój", "C": "Pogorszenie samopoczucia, rozdrażnienie, bezsenność, zmęczenie, apatia", "D": "Dobre samopoczucie, nadmierna aktywność fizyczna, brak apetytu, bezsenność"}, "poprawna": "C", "wyjasnienie": "Przetrenowanie objawia się pogorszeniem samopoczucia, drażliwością, zaburzeniami snu, przewlekłym zmęczeniem i spadkiem formy. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021).", "zrodlo": "MED.10.5.1"},
  {"id": "MED10-236", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "Strukturami anatomicznymi narażonymi na silne przeciążenia u sportowca uprawiającego wioślarstwo są", "odpowiedzi": {"A": "stawy skokowe", "B": "mięśnie trójgłowe ramienia", "C": "nasady bliższe kości ramiennych", "D": "pochewki ścięgniste prostowników nadgarstka"}, "poprawna": "D", "wyjasnienie": "W wiosłowaniu powtarzalna praca nadgarstków przeciąża pochewki ścięgniste prostowników nadgarstka, co grozi ich zapaleniem. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, styczeń 2021, czerwiec 2022, czerwiec 2024).", "zrodlo": "MED.10.5.1"},
  {"id": "MED10-237", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "Jednym z często występujących urazów u sportowców ćwiczących na kółkach lub na drążku w gimnastyce sportowej, przy niewłaściwym doborze szerokości uchwytu, jest", "odpowiedzi": {"A": "złamanie kości promieniowej", "B": "zwichnięcie stawu barkowego", "C": "skręcenie stawu skokowego górnego", "D": "nadkłykciowe złamanie kości ramiennej"}, "poprawna": "B", "wyjasnienie": "Ćwiczenia w zwisie i podporze na kółkach lub drążku przy nieprawidłowym uchwycie silnie obciążają obręcz barkową i grożą zwichnięciem w stawie barkowym. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021).", "zrodlo": "MED.10.5.1"},
  {"id": "MED10-238", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "Zastosowanie techniki ugniatania podczas masażu mięśni zmęczonych po wysiłku ma na celu", "odpowiedzi": {"A": "zmniejszenie utlenowania krwi", "B": "usunięcie kwaśnych metabolitów", "C": "usunięcie produktów odżywczych", "D": "zmniejszenie przekrwienia tkanek"}, "poprawna": "B", "wyjasnienie": "Ugniatanie poprawia przepływ krwi i chłonki w zmęczonych mięśniach, co przyspiesza usuwanie metabolitów wysiłkowych. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021).", "zrodlo": "MED.10.5.2"},
  {"id": "MED10-239", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "Środek poślizgowy nieposiadający działania wspomagającego masaż sportowy to", "odpowiedzi": {"A": "żel Fastum", "B": "maść Ben-Gay", "C": "olejek eteryczny", "D": "oliwka do masażu"}, "poprawna": "D", "wyjasnienie": "Oliwka to wyłącznie środek poślizgowy. Żele i maści (np. rozgrzewające, przeciwzapalne) mają działanie wspomagające. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021).", "zrodlo": "MED.10.5.2"},
  {"id": "MED10-240", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "W masażu zawodników z urazami sportowymi należy zastosować", "odpowiedzi": {"A": "talk i mydliny z szarego mydła", "B": "leki sterydowe i preparaty odżywcze", "C": "olejki eteryczne i leki homeopatyczne", "D": "preparaty przeciwzapalne i przeciwbólowe"}, "poprawna": "D", "wyjasnienie": "Przy urazach sportowych stosuje się środki wspomagające o działaniu przeciwzapalnym i przeciwbólowym. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021).", "zrodlo": "MED.10.5.2"},
  {"id": "MED10-241", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "Przed wykonaniem masażu aromaterapeutycznego u pacjenta bezwzględnie należy", "odpowiedzi": {"A": "określić jednostkę chorobową", "B": "wprowadzić olejki eteryczne do organizmu", "C": "wykluczyć ewentualne przeciwwskazania do tego rodzaju masażu", "D": "ogrzać organizm i doprowadzić do rozszerzenia naczyń krwionośnych"}, "poprawna": "C", "wyjasnienie": "Przed masażem aromaterapeutycznym trzeba wykluczyć przeciwwskazania, w tym uczulenie na olejki eteryczne. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021).", "zrodlo": "MED.10.6.3"},
  {"id": "MED10-242", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Wykonując zabieg masażu klasycznego mięśni powierzchownych klatki piersiowej w celu relaksacyjnym, masażysta podczas głaskania głębokiego powinien kierować ruchy", "odpowiedzi": {"A": "wzdłuż linii środkowej ciała", "B": "poprzecznie od linii środkowej ciała w bok", "C": "skośnie od linii środkowej do łuku żebrowego", "D": "skośnie od linii środkowej w stronę stawu ramiennego"}, "poprawna": "D", "wyjasnienie": "Na klatce piersiowej głaskanie prowadzi się skośnie od mostka w stronę stawu ramiennego i dołu pachowego, zgodnie z przebiegiem włókien mięśnia piersiowego i odpływem chłonki. Pytanie z egzaminu MED.10 (sesja: czerwiec 2021, czerwiec 2022, czerwiec 2023, czerwiec 2024, czerwiec 2026).", "zrodlo": "MED.10.4.5"},
  {"id": "MED10-243", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Jednym z przyczepów mięśnia mostkowo-obojczykowo-sutkowego jest", "odpowiedzi": {"A": "wyrostek mieczykowaty mostka", "B": "koniec mostkowy obojczyka", "C": "koniec barkowy obojczyka", "D": "trzon mostka"}, "poprawna": "B", "wyjasnienie": "Mięsień mostkowo-obojczykowo-sutkowy przyczepia się do rękojeści mostka, przyśrodkowej (mostkowej) części obojczyka i wyrostka sutkowego. Pytanie z egzaminu MED.10 (sesja: styczeń 2021, czerwiec 2023, czerwiec 2026).", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-244", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Które mięśnie odpowiadają za ruch zgięcia w stawie biodrowym?", "odpowiedzi": {"A": "Biodrowo-lędźwiowy i prosty uda", "B": "Pośladkowy wielki i obszerny boczny", "C": "Dwugłowy uda i obszerny pośrodkowy", "D": "Biodrowo-lędźwiowy i pośladkowy średni"}, "poprawna": "A", "wyjasnienie": "Główne zginacze stawu biodrowego to mięsień biodrowo-lędźwiowy i prosty uda. Pośladkowy wielki i dwugłowy uda prostują biodro. Pytanie z egzaminu MED.10 (sesja: styczeń 2021, czerwiec 2023, czerwiec 2026).", "zrodlo": "MED.10.2.11"},
  {"id": "MED10-245", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Po stronie tylnej, bocznej i przedniej stawu ramienno-promieniowego jest położony mięsień", "odpowiedzi": {"A": "nawrotny czworoboczny", "B": "trójgłowy ramienia", "C": "odwracacz", "D": "ramienny"}, "poprawna": "C", "wyjasnienie": "Mięsień odwracacz owija się wokół bliższego końca kości promieniowej, więc leży z tyłu, z boku i z przodu stawu ramienno-promieniowego. Pytanie z egzaminu MED.10 (sesja: styczeń 2021, styczeń 2024).", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-246", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "W której płaszczyźnie zachodzą ruchy w stawach śródręczno-paliczkowych palców II-V?", "odpowiedzi": {"A": "Wyłącznie w strzałkowej", "B": "Wyłącznie w poprzecznej", "C": "W strzałkowej i czołowej", "D": "W czołowej i poprzecznej"}, "poprawna": "C", "wyjasnienie": "W stawach śródręczno-paliczkowych II–V zachodzi zginanie i prostowanie (płaszczyzna strzałkowa) oraz odwodzenie i przywodzenie (płaszczyzna czołowa). Pytanie z egzaminu MED.10 (sesja: styczeń 2021, czerwiec 2022, czerwiec 2024).", "zrodlo": "MED.10.2.11"},
  {"id": "MED10-247", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Troczek górny mięśni strzałkowych znajduje się pomiędzy", "odpowiedzi": {"A": "tylną powierzchnią kości piszczelowej i strzałkowej", "B": "kostką boczną i powierzchnią boczną kości piętowej", "C": "przednią powierzchnią kości piszczelowej i strzałkowej", "D": "kostką przyśrodkową i powierzchnią przyśrodkową kości piętowej"}, "poprawna": "B", "wyjasnienie": "Troczek górny mięśni strzałkowych rozpięty jest między kostką boczną a boczną powierzchnią kości piętowej i przytrzymuje ścięgna strzałkowe. Pytanie z egzaminu MED.10 (sesja: styczeń 2021, czerwiec 2022, czerwiec 2024).", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-248", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Przeciwwskazaniem do stosowania masażu podwodnego jest", "odpowiedzi": {"A": "mózgowe porażenie dziecięce", "B": "mialgia wynikająca z przeciążenia", "C": "stan świeżo po zawale mięśnia sercowego", "D": "choroba Bechterewa w okresie przewlekłym"}, "poprawna": "C", "wyjasnienie": "Świeży zawał serca jest przeciwwskazaniem do zabiegów w wodzie i masażu podwodnego, bo silnie obciążają one układ krążenia. Pytanie z egzaminu MED.10 (sesja: styczeń 2021).", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-249", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Wskazaniem do masażu izometrycznego jest", "odpowiedzi": {"A": "przykurcz po porażeniu nerwu łokciowego", "B": "wiotkość mięśni po udarze mózgu", "C": "osłabienie mięśni po urazie stawu", "D": "obrzęk po naderwaniu mięśnia"}, "poprawna": "C", "wyjasnienie": "Masaż izometryczny jest wskazany przy osłabieniu mięśni po urazie stawu, gdy pacjent potrafi świadomie napiąć mięsień. Pytanie z egzaminu MED.10 (sesja: styczeń 2021).", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-250", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Który objaw chorobowy jest wskazaniem do stosowania rozcierań podczas masażu klasycznego?", "odpowiedzi": {"A": "Żylak", "B": "Geloza", "C": "Obrzęk", "D": "Przetoka"}, "poprawna": "B", "wyjasnienie": "Geloza to bolesne zgrubienie w mięśniu lub tkance podskórnej. Rozcieranie pomaga je rozluźnić. Żylaki i przetoki są przeciwwskazaniami. Pytanie z egzaminu MED.10 (sesja: styczeń 2021).", "zrodlo": "MED.10.2.15"},
  {"id": "MED10-251", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Masaż tensegracyjny układu mięśnia najszerszego grzbietu należy zawsze rozpocząć od", "odpowiedzi": {"A": "kości grochowatej wzdłuż przedramienia do nadkłykcia przyśrodkowego kości ramiennej", "B": "miejsca najbardziej oddalonego od lokalizacji bólu w obrębie tego układu", "C": "miejsca lokalizacji bólu w obrębie układu powierzchownego tylnego", "D": "kości piętowej, wzdłuż przegrody mięśniowej do głowy strzałki"}, "poprawna": "B", "wyjasnienie": "W masażu tensegracyjnym zaczyna się od miejsca układu najbardziej oddalonego od bólu i stopniowo zbliża się do okolicy bolesnej. Pytanie z egzaminu MED.10 (sesja: styczeń 2021, czerwiec 2023, czerwiec 2026).", "zrodlo": "MED.10.4.10"},
  {"id": "MED10-252", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Przyłożenie oporu w tylnej, dystalnej części podudzia stosuje się w drugiej fazie masażu izometrycznego mięśnia", "odpowiedzi": {"A": "pośladkowego wielkiego", "B": "piszczelowego tylnego", "C": "czworogłowego uda", "D": "dwugłowego uda"}, "poprawna": "D", "wyjasnienie": "Opór przykłada się w tylnej, dalszej części podudzia przy próbie zgięcia kolana, czyli przy napinaniu mięśni kulszowo-goleniowych, w tym dwugłowego uda. Pytanie z egzaminu MED.10 (sesja: styczeń 2021, czerwiec 2022, czerwiec 2024).", "zrodlo": "MED.10.4.10"},
  {"id": "MED10-253", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Przed przystąpieniem do oceny tkanek i terapii segmentarnej masażysta powinien poznać wszystkie", "odpowiedzi": {"A": "zmiany odruchowe występujące u pacjenta", "B": "punkty maksymalne występujące u pacjenta", "C": "przesunięcia odruchowe, które mogą wystąpić u pacjenta", "D": "reakcje uczuleniowe, które mogą wystąpić u pacjenta po zastosowaniu środków poślizgowych"}, "poprawna": "C", "wyjasnienie": "Przed masażem segmentarnym trzeba znać możliwe przesunięcia odruchowe, czyli niepożądane reakcje w innych segmentach, by im zapobiegać. Pytanie z egzaminu MED.10 (sesja: styczeń 2021).", "zrodlo": "MED.10.4.9"},
  {"id": "MED10-254", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Wskaż wpływ masażu klasycznego na funkcjonowanie układu pokarmowego.", "odpowiedzi": {"A": "Zmniejsza uczucie głodu", "B": "Poprawia wchłanianie substancji odżywczych do żołądka", "C": "Normalizuje napięcie mięśni gładkich przewodu pokarmowego", "D": "Przepycha masy kałowe przy niedrożności przewodu pokarmowego"}, "poprawna": "C", "wyjasnienie": "Masaż (zwłaszcza powłok brzusznych) normalizuje napięcie i perystaltykę mięśni gładkich jelit. Niedrożność jelit jest przeciwwskazaniem. Pytanie z egzaminu MED.10 (sesja: styczeń 2021).", "zrodlo": "MED.10.3.5"},
  {"id": "MED10-255", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Celem wykonania drenażu limfatycznego u pacjentki po mastektomii jest", "odpowiedzi": {"A": "uelastycznienie tkanek okołostawowych", "B": "rozgrzanie tkanek w obrębie kończyny górnej", "C": "usprawnienie funkcjonowania układu chłonnego", "D": "poprawa ukrwienia tkanek w obrębie rany pooperacyjnej"}, "poprawna": "C", "wyjasnienie": "Drenaż po mastektomii usprawnia odpływ chłonki i zapobiega obrzękowi limfatycznemu kończyny górnej. Pytanie z egzaminu MED.10 (sesja: styczeń 2021).", "zrodlo": "MED.10.3.5"},
  {"id": "MED10-256", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Masaż klasyczny klatki piersiowej wykonany u pacjenta z przewlekłą obturacyjną chorobą płuc powoduje", "odpowiedzi": {"A": "wzrost transportu tlenu z krwi do pęcherzyków płucnych", "B": "zwiększenie ilości wdychanego powietrza", "C": "spłycenie i przyspieszenie oddechu", "D": "zmniejszenie wydalania śluzu"}, "poprawna": "B", "wyjasnienie": "Rozluźnienie mięśni klatki piersiowej zwiększa jej ruchomość i objętość wdechu u chorych na POChP. Pytanie z egzaminu MED.10 (sesja: styczeń 2021).", "zrodlo": "MED.10.3.5"},
  {"id": "MED10-257", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Która pozycja pacjenta i sposób stabilizacji pozycji są prawidłowe podczas masażu mięśnia mostkowo-obojczykowo-sutkowego?", "odpowiedzi": {"A": "Leżenie przodem, głowa pacjenta stabilizowana przez masażystę", "B": "Leżenie przodem, szyja pacjenta stabilizowana przez masażystę", "C": "Siedząca, głowa pacjenta stabilizowana przez masażystę", "D": "Siedząca, kark pacjenta stabilizowany przez masażystę"}, "poprawna": "C", "wyjasnienie": "Mięsień mostkowo-obojczykowo-sutkowy masuje się w siadzie, a masażysta stabilizuje głowę pacjenta, aby mięsień był rozluźniony. Pytanie z egzaminu MED.10 (sesja: styczeń 2021, czerwiec 2022, czerwiec 2024, styczeń 2024).", "zrodlo": "MED.10.4.2"},
  {"id": "MED10-258", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "W II fazie masażu izometrycznego mięśnia dwugłowego uda należy ułożyć pacjenta w pozycji leżenia", "odpowiedzi": {"A": "przodem, z kończyną dolną zgiętą w stawie kolanowym", "B": "na boku, z wyprostowanymi stawami kolanowymi", "C": "tyłem, z wałkiem pod stawami kolanowymi", "D": "na boku, ze zgiętymi stawami kolanowymi"}, "poprawna": "A", "wyjasnienie": "W leżeniu przodem ze zgiętym kolanem pacjent napina mięśnie kulszowo-goleniowe przeciw oporowi masażysty. Pytanie z egzaminu MED.10 (sesja: styczeń 2021).", "zrodlo": "MED.10.4.10"},
  {"id": "MED10-259", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Lokalizując palpacyjnie wyrostek rylcowaty kości promieniowej, należy przyłożyć opuszki palców w części", "odpowiedzi": {"A": "dystalnej, tylno-przyśrodkowej przedramienia", "B": "proksymalnej, przyśrodkowej przedramienia", "C": "proksymalnej, bocznej przedramienia", "D": "dystalnej, bocznej przedramienia"}, "poprawna": "D", "wyjasnienie": "Wyrostek rylcowaty kości promieniowej wyczuwa się na dalszym końcu przedramienia po stronie bocznej (kciukowej). Pytanie z egzaminu MED.10 (sesja: styczeń 2021).", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-260", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "W części bliższej kości udowej od strony bocznej uda palpacyjnie można zlokalizować", "odpowiedzi": {"A": "głowę kości", "B": "krętarz większy", "C": "krętarz mniejszy", "D": "nadkłykieć boczny"}, "poprawna": "B", "wyjasnienie": "Krętarz większy jest dobrze wyczuwalny na bocznej powierzchni bliższej części uda. Krętarz mniejszy leży przyśrodkowo i głęboko. Pytanie z egzaminu MED.10 (sesja: styczeń 2021).", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-261", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Podczas oceny palpacyjnej mięśnia dwugłowego uda należy chwycić wał skórno-mięśniowy w okolicy uda po stronie", "odpowiedzi": {"A": "tylno-bocznej", "B": "przednio-bocznej", "C": "tylno-przyśrodkowej", "D": "przednio-przyśrodkowej"}, "poprawna": "A", "wyjasnienie": "Mięsień dwugłowy uda leży w tylno-bocznej części uda, a półścięgnisty i półbłoniasty w tylno-przyśrodkowej. Pytanie z egzaminu MED.10 (sesja: styczeń 2021).", "zrodlo": "MED.10.4.1"},
  {"id": "MED10-262", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Taśmy centymetrowej nie stosuje się podczas oceny", "odpowiedzi": {"A": "ruchomości klatki piersiowej przed masażem segmentarnym", "B": "zakresu ruchu w stawie przed masażem klasycznym", "C": "masy mięśniowej przed masażem izometrycznym", "D": "wielkości obrzęku przed drenażem limfatycznym"}, "poprawna": "B", "wyjasnienie": "Zakres ruchu w stawie mierzy się goniometrem. Taśmą mierzy się obwody (klatka piersiowa, mięśnie, obrzęk). Pytanie z egzaminu MED.10 (sesja: styczeń 2021, czerwiec 2023, czerwiec 2026).", "zrodlo": "MED.10.4.1"},
  {"id": "MED10-263", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Płaskostopie podłużne charakteryzuje się", "odpowiedzi": {"A": "koślawością kości piętowej i odwiedzeniem przodostopia", "B": "szpotawością kości piętowej i odwiedzeniem przodostopia", "C": "koślawością kości piętowej i przywiedzeniem przodostopia", "D": "szpotawością kości piętowej i przywiedzeniem przodostopia"}, "poprawna": "A", "wyjasnienie": "W płaskostopiu podłużnym łuk przyśrodkowy się obniża, pięta ustawia się koślawo, a przodostopie odwodzi. Pytanie z egzaminu MED.10 (sesja: styczeń 2021, czerwiec 2022, czerwiec 2024, styczeń 2024).", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-264", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Które objawy występują u pacjenta po lewostronnym udarze mózgu?", "odpowiedzi": {"A": "Miopatia lub wiotkość jednej z kończyn dolnych", "B": "Sztywność lub spastyczność obu kończyn dolnych", "C": "Porażenie lub niedowład kończyn po prawej stronie ciała", "D": "Sztywność lub niedowład kończyn zawsze po lewej stronie ciała"}, "poprawna": "C", "wyjasnienie": "Drogi ruchowe krzyżują się, więc udar lewej półkuli powoduje niedowład lub porażenie po prawej stronie ciała. Pytanie z egzaminu MED.10 (sesja: styczeń 2021, styczeń 2024).", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-265", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "W przebiegu której choroby klatka piersiowa jest ustawiona wdechowo, zwiększona w wymiarze przednio-tylnym, mostek, obojczyki i łopatki są ustawione wysoko?", "odpowiedzi": {"A": "Rozedmy", "B": "Krzywicy", "C": "Gruźlicy płuc", "D": "Zespołu Marfana"}, "poprawna": "A", "wyjasnienie": "W rozedmie klatka piersiowa jest beczkowata, ustawiona wdechowo, ze zwiększonym wymiarem przednio-tylnym. Pytanie z egzaminu MED.10 (sesja: styczeń 2021, styczeń 2024).", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-266", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Ruchy bierne na zakończenie masażu należy wykonać u pacjenta", "odpowiedzi": {"A": "z przykurczem stawu ramiennego po zwichnięciu", "B": "z wiotkością po uszkodzeniu nerwu obwodowego", "C": "ze sztywnością mięśni w chorobie Parkinsona", "D": "z bólami kostno-stawowymi w fibromialgii"}, "poprawna": "B", "wyjasnienie": "Przy porażeniu wiotkim (uszkodzenie nerwu obwodowego) ruchy bierne utrzymują zakres ruchu w stawach i zapobiegają przykurczom. Pytanie z egzaminu MED.10 (sesja: styczeń 2021).", "zrodlo": "MED.10.3.7"},
  {"id": "MED10-267", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "U pacjenta ze zdiagnozowanym samoistnym porażeniem nerwu twarzowego należy zabieg masażu klasycznego połączyć", "odpowiedzi": {"A": "z ćwiczeniami rozciągającymi", "B": "z ćwiczeniami rozluźniającymi", "C": "z naświetlaniem lampą kwarcową", "D": "z naświetlaniem lampą na podczerwień"}, "poprawna": "D", "wyjasnienie": "W porażeniu nerwu twarzowego przed masażem lub razem z nim stosuje się ciepło lampy na podczerwień, które poprawia ukrwienie. UV z lampy kwarcowej nie łączy się w ten sposób z masażem. Pytanie z egzaminu MED.10 (sesja: styczeń 2021).", "zrodlo": "MED.10.3.7"},
  {"id": "MED10-268", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Który rodzaj masażu jest przeciwwskazany w przypadku pacjenta z chorobą Parkinsona?", "odpowiedzi": {"A": "Stawowy", "B": "Klasyczny", "C": "Izometryczny", "D": "Tensegracyjny"}, "poprawna": "C", "wyjasnienie": "W chorobie Parkinsona dominuje sztywność mięśni, a izometryczne napinanie mogłoby ją nasilać, dlatego masaż izometryczny jest przeciwwskazany. Pytanie z egzaminu MED.10 (sesja: styczeń 2021).", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-269", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "W przypadku sportowca z entezopatią mięśnia podkolanowego należy zastosować", "odpowiedzi": {"A": "masaż okostnowy na nadkłykciu przyśrodkowym kości udowej", "B": "masaż stawowy z wcieraniem maści przeciwzapalnych", "C": "drenaż limfatyczny z bandażowaniem całej kończyny", "D": "masaż izometryczny mięśnia podkolanowego"}, "poprawna": "B", "wyjasnienie": "Entezopatia to przeciążenie przyczepu ścięgna. Stosuje się łagodny masaż okolicy stawu z wcieraniem preparatów przeciwzapalnych. Pytanie z egzaminu MED.10 (sesja: styczeń 2021, czerwiec 2022, czerwiec 2024, styczeń 2024).", "zrodlo": "MED.10.5.2"},
  {"id": "MED10-270", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Który zabieg jest wskazany u pacjenta, u którego 3 tygodnie wcześniej wykonano amputację kończyny dolnej na poziomie uda?", "odpowiedzi": {"A": "Masaż limfatyczny", "B": "Masaż segmentarny", "C": "Masaż wirowy kikuta", "D": "Masaż klasyczny kikuta"}, "poprawna": "A", "wyjasnienie": "Kilka tygodni po amputacji kikut jest obrzęknięty, a blizna świeża. Drenaż limfatyczny zmniejsza obrzęk i przygotowuje kikut do protezowania. Pytanie z egzaminu MED.10 (sesja: styczeń 2021).", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-271", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Podczas wykonywania masażu klasycznego o charakterze rozluźniającym właściwe jest", "odpowiedzi": {"A": "ugniatanie na brzuścu mięśnia, poprzecznie do jego włókien", "B": "uciskanie pulsacyjne na przyczepach i ścięgnach mięśnia", "C": "ugniatanie na brzuścu mięśnia, wzdłuż jego włókien", "D": "uciskanie pulsacyjne wzdłuż całego mięśnia"}, "poprawna": "C", "wyjasnienie": "Spokojne ugniatanie wzdłuż przebiegu włókien działa rozluźniająco. Ugniatanie poprzeczne i uciski pulsacyjne bardziej pobudzają. Pytanie z egzaminu MED.10 (sesja: styczeń 2021).", "zrodlo": "MED.10.2.15"},
  {"id": "MED10-272", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "W przypadku pacjenta z rwą kulszową w podostrym okresie choroby należy zastosować masaż klasyczny o charakterze", "odpowiedzi": {"A": "pobudzającym w obrębie lędźwi i tylnej części kończyny dolnej", "B": "rozluźniającym w obrębie lędźwi i tylnej części kończyny dolnej", "C": "odżywczym w obrębie lędźwi i przedniej części kończyny dolnej", "D": "rozluźniającym w obrębie lędźwi i przedniej części kończyny dolnej"}, "poprawna": "B", "wyjasnienie": "W okresie podostrym rwy kulszowej masażem rozluźniającym opracowuje się okolicę lędźwiową i tylną stronę kończyny, wzdłuż przebiegu nerwu. Pytanie z egzaminu MED.10 (sesja: styczeń 2021).", "zrodlo": "MED.10.3.4"},
  {"id": "MED10-273", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "W przypadku pacjenta z ręką szponiastą, wynikającą z uszkodzenia nerwu łokciowego na poziomie stawu łokciowego, bez występującego obrzęku, w początkowym okresie kompensacji należy wykonać masaż klasyczny w obszarze", "odpowiedzi": {"A": "kończyny górnej, z pominięciem stawu łokciowego", "B": "przedramienia stawu łokciowego i ramienia", "C": "całej kończyny górnej", "D": "dłoni i nadgarstka"}, "poprawna": "A", "wyjasnienie": "Przy świeżym uszkodzeniu nerwu łokciowego na poziomie łokcia masuje się kończynę z pominięciem miejsca uszkodzenia, czyli stawu łokciowego. Pytanie z egzaminu MED.10 (sesja: styczeń 2021).", "zrodlo": "MED.10.3.4"},
  {"id": "MED10-274", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "Który masaż należy wykonać w okresie przejściowym u zawodnika uprawiającego gimnastykę sportową?", "odpowiedzi": {"A": "Segmentarny grzbietu", "B": "Klasyczny całego ciała", "C": "Wirowy kończyn górnych", "D": "Izometryczny mięśni kończyn dolnych"}, "poprawna": "B", "wyjasnienie": "W okresie przejściowym (odpoczynek po sezonie) stosuje się ogólny masaż klasyczny całego ciała, wspierający regenerację. Pytanie z egzaminu MED.10 (sesja: styczeń 2021, czerwiec 2022, czerwiec 2024).", "zrodlo": "MED.10.5.1"},
  {"id": "MED10-275", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "Do gabinetu masażu zgłasza się 30-letnia kobieta na masaż relaksacyjny, która chce wykorzystać godzinną przerwę w pracy. Który rodzaj masażu należy zaproponować pacjentce?", "odpowiedzi": {"A": "Stawowy", "B": "Klasyczny", "C": "Segmentarny", "D": "Izometryczny"}, "poprawna": "B", "wyjasnienie": "Relaksacyjny masaż klasyczny (np. pleców lub całego ciała) mieści się w godzinie i nie wymaga skierowania. Pytanie z egzaminu MED.10 (sesja: styczeń 2021).", "zrodlo": "MED.10.6.1"},
  {"id": "MED10-276", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Do gabinetu masażu zgłosiła się pacjentka na zabieg drenażu limfatycznego twarzy, szyi i dekoltu. Który z kierunków wykonania tego zabiegu nie jest właściwy?", "odpowiedzi": {"A": "Od brody do kątów żuchwy", "B": "Od skrzydełek nosa do skroni", "C": "Od linii włosów do nasady nosa", "D": "Od kątów żuchwy do dołów nadobojczykowych"}, "poprawna": "C", "wyjasnienie": "Drenaż twarzy prowadzi się od środka twarzy ku bokom i w dół, do węzłów przy kątach żuchwy i dalej do dołów nadobojczykowych. Kierunek od linii włosów do nosa jest odwrotny. Pytanie z egzaminu MED.10 (sesja: styczeń 2021, czerwiec 2022, czerwiec 2023, czerwiec 2024).", "zrodlo": "MED.10.4.7"},
  {"id": "MED10-277", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "Ocena skutków próby uczuleniowej wykonanej przed pierwszym masażem aromaterapeutycznym jest możliwa po upływie", "odpowiedzi": {"A": "jednego dnia", "B": "pięciu dni", "C": "10 minut", "D": "30 minut"}, "poprawna": "A", "wyjasnienie": "Odczyn uczuleniowy na olejek ocenia się po upływie doby od nałożenia próbki na skórę. Pytanie z egzaminu MED.10 (sesja: styczeń 2021).", "zrodlo": "MED.10.6.3"},
  {"id": "MED10-278", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Za ruch wyprostu w stawie ramiennym odpowiada mięsień", "odpowiedzi": {"A": "ramienny", "B": "kruczo-ramienny", "C": "nadgrzebieniowy", "D": "najszerszy grzbietu"}, "poprawna": "D", "wyjasnienie": "Mięsień najszerszy grzbietu prostuje, przywodzi i rotuje ramię do wewnątrz. Kruczo-ramienny i nadgrzebieniowy go zginają lub odwodzą. Pytanie z egzaminu MED.10 (sesja: czerwiec 2022, czerwiec 2024).", "zrodlo": "MED.10.2.11"},
  {"id": "MED10-279", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Wskazaniem do zastosowania masażu tensegracyjnego w układzie mięśnia najszerszego grzbietu po stronie lewej jest", "odpowiedzi": {"A": "wzmożona bolesność okolicy przyśrodkowej lewego stawu łokciowego i przedramienia", "B": "nawracający ból głowy i zwiększone napięcie mięśni podpotylicznych po stronie lewej", "C": "zwiększona wrażliwość na dotyk w okolicy C6-Th3 po stronie lewej", "D": "zaburzenie czucia powierzchownego na bocznej stronie lewego uda"}, "poprawna": "A", "wyjasnienie": "Układ mięśnia najszerszego grzbietu obejmuje struktury przyśrodkowej strony łokcia i przedramienia (do kości grochowatej), więc ból w tej okolicy jest wskazaniem. Pytanie z egzaminu MED.10 (sesja: czerwiec 2022, styczeń 2022, czerwiec 2023, styczeń 2023, czerwiec 2024, czerwiec 2025, styczeń 2025, czerwiec 2026).", "zrodlo": "MED.10.4.10"},
  {"id": "MED10-280", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Które stwierdzenie jest zgodne z zasadami wykonywania masażu?", "odpowiedzi": {"A": "Maksymalna liczba powtórzeń skurczów w drugiej fazie masażu izometrycznego wynosi 20", "B": "Bodziec masażu powinien być tak silny, jak to tylko możliwe, i tak słaby, jak to konieczne", "C": "Masaż segmentarny wykonuje się tylko do usunięcia zmian odruchowych", "D": "Masaż stawowy wykonuje się w kierunku od szpary stawowej"}, "poprawna": "C", "wyjasnienie": "Masaż segmentarny prowadzi się do ustąpienia zmian odruchowych w tkankach. Zasada siły bodźca brzmi odwrotnie: tak słaby, jak to możliwe, i tak silny, jak to konieczne. Pytanie z egzaminu MED.10 (sesja: czerwiec 2022, czerwiec 2024).", "zrodlo": "MED.10.4.9"},
  {"id": "MED10-281", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Pacjenta z prawostronnym rozstrzeniem oskrzeli do wykonania masażu klatki piersiowej należy ułożyć na stole w pozycji leżenia", "odpowiedzi": {"A": "na prawym boku, ze zgiętymi lekko kończynami dolnymi i poduszką pod głową", "B": "na lewym boku, ze zgiętymi lekko kończynami dolnymi i poduszką pod głową", "C": "przodem z wyprostowanymi kończynami dolnymi i poduszką pod głową", "D": "tyłem, ze zgiętymi kończynami dolnymi i poduszką pod głową"}, "poprawna": "B", "wyjasnienie": "Przy drenażu wydzieliny chore płuco układa się wyżej, więc przy zmianach prawostronnych pacjent leży na lewym boku. Pytanie z egzaminu MED.10 (sesja: czerwiec 2022).", "zrodlo": "MED.10.4.2"},
  {"id": "MED10-282", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "Ugniatania w masażu klasycznym w celu relaksacyjnym powinny być wykonywane", "odpowiedzi": {"A": "szybko i energicznie, podczas pracy wyłącznie na fałdzie skórno-łącznotkankowym", "B": "bardzo szybko i energicznie, podczas pracy na brzuścach mięśniowych", "C": "głęboko i wolno, podczas pracy na brzuścach mięśniowych", "D": "bardzo wolno, przy odkształcaniu skóry i okostnej"}, "poprawna": "C", "wyjasnienie": "W masażu relaksacyjnym ugniatanie wykonuje się wolno i głęboko na brzuścach mięśni. Szybkie, energiczne ruchy pobudzają. Pytanie z egzaminu MED.10 (sesja: czerwiec 2022, czerwiec 2024).", "zrodlo": "MED.10.6.2"},
  {"id": "MED10-283", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Reakcją organizmu mogącą pojawić się po wykonaniu pierwszych kilku zabiegów masażu klasycznego jest", "odpowiedzi": {"A": "zwiększone przekrwienie w obrębie masowanego miejsca", "B": "masywny wylew podskórny powyżej masowanego miejsca", "C": "obniżenie temperatury ciała w obrębie masowanych struktur", "D": "zniesienie czucia powierzchownego w obrębie masowanych struktur"}, "poprawna": "A", "wyjasnienie": "Typową, korzystną reakcją na pierwsze zabiegi jest przekrwienie masowanej okolicy. Wylew podskórny świadczy o błędzie. Pytanie z egzaminu MED.10 (sesja: czerwiec 2022, czerwiec 2023, czerwiec 2024, czerwiec 2026).", "zrodlo": "MED.10.3.5"},
  {"id": "MED10-284", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "U pacjenta z zaawansowaną postacią przewlekłej obturacyjnej choroby płuc można zaobserwować", "odpowiedzi": {"A": "obniżenie wysokości barków", "B": "nadmierną ruchomość łopatek", "C": "obniżone napięcia kres karkowych", "D": "nadmierne napięcie mięśni wydechowych"}, "poprawna": "D", "wyjasnienie": "W zaawansowanej POChP oddychanie wymaga dużego wysiłku, a mięśnie wydechowe (np. brzucha) i pomocnicze pracują z nadmiernym napięciem. Pytanie z egzaminu MED.10 (sesja: czerwiec 2022, czerwiec 2023, czerwiec 2024, czerwiec 2026).", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-285", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Po głębokim opracowaniu części podeszwowych stóp jest możliwe pogłębienie skłonu tułowia przy wyprostowanych stawach kolanowych, ponieważ", "odpowiedzi": {"A": "pobudzone receptory bólowe podeszwowej strony stopy blokują w ośrodkowym układzie nerwowym dostęp informacji o bólu z innych rozciąganych mięśni", "B": "rozluźnienie struktur na podeszwowej stronie stopy obniża napięcie w pozostałej części łańcucha mięśniowo-powięziowego kończyny dolnej", "C": "za sprawą łuku odruchowego skórno-trzewnego opracowanie stopy rozluźnia proksymalnie leżące mięśnie", "D": "głębokie opracowanie stopy poprawia ukrwienie w mięśniach kulszowo-goleniowych"}, "poprawna": "B", "wyjasnienie": "Powięź podeszwowa należy do tylnego łańcucha mięśniowo-powięziowego. Jej rozluźnienie zmniejsza napięcie całego łańcucha i pogłębia skłon. Pytanie z egzaminu MED.10 (sesja: czerwiec 2022, czerwiec 2024).", "zrodlo": "MED.10.4.4"},
  {"id": "MED10-286", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "W celu uzyskania zmniejszenia poziomu pobudzenia układu nerwowego masażysta nie powinien stosować w trakcie masażu techniki", "odpowiedzi": {"A": "głaskania", "B": "ugniatania", "C": "rozcierania", "D": "oklepywania"}, "poprawna": "D", "wyjasnienie": "Oklepywanie to technika pobudzająca, dlatego nie stosuje się jej, gdy celem jest wyciszenie układu nerwowego. Pytanie z egzaminu MED.10 (sesja: czerwiec 2022, czerwiec 2024).", "zrodlo": "MED.10.6.2"},
  {"id": "MED10-287", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Celem rozluźnienia bolesnych napięć mięśni równoległobocznych masażysta powinien wykonać masaż", "odpowiedzi": {"A": "dłoniowej strony śródręcza każdej z rąk", "B": "części dystalnej podeszwowej strony obu stóp", "C": "okolicy między brzegami przyśrodkowymi łopatek", "D": "okolicy między grzebieniami talerzy biodrowych a dolnymi żebrami"}, "poprawna": "C", "wyjasnienie": "Mięśnie równoległoboczne leżą między wyrostkami kolczystymi C7–Th5 a brzegiem przyśrodkowym łopatki, więc masuje się okolicę międzyłopatkową. Pytanie z egzaminu MED.10 (sesja: czerwiec 2022, styczeń 2023, czerwiec 2024, styczeń 2025).", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-288", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Akineza, sztywność, drżenie i maskowatość twarzy to objawy charakterystyczne choroby", "odpowiedzi": {"A": "Heinego-Medina", "B": "Bechterewa", "C": "Parkinsona", "D": "Raynauda"}, "poprawna": "C", "wyjasnienie": "Spowolnienie ruchowe (akineza), sztywność, drżenie spoczynkowe i maskowata twarz to typowe objawy choroby Parkinsona. Pytanie z egzaminu MED.10 (sesja: czerwiec 2022, styczeń 2022, czerwiec 2023, czerwiec 2024, czerwiec 2025, czerwiec 2026).", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-289", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "W celu usunięcia zmian odruchowych powstałych w tkankach na skutek choroby Raynauda, masażysta powinien zastosować masaż", "odpowiedzi": {"A": "limfatyczny", "B": "segmentarny", "C": "centryfugalny", "D": "tensegracyjny"}, "poprawna": "B", "wyjasnienie": "Choroba Raynauda to zaburzenie naczynioruchowe o podłożu wegetatywnym. Masaż segmentarny usuwa zmiany odruchowe w odpowiednich segmentach. Pytanie z egzaminu MED.10 (sesja: czerwiec 2022, czerwiec 2024, styczeń 2024).", "zrodlo": "MED.10.3.4"},
  {"id": "MED10-290", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "W przypadku pleców okrągłych podczas zabiegu masażu należy łagodzić pobudzenie i znormalizować napięcie mięśnia", "odpowiedzi": {"A": "piersiowego większego", "B": "najszerszego grzbietu", "C": "równoległobocznego", "D": "czworobocznego"}, "poprawna": "A", "wyjasnienie": "W plecach okrągłych przykurczony mięsień piersiowy większy się rozluźnia, a osłabione mięśnie grzbietu się pobudza. Pytanie z egzaminu MED.10 (sesja: czerwiec 2022, czerwiec 2024).", "zrodlo": "MED.10.3.4"},
  {"id": "MED10-291", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Podczas wykonywania masażu klasycznego w celu normalizacji napięcia spoczynkowego mięśnia i poprawy czucia głębokiego masażysta powinien zastosować przede wszystkim technikę", "odpowiedzi": {"A": "oklepywania", "B": "wstrząsania", "C": "rozcierania", "D": "ugniatania"}, "poprawna": "D", "wyjasnienie": "Ugniatanie oddziałuje na brzusiec mięśnia i jego proprioceptory, normalizując napięcie i poprawiając czucie głębokie. Pytanie z egzaminu MED.10 (sesja: czerwiec 2022, czerwiec 2024).", "zrodlo": "MED.10.2.15"},
  {"id": "MED10-292", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "Na zabieg masażu gorącymi kamieniami całego ciała zgłasza się pacjentka z niewielkimi obrzękami pod oczami i cerą naczynkową. W trakcie masażu twarzy należy zastosować", "odpowiedzi": {"A": "gorące kamienie marmurowe", "B": "zimne kamienie marmurowe", "C": "gorące kamienie bazaltowe", "D": "ciepłe kamienie bazaltowe"}, "poprawna": "B", "wyjasnienie": "Zimne kamienie marmurowe obkurczają naczynia i zmniejszają obrzęk, dlatego przy cerze naczynkowej i obrzękach pod oczami stosuje się je na twarz. Pytanie z egzaminu MED.10 (sesja: czerwiec 2022, czerwiec 2024).", "zrodlo": "MED.10.6.2"},
  {"id": "MED10-293", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Przyczep końcowy mięśnia zębatego przedniego znajduje się na", "odpowiedzi": {"A": "wewnętrznej powierzchni 9 żeber", "B": "guzku większym kości ramiennej", "C": "brzegu przyśrodkowym łopatki", "D": "grzebieniu łopatki"}, "poprawna": "C", "wyjasnienie": "Mięsień zębaty przedni zaczyna się na żebrach I–IX, a kończy na brzegu przyśrodkowym łopatki. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2025).", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-294", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Za zgięcie stopy w kierunku podeszwowym jest odpowiedzialny między innymi mięsień", "odpowiedzi": {"A": "płaszczkowaty", "B": "podkolanowy", "C": "półścięgnisty", "D": "półbłoniasty"}, "poprawna": "A", "wyjasnienie": "Mięsień płaszczkowaty (część mięśnia trójgłowego łydki) zgina stopę podeszwowo przez ścięgno piętowe. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2025).", "zrodlo": "MED.10.2.11"},
  {"id": "MED10-295", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Strukturą wchodzącą w skład stawu ramienno-łokciowego jest", "odpowiedzi": {"A": "wcięcie promieniowe kości łokciowej", "B": "dołek głowy kości promieniowej", "C": "bloczek kości ramiennej", "D": "główka kości ramiennej"}, "poprawna": "C", "wyjasnienie": "Staw ramienno-łokciowy tworzą bloczek kości ramiennej i wcięcie bloczkowe kości łokciowej. Główka kości ramiennej łączy się z kością promieniową. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2023, czerwiec 2025, czerwiec 2026).", "zrodlo": "MED.10.2.8"},
  {"id": "MED10-296", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "W kanale nadgarstka między wyniosłościami promieniową i łokciową przebiega ścięgno mięśnia", "odpowiedzi": {"A": "prostownika łokciowego nadgarstka", "B": "zginacza powierzchownego palców", "C": "zginacza krótkiego palca małego", "D": "prostownika palców"}, "poprawna": "B", "wyjasnienie": "W kanale nadgarstka biegną ścięgna zginaczy palców (powierzchownego i głębokiego), zginacza długiego kciuka oraz nerw pośrodkowy. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2023, czerwiec 2025, czerwiec 2026, styczeń 2026).", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-297", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Wskazaniem do oklepywania klatki piersiowej jest", "odpowiedzi": {"A": "rozstrzenie oskrzeli z krwawieniem do dróg oddechowych", "B": "przewlekłe zapalenie oskrzeli", "C": "osteoporoza w obrębie żeber", "D": "odma opłucnej"}, "poprawna": "B", "wyjasnienie": "Oklepywanie klatki piersiowej ułatwia odkrztuszanie wydzieliny w przewlekłym zapaleniu oskrzeli. Krwawienie, odma i osteoporoza żeber są przeciwwskazaniami. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2023, czerwiec 2025, czerwiec 2026).", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-298", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Przeciwwskazaniem do wykonania masażu klasycznego mięśni przykręgosłupowych jest", "odpowiedzi": {"A": "dyskopatia w odcinku piersiowym kręgosłupa bez objawów korzeniowych", "B": "zespół bólowy odcinka lędźwiowego kręgosłupa w okresie przewlekłym", "C": "zesztywniające zapalenie stawów w okresie silnego zaostrzenia", "D": "skolioza funkcjonalna bez dolegliwości bólowych"}, "poprawna": "C", "wyjasnienie": "Silne zaostrzenie choroby zapalnej (ZZSK) jest przeciwwskazaniem do masażu. Stany przewlekłe bez zaostrzenia są wskazaniami. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2023, czerwiec 2025, czerwiec 2026, styczeń 2026).", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-299", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Przeciwwskazaniem do wykonywania masażu izometrycznego jest", "odpowiedzi": {"A": "ograniczenie ruchomości kończyny po zdjęciu opatrunku gipsowego", "B": "zanik mięśni na skutek ograniczenia aktywności fizycznej", "C": "spastyczność mięśni jako konsekwencja udaru mózgu", "D": "osłabienie siły mięśniowej po przebytym urazie"}, "poprawna": "C", "wyjasnienie": "Napinanie mięśni spastycznych nasila ich napięcie, dlatego spastyczność po udarze jest przeciwwskazaniem do masażu izometrycznego. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2025).", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-300", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Zastosowanie techniki wibracji podczas masażu kończyn górnych jest przeciwwskazane w przypadku", "odpowiedzi": {"A": "reumatoidalnego zapalenia stawów", "B": "zmian zwyrodnieniowych stawów", "C": "choroby Raynauda", "D": "koślawych kolan"}, "poprawna": "C", "wyjasnienie": "Wibracja może wywołać skurcz naczyń, więc w chorobie Raynauda jest przeciwwskazana. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2025).", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-301", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Czas trwania pojedynczego zabiegu masażu u osoby dorosłej nie zależy od", "odpowiedzi": {"A": "rodzaju schorzenia rozpoznanego u pacjenta", "B": "aktualnego stanu zdrowia pacjenta", "C": "wielkości powierzchni masowanej", "D": "płci osoby masowanej"}, "poprawna": "D", "wyjasnienie": "Czas zabiegu zależy od schorzenia, stanu pacjenta i wielkości masowanej powierzchni, a nie od płci. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2025).", "zrodlo": "MED.10.4.3"},
  {"id": "MED10-302", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "W masażu klasycznym grzbietu głaskanie głębokie wykonuje się", "odpowiedzi": {"A": "wzdłuż grzebieni łopatek, rozpoczynając od wyrostka barkowego łopatki", "B": "w przestrzeniach międzyżebrowych, w kierunku do kątów żeber", "C": "od kręgosłupa, w kierunku na oba boki dołów pachowych", "D": "wzdłuż kręgosłupa, od wyrostka kolczystego C7 do L5"}, "poprawna": "C", "wyjasnienie": "Głaskanie głębokie grzbietu prowadzi się od kręgosłupa ku bokom, do dołów pachowych, czyli w kierunku węzłów chłonnych pachowych. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2025).", "zrodlo": "MED.10.4.5"},
  {"id": "MED10-303", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "W trakcie wykonywania masażu limfatycznego dochodzi do", "odpowiedzi": {"A": "poprawy przepływów naczyniowych płynów ustrojowych", "B": "zaburzenia dystrybucji substancji odżywczych", "C": "podwyższenia napięcia mięśniowego", "D": "zmniejszenia ukrwienia tkanek"}, "poprawna": "A", "wyjasnienie": "Drenaż limfatyczny poprawia przepływ chłonki i płynu tkankowego, co zmniejsza obrzęk. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2025, styczeń 2026).", "zrodlo": "MED.10.3.5"},
  {"id": "MED10-304", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Rozcieranie klasyczne okolicy stawu wpływa na", "odpowiedzi": {"A": "nagromadzenie się produktów przemiany materii w tkankach okołostawowych", "B": "przyspieszenie metabolizmu komórkowego torebki stawowej", "C": "zmniejszenie ilości wydzielanej mazi w stawie", "D": "usunięcie obrzęku wewnątrzstawowego"}, "poprawna": "B", "wyjasnienie": "Rozcieranie okolicy stawu przekrwia ją i przyspiesza przemianę materii w torebce stawowej. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2023, czerwiec 2025, czerwiec 2026, styczeń 2026).", "zrodlo": "MED.10.2.15"},
  {"id": "MED10-305", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Technika roztrząsania stosowana w masażu jest odmianą", "odpowiedzi": {"A": "rozcierania", "B": "ugniatania", "C": "rolowania", "D": "wibracji"}, "poprawna": "D", "wyjasnienie": "Roztrząsanie należy do technik drgających, czyli jest odmianą wibracji wykonywaną na rozluźnionym mięśniu lub kończynie. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2023, czerwiec 2025, czerwiec 2026, styczeń 2026).", "zrodlo": "MED.10.2.15"},
  {"id": "MED10-306", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Podczas palpacyjnej lokalizacji wyrostka kruczego łopatki opuszki palców należy przyłożyć", "odpowiedzi": {"A": "powyżej głowy kości ramiennej po stronie bocznej", "B": "poniżej obojczyka w jego części przyśrodkowej", "C": "powyżej grzebienia łopatki w środkowej części", "D": "poniżej obojczyka w jego części bocznej"}, "poprawna": "D", "wyjasnienie": "Wyrostek kruczy wyczuwa się poniżej bocznej części obojczyka, w dole podobojczykowym. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2023, czerwiec 2025, czerwiec 2026).", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-307", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Przyczep początkowy głowy przyśrodkowej mięśnia mostkowo-obojczykowo-sutkowego wyszukuje się palpacyjnie na wysokości", "odpowiedzi": {"A": "wyrostka rylcowatego kości skroniowej", "B": "wyrostka sutkowego kości skroniowej", "C": "końca mostkowego obojczyka", "D": "rękojeści mostka"}, "poprawna": "D", "wyjasnienie": "Głowa przyśrodkowa (mostkowa) mięśnia mostkowo-obojczykowo-sutkowego zaczyna się na rękojeści mostka. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, styczeń 2023, czerwiec 2025, styczeń 2025, styczeń 2026).", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-308", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Diagnostyka układu mięśnia piersiowego większego w masażu tensegracyjnym obejmuje między innymi ocenę wrażliwości uciskowej", "odpowiedzi": {"A": "kolca biodrowego przedniego górnego", "B": "nadkłykcia bocznego kości ramiennej", "C": "kości grochowatej", "D": "guza kulszowego"}, "poprawna": "A", "wyjasnienie": "Diagnostyka układu mięśnia piersiowego większego w masażu tensegracyjnym obejmuje m.in. ocenę uciskową kolca biodrowego przedniego górnego. Pytanie z egzaminu MED.10 (sesja: styczeń 2022).", "zrodlo": "MED.10.4.10"},
  {"id": "MED10-309", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Ból umiejscowiony w okolicy przyczepu mięśni prostowników nadgarstka i palców do nadkłykcia bocznego kości ramiennej jest objawem wskazującym na zespół", "odpowiedzi": {"A": "cieśni kanału nadgarstka", "B": "łokcia tenisisty", "C": "łokcia golfisty", "D": "de Quervaina"}, "poprawna": "B", "wyjasnienie": "Łokieć tenisisty to entezopatia przyczepów prostowników na nadkłykciu bocznym. Łokieć golfisty dotyczy nadkłykcia przyśrodkowego. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2023, czerwiec 2025).", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-310", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Choroba o podłożu autoimmunologicznym, prowadząca do powstawania zmian zwyrodnieniowo-przeprostnych oraz upośledzenia funkcji stawów, której jednym z objawów jest sztywność poranna, to", "odpowiedzi": {"A": "zesztywniające zapalenie stawów", "B": "reumatoidalne zapalenie stawów", "C": "stwardnienie rozsiane", "D": "twardzina układowa"}, "poprawna": "B", "wyjasnienie": "RZS to autoimmunologiczne zapalenie błony maziowej ze sztywnością poranną. Prowadzi do zniekształceń i upośledzenia funkcji stawów. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2023, czerwiec 2025, czerwiec 2026).", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-311", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Wadę kończyny dolnej polegającą na ustawieniu stopy w pozycji zgięcia podeszwowego, odwrócenia i przywiedzenia, określa się jako stopę", "odpowiedzi": {"A": "końsko-szpotawą", "B": "płasko-koślawą", "C": "wydrążoną", "D": "piętową"}, "poprawna": "A", "wyjasnienie": "Stopa końsko-szpotawa jest zgięta podeszwowo (końska), odwrócona i przywiedziona (szpotawa). Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2025, styczeń 2026).", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-312", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Skrócenie mięśnia mostkowo-obojczykowo-sutkowego z powodu jego zbliznowacenia może spowodować", "odpowiedzi": {"A": "podwichnięcie kręgu szyjnego", "B": "dyskopatię odcinka szyjnego", "C": "skoliozę idiopatyczną", "D": "kręcz szyi"}, "poprawna": "D", "wyjasnienie": "Przykurcz lub zbliznowacenie mięśnia mostkowo-obojczykowo-sutkowego przechyla głowę w jego stronę i rotuje w przeciwną, co nazywamy kręczem szyi. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2025).", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-313", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Który czynnik nie ma wpływu na występowanie obrzęków kończyn dolnych?", "odpowiedzi": {"A": "Umiarkowana aktywność fizyczna dostosowana do stanu klinicznego pacjenta", "B": "Odzież, uciskająca okolice pachwin, kolan i brzucha", "C": "Niedostateczne nawodnienie organizmu", "D": "Nadmierna podaż soli w diecie"}, "poprawna": "A", "wyjasnienie": "Umiarkowana aktywność fizyczna pobudza pompę mięśniową i zapobiega obrzękom. Ucisk odzieży i nadmiar soli im sprzyjają. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2023, czerwiec 2025, czerwiec 2026).", "zrodlo": "MED.10.3.1"},
  {"id": "MED10-314", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Wada postawy charakteryzująca się cofnięciem dolnej części mostka wraz z przylegającymi żebrami nazywa się", "odpowiedzi": {"A": "klatką piersiową lejkowatą", "B": "klatką piersiową kurzą", "C": "garbem żebrowym", "D": "skoliozą"}, "poprawna": "A", "wyjasnienie": "Klatka piersiowa lejkowata ma zapadnięty dolny odcinek mostka z żebrami. Klatka kurza ma mostek uwypuklony. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2023, styczeń 2023, czerwiec 2025, styczeń 2025, czerwiec 2026).", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-315", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Tydzień po zdjęciu opatrunku gipsowego z kończyny, w celu poprawienia elastyczności tkanek oraz zwiększenia ruchomości w stawach objętych wcześniej opatrunkiem gipsowym, zabieg masażu zaleca się połączyć", "odpowiedzi": {"A": "z ćwiczeniami czynnymi z oporem", "B": "z biczami szkockimi", "C": "z kąpielą wirową", "D": "z krioterapią"}, "poprawna": "C", "wyjasnienie": "Kąpiel wirowa ogrzewa i rozluźnia tkanki, więc dobrze przygotowuje je do masażu i ćwiczeń po unieruchomieniu. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2025).", "zrodlo": "MED.10.3.7"},
  {"id": "MED10-316", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "U pacjenta po amputacji powyżej stawu kolanowego zmniejszenie przykurczów osiąga się przez połączenie masażu klasycznego z ćwiczeniami wzmacniającymi mięśnie", "odpowiedzi": {"A": "prostowniki i przywodziciele uda", "B": "prostowniki i odwodziciele uda", "C": "zginacze i przywodziciele uda", "D": "zginacze i odwodziciele uda"}, "poprawna": "A", "wyjasnienie": "Kikut uda ma skłonność do przykurczu zgięciowo-odwiedzeniowego, dlatego wzmacnia się prostowniki i przywodziciele uda. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2023, czerwiec 2025, czerwiec 2026).", "zrodlo": "MED.10.3.7"},
  {"id": "MED10-317", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Na zabieg masażu tensegracyjnego zgłosił się pacjent z dolegliwościami bólowymi w obrębie bocznej powierzchni kości piętowej w miejscu przyczepu troczka górnego mięśni strzałkowych. Taki objaw występuje w układzie mięśnia", "odpowiedzi": {"A": "czworobocznego grzbietu", "B": "piersiowego większego", "C": "najszerszego grzbietu", "D": "zębatego przedniego"}, "poprawna": "C", "wyjasnienie": "W koncepcji masażu tensegracyjnego dolegliwości w okolicy bocznej kości piętowej (troczek mięśni strzałkowych) przypisuje się układowi mięśnia najszerszego grzbietu. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2023, styczeń 2023, czerwiec 2025, styczeń 2025, czerwiec 2026, styczeń 2026).", "zrodlo": "MED.10.4.10"},
  {"id": "MED10-318", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "U 8-miesięcznego pacjenta z lewostronnym wrodzonym kręczem szyi pochodzenia mięśniowego masażysta w celu rozluźnienia, a następnie rozciągnięcia przykurczonych mięśni powinien wykonać masaż", "odpowiedzi": {"A": "klasyczny uzupełniony masażem punktowym", "B": "klasyczny uzupełniony masażem stawowym", "C": "segmentarny uzupełniony elektroterapią", "D": "segmentarny uzupełniony krioterapią"}, "poprawna": "A", "wyjasnienie": "W kręczu mięśniowym u niemowlęcia łączy się delikatny masaż klasyczny z punktowym, a potem rozciąga się przykurczone mięśnie. Pytanie z egzaminu MED.10 (sesja: styczeń 2022).", "zrodlo": "MED.10.4.3"},
  {"id": "MED10-319", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "W masażu startowym kończyn dolnych u sprintera, biorącego udział w zawodach na otwartym stadionie w chłodny dzień, należy zastosować środki wspomagające masaż o charakterze", "odpowiedzi": {"A": "przeciwbólowym", "B": "natłuszczającym", "C": "rozgrzewającym", "D": "chłodzącym"}, "poprawna": "C", "wyjasnienie": "W chłodny dzień przed startem stosuje się środki rozgrzewające, które przekrwiają mięśnie i chronią je przed wychłodzeniem. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2023, styczeń 2023, czerwiec 2025, styczeń 2025, czerwiec 2026, styczeń 2026).", "zrodlo": "MED.10.5.2"},
  {"id": "MED10-320", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "Której techniki nie stosuje się podczas wykonywania kosmetycznego masażu twarzy?", "odpowiedzi": {"A": "oklepywania muskającego policzków", "B": "rozcierania w okolicy skroni", "C": "rolowania dolnych powiek", "D": "głaskania policzków"}, "poprawna": "C", "wyjasnienie": "Skóra dolnych powiek jest bardzo cienka i delikatna, dlatego nie stosuje się na niej rolowania. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2023, czerwiec 2025, czerwiec 2026).", "zrodlo": "MED.10.6.2"},
  {"id": "MED10-321", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "U pacjenta skarżącego się na ogólne zmęczenie psychofizyczne, zaburzenia snu i nadmierny stres, masażysta w celu poprawy stanu ogólnego powinien wykonać masaż", "odpowiedzi": {"A": "gorącymi kamieniami całego ciała", "B": "izometryczny kończyn dolnych", "C": "limfatyczny kończyn górnych", "D": "segmentarny grzbietu"}, "poprawna": "A", "wyjasnienie": "Masaż gorącymi kamieniami działa relaksacyjnie i rozgrzewająco, więc dobrze odpowiada na zmęczenie psychofizyczne i stres. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, czerwiec 2025).", "zrodlo": "MED.10.6.1"},
  {"id": "MED10-322", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "Przed pierwszym masażem aromaterapeutycznym całego ciała należy", "odpowiedzi": {"A": "wykonać próbę uczuleniową na dobrany olejek bezpośrednio przed zabiegiem", "B": "wykonać próbę uczuleniową na dobrany olejek minimum 12 godzin wcześniej", "C": "przygotować około 10 ml olejku eterycznego do masażu ciała", "D": "przygotować co najmniej trzy rodzaje olejków eterycznych"}, "poprawna": "B", "wyjasnienie": "Próbę uczuleniową na olejek wykonuje się z wyprzedzeniem (co najmniej 12 godzin), aby zdążyła wystąpić ewentualna reakcja skórna. Pytanie z egzaminu MED.10 (sesja: styczeń 2022, styczeń 2023, czerwiec 2025, styczeń 2025, styczeń 2026).", "zrodlo": "MED.10.6.3"},
  {"id": "MED10-323", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "W ruchu zgięcia grzbietowego (prostowania) stopy bierze udział głównie mięsień", "odpowiedzi": {"A": "trójgłowy łydki", "B": "strzałkowy długi", "C": "piszczelowy tylny", "D": "piszczelowy przedni"}, "poprawna": "D", "wyjasnienie": "Mięsień piszczelowy przedni zgina stopę grzbietowo. Trójgłowy łydki, strzałkowy długi i piszczelowy tylny zginają ją podeszwowo. Pytanie z egzaminu MED.10 (sesja: styczeń 2023, styczeń 2025).", "zrodlo": "MED.10.2.11"},
  {"id": "MED10-324", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Pasmo biodrowo-piszczelowe jest strukturą łącznotkankową odchodzącą od między innymi mięśni", "odpowiedzi": {"A": "pośladkowego wielkiego i naprężacza powięzi szerokiej", "B": "pośladkowego małego i naprężacza powięzi szerokiej", "C": "pośladkowego małego i pośladkowego średniego", "D": "pośladkowego wielkiego i pośladkowego małego"}, "poprawna": "A", "wyjasnienie": "Do pasma biodrowo-piszczelowego wnikają włókna mięśnia naprężacza powięzi szerokiej i pośladkowego wielkiego. Pytanie z egzaminu MED.10 (sesja: styczeń 2023, styczeń 2024, styczeń 2025, styczeń 2026).", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-325", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Strukturą łącznotkankową wzmacniającą staw obojczykowo-barkowy jest więzadło", "odpowiedzi": {"A": "międzyobojczykowe", "B": "kruczo-obojczykowe", "C": "żebrowo-obojczykowe", "D": "mostkowo-obojczykowe"}, "poprawna": "B", "wyjasnienie": "Więzadło kruczo-obojczykowe (części czworoboczna i stożkowata) stabilizuje staw obojczykowo-barkowy. Pozostałe wymienione więzadła wzmacniają staw mostkowo-obojczykowy. Pytanie z egzaminu MED.10 (sesja: styczeń 2023, styczeń 2024, styczeń 2025).", "zrodlo": "MED.10.2.8"},
  {"id": "MED10-326", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Wskazaniem do wykonywania masażu powłok brzusznych jest", "odpowiedzi": {"A": "okres menstruacji", "B": "zaparcie nawykowe", "C": "ostra kamica wątrobowa", "D": "choroba wrzodowa żołądka z krwawieniem"}, "poprawna": "B", "wyjasnienie": "Zaparcie nawykowe (atoniczne) jest wskazaniem do masażu brzucha. Ostra kamica i krwawienie są przeciwwskazaniami. Pytanie z egzaminu MED.10 (sesja: styczeń 2023, styczeń 2025, styczeń 2026).", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-327", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "W trakcie masażu klasycznego twarz opracowuje się głównie w kierunku węzłów chłonnych", "odpowiedzi": {"A": "pachowych", "B": "przyusznych", "C": "podpotylicznych", "D": "podobojczykowych"}, "poprawna": "B", "wyjasnienie": "W masażu klasycznym twarzy ruchy kieruje się głównie ku węzłom chłonnym przyusznym (przed uszami) i dalej w dół szyi. Pytanie z egzaminu MED.10 (sesja: styczeń 2023, styczeń 2024, styczeń 2025).", "zrodlo": "MED.10.4.5"},
  {"id": "MED10-328", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Masażysta wykonujący manualny drenaż limfatyczny obszaru prawego podbrzusza powinien ruchy masażu kierować do", "odpowiedzi": {"A": "lewych węzłów pachowych", "B": "prawych węzłów pachowych", "C": "lewych węzłów pachwinowych", "D": "prawych węzłów pachwinowych"}, "poprawna": "D", "wyjasnienie": "Chłonka z dolnej części brzucha (poniżej pępka) spływa do węzłów pachwinowych tej samej strony. Pytanie z egzaminu MED.10 (sesja: styczeń 2023, styczeń 2025).", "zrodlo": "MED.10.4.7"},
  {"id": "MED10-329", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Aby wykonać masaż klasyczny stawów skokowych, masażysta powinien ułożyć pacjenta", "odpowiedzi": {"A": "w siadzie na stole do masażu z opuszczonymi podudziami", "B": "w leżeniu tyłem, z wałkiem pod stawami kolanowymi", "C": "w leżeniu tyłem, z wałkiem pod stawami skokowymi", "D": "w siadzie prostym na stole do masażu"}, "poprawna": "B", "wyjasnienie": "Wałek pod kolanami rozluźnia mięśnie kończyny w leżeniu tyłem i dobrze odsłania stawy skokowe. Pytanie z egzaminu MED.10 (sesja: styczeń 2023, styczeń 2024, styczeń 2025, styczeń 2026).", "zrodlo": "MED.10.4.2"},
  {"id": "MED10-330", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Pacjent do masażu grzbietu jest ułożony w pozycji leżenia przodem. Aby maksymalnie rozluźnić mięśnie górnej części grzbietu, do wykonania zabiegu masażysta powinien", "odpowiedzi": {"A": "podłożyć wałek pod brzuch pacjenta", "B": "podłożyć płaską poduszkę pod czoło pacjenta", "C": "umieścić kliny pod obręczami barkowymi pacjenta", "D": "umieścić ręcznik pod kolcami biodrowymi przednimi górnymi"}, "poprawna": "C", "wyjasnienie": "Kliny pod obręczami barkowymi w leżeniu przodem rozluźniają mięśnie górnej części grzbietu, bo barki nie opadają w przód. Pytanie z egzaminu MED.10 (sesja: styczeń 2023, styczeń 2025, styczeń 2026).", "zrodlo": "MED.10.4.2"},
  {"id": "MED10-331", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Odpowiednią pozycją do wykonania masażu izometrycznego mięśnia trójgłowego łydki jest", "odpowiedzi": {"A": "leżenie na boku strony masowanej z ugiętym stawem kolanowym", "B": "leżenie przodem, wałek włożony pod stawami skokowymi", "C": "leżenie tyłem z nogami prostymi w stawach kolanowych", "D": "pozycja siedząca z podudziami i stopami zwieszonymi"}, "poprawna": "B", "wyjasnienie": "Wałek pod stawami skokowymi w leżeniu przodem lekko zgina kolana i ustawia mięsień trójgłowy łydki w pozycji do izometrycznego napinania. Pytanie z egzaminu MED.10 (sesja: styczeń 2023, styczeń 2025).", "zrodlo": "MED.10.4.10"},
  {"id": "MED10-332", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Na wyrostku kruczym łopatki lokalizuje się palpacyjnie przyczepy między innymi mięśni", "odpowiedzi": {"A": "kruczo-ramiennego i dwugłowego ramienia", "B": "podgrzebieniowego i nadgrzebieniowego", "C": "naramiennego i trójgłowego ramienia", "D": "ramiennego i łokciowego"}, "poprawna": "A", "wyjasnienie": "Na wyrostku kruczym przyczepiają się mięśnie kruczo-ramienny, krótka głowa dwugłowego ramienia i piersiowy mniejszy. Pytanie z egzaminu MED.10 (sesja: styczeń 2023, styczeń 2024, styczeń 2025, styczeń 2026).", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-333", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "W obrębie nadkłykcia bocznego kości ramiennej przyczepione są między innymi mięśnie", "odpowiedzi": {"A": "nawrotny obły, zginacz powierzchowny palców", "B": "zginacz promieniowy nadgarstka, dłoniowy długi", "C": "ramienno-promieniowy, zginacz łokciowy nadgarstka", "D": "odwracacz, prostownik promieniowy nadgarstka długi"}, "poprawna": "D", "wyjasnienie": "Z okolicy nadkłykcia bocznego zaczynają się prostowniki nadgarstka i palców oraz odwracacz. Zginacze i nawrotny obły zaczynają się na nadkłykciu przyśrodkowym. Pytanie z egzaminu MED.10 (sesja: styczeń 2023, styczeń 2024, styczeń 2025, styczeń 2026).", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-334", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Na którym elemencie kostnym należy dokonać oceny wrażliwości uciskowej, przeprowadzając diagnostykę układu mięśnia najszerszego grzbietu, w masażu tensegracyjnym?", "odpowiedzi": {"A": "Kości grochowatej", "B": "Kości klinowatej przyśrodkowej", "C": "Kolcu biodrowym przednim górnym", "D": "Nadkłykciu bocznym kości ramiennej"}, "poprawna": "A", "wyjasnienie": "W diagnostyce układu mięśnia najszerszego grzbietu w masażu tensegracyjnym ocenia się wrażliwość uciskową kości grochowatej. Pytanie z egzaminu MED.10 (sesja: styczeń 2023).", "zrodlo": "MED.10.4.10"},
  {"id": "MED10-335", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Odstawanie przyśrodkowego brzegu łopatki i jednoczesny brak unoszenia kończyny górnej ponad poziom jest objawem porażenia mięśnia", "odpowiedzi": {"A": "podłopatkowego", "B": "podgrzebieniowego", "C": "zębatego przedniego", "D": "piersiowego większego"}, "poprawna": "C", "wyjasnienie": "Mięsień zębaty przedni dociska łopatkę do klatki piersiowej i rotuje ją przy unoszeniu ręki powyżej poziomu. Jego porażenie daje łopatkę skrzydłowatą. Pytanie z egzaminu MED.10 (sesja: styczeń 2023, styczeń 2025).", "zrodlo": "MED.10.3.2"},
  {"id": "MED10-336", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Ćwiczenia czynne w odciążeniu z dawkowanym oporem wykonywane po zabiegu masażu stosuje się u pacjenta z siłą mięśniową w skali Lovetta ocenianą na", "odpowiedzi": {"A": "więcej niż 0, ale mniej niż 1", "B": "więcej niż 1, ale mniej niż 2", "C": "więcej niż 2, ale mniej niż 3", "D": "więcej niż 3, ale mniej niż 4"}, "poprawna": "C", "wyjasnienie": "Przy sile powyżej 2, ale poniżej 3 w skali Lovetta pacjent pokonuje opór w odciążeniu, ale nie pełny ruch przeciw grawitacji. Pytanie z egzaminu MED.10 (sesja: styczeń 2023, styczeń 2024, styczeń 2025).", "zrodlo": "MED.10.3.7"},
  {"id": "MED10-337", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "W profilaktyce przeciwodleżynowej wskazane jest wykonanie przede wszystkim masażu", "odpowiedzi": {"A": "klasycznego", "B": "okostnowego", "C": "limfatycznego", "D": "segmentarnego"}, "poprawna": "A", "wyjasnienie": "Masaż klasyczny okolic narażonych na ucisk poprawia ukrwienie skóry i tkanek, co zapobiega odleżynom (nie wykonuje się go na już istniejące odleżyny). Pytanie z egzaminu MED.10 (sesja: styczeń 2023, styczeń 2025, styczeń 2026).", "zrodlo": "MED.10.3.4"},
  {"id": "MED10-338", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "W przypadku zabiegu drenażu limfatycznego, u pacjenta z pourazowym obrzękiem stawu skokowego, przede wszystkim należy rozpocząć masaż od okolicy", "odpowiedzi": {"A": "uda", "B": "stopy", "C": "podudzia", "D": "pachwiny"}, "poprawna": "D", "wyjasnienie": "Drenaż kończyny dolnej zaczyna się od części centralnej i węzłów pachwinowych, a dopiero potem opracowuje się udo, podudzie i okolicę obrzęku. Pytanie z egzaminu MED.10 (sesja: styczeń 2023, styczeń 2026).", "zrodlo": "MED.10.4.7"},
  {"id": "MED10-339", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Masaż Shantala u dwuletniego dziecka z mózgowym porażeniem dziecięcym w stopniu umiarkowanym należy zacząć od opracowania", "odpowiedzi": {"A": "powłok brzusznych", "B": "klatki piersiowej", "C": "grzbietu", "D": "twarzy"}, "poprawna": "B", "wyjasnienie": "Masaż Shantala zaczyna się od klatki piersiowej, także u dzieci z mózgowym porażeniem dziecięcym, a twarz opracowuje się na końcu. Pytanie z egzaminu MED.10 (sesja: styczeń 2023, styczeń 2025).", "zrodlo": "MED.10.4.11"},
  {"id": "MED10-340", "dzial": "MED.10.5 Wykonywanie masażu w sporcie", "pytanie": "Masaż treningowy to masaż, który", "odpowiedzi": {"A": "stanowi dla sportowca dodatkowe obciążenie, uwzględnione w tygodniowym planie treningu", "B": "jest wykonywany następnego dnia po zakończeniu treningu i stosowany do dnia startu", "C": "jest przeprowadzany w przerwie między treningami i bezpośrednio po zawodach", "D": "poprzedza rozgrzewkę i jest stosowany bezpośrednio przed startem"}, "poprawna": "A", "wyjasnienie": "Masaż treningowy stanowi dodatkowe obciążenie organizmu sportowca, uwzględnione w planie treningowym. Pytanie z egzaminu MED.10 (sesja: styczeń 2023, styczeń 2025, styczeń 2026).", "zrodlo": "MED.10.5.2"},
  {"id": "MED10-341", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "Wskazaniem do masażu gorącymi kamieniami jest", "odpowiedzi": {"A": "brak czucia powierzchownego", "B": "uczucie zmęczenia mięśni", "C": "zakrzepowe zapalenie żył", "D": "pierwszy trymestr ciąży"}, "poprawna": "B", "wyjasnienie": "Zmęczenie mięśni jest wskazaniem do masażu gorącymi kamieniami. Zaburzenia czucia, zakrzepowe zapalenie żył i I trymestr ciąży są przeciwwskazaniami. Pytanie z egzaminu MED.10 (sesja: styczeń 2023, styczeń 2025, styczeń 2026).", "zrodlo": "MED.10.6.3"},
  {"id": "MED10-342", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "U kobiety w 5. miesiącu ciąży fizjologicznej niepowikłanej, której lekarz zalecił zabiegi masażu celem profilaktyki wystąpienia dolegliwości bólowych odcinka lędźwiowego kręgosłupa, masażysta powinien wykonać masaż", "odpowiedzi": {"A": "relaksacyjny grzbietu", "B": "segmentarny miednicy", "C": "limfatyczny całościowy", "D": "izometryczny pośladków"}, "poprawna": "A", "wyjasnienie": "U ciężarnej w niepowikłanej ciąży stosuje się łagodny, relaksacyjny masaż grzbietu, zwykle w ułożeniu na boku. Pytanie z egzaminu MED.10 (sesja: styczeń 2023, styczeń 2025, styczeń 2026).", "zrodlo": "MED.10.4.11"},
  {"id": "MED10-343", "dzial": "MED.10.6 Wykonywanie masażu prozdrowotnego", "pytanie": "W masażu lipolitycznym, zalecanym do likwidacji cellulitu, wykorzystuje się techniki masażu", "odpowiedzi": {"A": "klasycznego i limfatycznego", "B": "izometrycznego i punktowego", "C": "segmentarnego i klasycznego", "D": "segmentarnego i izometrycznego"}, "poprawna": "A", "wyjasnienie": "Masaż antycellulitowy łączy techniki klasyczne poprawiające ukrwienie z drenażem limfatycznym zmniejszającym zastoje. Pytanie z egzaminu MED.10 (sesja: styczeń 2023, styczeń 2024, styczeń 2025, styczeń 2026).", "zrodlo": "MED.10.6.1"},
  {"id": "MED10-344", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Wskazaniem do wykonania masażu klasycznego powłok brzusznych są", "odpowiedzi": {"A": "kamienie nerkowe", "B": "blizny pooperacyjne", "C": "uchyłki jelita grubego", "D": "stany zapalne dróg żółciowych"}, "poprawna": "B", "wyjasnienie": "Blizny pooperacyjne (po zagojeniu) są wskazaniem do masażu powłok brzusznych. Kamica, uchyłki i stany zapalne dróg żółciowych są przeciwwskazaniami. Pytanie z egzaminu MED.10 (sesja: styczeń 2024).", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-345", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Wskazaniem do wykonania u pacjenta serii zabiegów masażu klasycznego, obejmującego całą kończynę dolną, jest", "odpowiedzi": {"A": "stan po zespoleniu złamania kości piszczelowej w okresie gojenia się rany", "B": "obrzęk stawu skokowego bezpośrednio po urazie", "C": "porażenie nerwu udowego w okresie adaptacji", "D": "zaawansowana postać żylaków podudzi"}, "poprawna": "C", "wyjasnienie": "W okresie adaptacji po porażeniu nerwu udowego masaż całej kończyny poprawia trofikę i przeciwdziała zanikom. Pytanie z egzaminu MED.10 (sesja: styczeń 2024).", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-346", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Podczas wykonywania masażu segmentarnego miednicy w pozycji siedzącej pacjenta należy zachować kierunek opracowywania od", "odpowiedzi": {"A": "odcinka lędźwiowo-krzyżowego kręgosłupa do linii pachowej środkowej", "B": "linii pachowej środkowej do odcinka lędźwiowo-krzyżowego kręgosłupa", "C": "kości krzyżowej, wzdłuż grzebieni biodrowych i pachwin do spojenia łonowego", "D": "spojenia łonowego, wzdłuż pachwin i grzebieni biodrowych do kości krzyżowej"}, "poprawna": "D", "wyjasnienie": "Według klucza CKE masaż segmentarny miednicy w siadzie prowadzi się od spojenia łonowego wzdłuż pachwin i grzebieni biodrowych do kości krzyżowej. Pytanie z egzaminu MED.10 (sesja: styczeń 2024).", "zrodlo": "MED.10.4.9"},
  {"id": "MED10-347", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Siła bodźca w masażu klasycznym powinna być stosowana", "odpowiedzi": {"A": "poniżej progu odczuwania bólu", "B": "powyżej progu odczuwania bólu", "C": "na poziomie minimalnych możliwości wytrzymałościowych pacjenta", "D": "na poziomie maksymalnych możliwości wytrzymałościowych pacjenta"}, "poprawna": "A", "wyjasnienie": "Bodźce masażu dawkuje się poniżej progu bólu. Ból wywołuje obronne napięcie mięśni i reakcje niepożądane. Pytanie z egzaminu MED.10 (sesja: styczeń 2024).", "zrodlo": "MED.10.2.15"},
  {"id": "MED10-348", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Masaż tensegracyjny wykonany w układzie więzadła krzyżowo-guzowego wpływa na ograniczenie", "odpowiedzi": {"A": "dolegliwości bólowych mięśni brzucha", "B": "napięcia spoczynkowego mięśnia naramiennego", "C": "dolegliwości bólowych mięśnia prostownika grzbietu", "D": "napięcia spoczynkowego mięśnia piersiowego większego"}, "poprawna": "C", "wyjasnienie": "Układ więzadła krzyżowo-guzowego łączy mięśnie kulszowo-goleniowe z prostownikiem grzbietu, więc praca na nim zmniejsza dolegliwości prostownika. Pytanie z egzaminu MED.10 (sesja: styczeń 2024).", "zrodlo": "MED.10.4.10"},
  {"id": "MED10-349", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Które struktury tworzą wyniosłość międzykłykciową kości piszczelowej?", "odpowiedzi": {"A": "Guzek boczny i przyśrodkowy", "B": "Nadkłykieć przyśrodkowy i boczny", "C": "Kostka przyśrodkowa i wcięcie strzałkowe", "D": "Powierzchnia stawowa dolna i guzowatość piszczeli"}, "poprawna": "A", "wyjasnienie": "Wyniosłość międzykłykciową tworzą guzek międzykłykciowy przyśrodkowy i boczny, do których przyczepiają się więzadła krzyżowe i łąkotki. Pytanie z egzaminu MED.10 (sesja: styczeń 2024).", "zrodlo": "MED.10.2.8"},
  {"id": "MED10-350", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "U pacjenta z zaawansowaną chorobą Buergera, w celu uzyskania poprawy krążenia w kończynach dolnych należy opracować", "odpowiedzi": {"A": "obie całe kończyny dolne", "B": "wyłącznie dystalne odcinki obu kończyn dolnych", "C": "odcinek lędźwiowy grzbietu i obie kończyny dolne", "D": "wyłącznie grzbiet na wysokości odcinka lędźwiowego kręgosłupa"}, "poprawna": "D", "wyjasnienie": "W zaawansowanej chorobie Buergera nie masuje się bezpośrednio kończyn z niedokrwieniem. Krążenie poprawia się odruchowo, opracowując segmenty lędźwiowe grzbietu. Pytanie z egzaminu MED.10 (sesja: styczeń 2024).", "zrodlo": "MED.10.3.4"},
  {"id": "MED10-351", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "U pacjenta z osteoporozą nie należy wykonywać", "odpowiedzi": {"A": "pionowych ucisków w okolicy kręgosłupa", "B": "ugniatania mięśnia czworogłowego uda", "C": "rozcierania przestrzeni międzyżebrowych", "D": "oklepywania mięśni pośladkowych grzbietową stroną palców"}, "poprawna": "A", "wyjasnienie": "W osteoporozie silne pionowe uciski na kręgosłup grożą złamaniem kompresyjnym kręgów. Pytanie z egzaminu MED.10 (sesja: styczeń 2024).", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-352", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "U pacjenta po przebytym zawale mięśnia sercowego, stanowiącym przyczynę skierowania lekarskiego na masaż segmentarny, zabieg masażu należy rozpocząć od opracowania obszaru", "odpowiedzi": {"A": "kręgosłupa w pozycji siedzącej", "B": "grzbietu w pozycji leżącej przodem", "C": "klatki piersiowej w pozycji siedzącej", "D": "klatki piersiowej w pozycji leżącej tyłem"}, "poprawna": "A", "wyjasnienie": "Masaż segmentarny zaczyna się od opracowania grzbietu przy kręgosłupie, tu w pozycji siedzącej bezpiecznej dla pacjenta kardiologicznego. Klatkę piersiową opracowuje się później. Pytanie z egzaminu MED.10 (sesja: styczeń 2024).", "zrodlo": "MED.10.4.9"},
  {"id": "MED10-353", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Napięcia izometryczne podnoszą ciśnienie tętnicze, dlatego szczególną ostrożność przy masażu izometrycznym należy zachować u pacjenta z", "odpowiedzi": {"A": "płaskostopiem podłużnym bez dolegliwości", "B": "przewlekłym przeciążeniem mięśni karku", "C": "zanikiem mięśni po unieruchomieniu w gipsie", "D": "niewyrównanym nadciśnieniem tętniczym"}, "poprawna": "D", "wyjasnienie": "Wysiłek izometryczny gwałtownie zwiększa ciśnienie tętnicze. U osób z niewyrównanym nadciśnieniem może to być niebezpieczne.", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-354", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Podczas izometrycznego napinania mięśnia w trakcie masażu masażysta powinien dopilnować, aby pacjent", "odpowiedzi": {"A": "wstrzymał oddech na czas całego napięcia", "B": "wykonywał przy tym szybkie ruchy w stawie", "C": "oddychał swobodnie, bez wstrzymywania oddechu", "D": "napinał mięsień z maksymalną siłą przez minutę"}, "poprawna": "C", "wyjasnienie": "Wstrzymanie oddechu przy wysiłku (próba Valsalvy) dodatkowo podnosi ciśnienie tętnicze i obciąża serce.", "zrodlo": "MED.10.4.10"},
  {"id": "MED10-355", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Pacjent leży tyłem z wałkiem pod stawem kolanowym. Które polecenie wywoła izometryczne napięcie mięśnia czworogłowego uda?", "odpowiedzi": {"A": "„Proszę docisnąć tył kolana do wałka i napiąć mięśnie uda”", "B": "„Proszę powoli zgiąć kolano, przyciągając piętę jak najbliżej pośladka”", "C": "„Proszę całkowicie rozluźnić kończynę i oddychać”", "D": "„Proszę obrócić stopę do środka i unieść palce”"}, "poprawna": "A", "wyjasnienie": "Dociskanie dołu podkolanowego do podłoża to próba wyprostu kolana bez ruchu, czyli izometryczny skurcz mięśnia czworogłowego.", "zrodlo": "MED.10.4.10"},
  {"id": "MED10-356", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Izometryczne napięcie mięśni pośladkowych wielkich w leżeniu przodem uzyskuje się poleceniem", "odpowiedzi": {"A": "„Proszę rozluźnić pośladki i wykonać wydech”", "B": "„Proszę unieść obie wyprostowane nogi wysoko nad powierzchnię stołu”", "C": "„Proszę zgiąć kolana i dotknąć piętami pośladków”", "D": "„Proszę mocno zacisnąć pośladki i utrzymać napięcie”"}, "poprawna": "D", "wyjasnienie": "Zaciśnięcie pośladków napina mięśnie pośladkowe wielkie bez ruchu w stawach biodrowych.", "zrodlo": "MED.10.4.10"},
  {"id": "MED10-357", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Termin „tensegracja” (ang. tensegrity) powstał z połączenia angielskich słów oznaczających", "odpowiedzi": {"A": "napięcie i spójność", "B": "tkankę i regenerację narządów", "C": "odruch i segment rdzenia kręgowego", "D": "rozciąganie i siłę skurczu mięśnia"}, "poprawna": "A", "wyjasnienie": "Tensional integrity to spójność struktury utrzymywana przez ciągłą sieć napięć. W ciele tworzą ją mięśnie, powięzi i więzadła.", "zrodlo": "MED.10.3.4"},
  {"id": "MED10-358", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Ocena pacjenta przed masażem tensegracyjnym polega przede wszystkim na", "odpowiedzi": {"A": "pomiarze obwodów kończyny taśmą centymetrową co 4 cm", "B": "wyznaczeniu stref Heada na skórze klatki piersiowej", "C": "badaniu wrażliwości uciskowej w charakterystycznych punktach układu", "D": "ocenie siły wszystkich mięśni kończyn i tułowia w skali Lovetta przed każdym zabiegiem"}, "poprawna": "C", "wyjasnienie": "W masażu tensegracyjnym ocenia się palpacyjnie bolesność i napięcie w punktach (często kostnych) należących do danego układu.", "zrodlo": "MED.10.4.10"},
  {"id": "MED10-359", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Po wykonaniu masażu tensegracyjnego masażysta powinien", "odpowiedzi": {"A": "natychmiast wykonać intensywne oklepywanie całego układu", "B": "ponownie ocenić wrażliwość uciskową badanych punktów", "C": "zalecić pacjentowi unieruchomienie kończyny na tydzień", "D": "zakończyć zabieg bez oceny, bo efekt pojawia się po miesiącu"}, "poprawna": "B", "wyjasnienie": "Porównanie oceny przed zabiegiem i po nim pokazuje, czy napięcie w układzie się zmniejszyło, i pomaga zaplanować kolejne zabiegi.", "zrodlo": "MED.10.4.4"},
  {"id": "MED10-360", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "W skład układu więzadła krzyżowo-guzowego wchodzi m.in.", "odpowiedzi": {"A": "głowa długa mięśnia dwugłowego uda", "B": "część obojczykowa mięśnia piersiowego większego", "C": "mięsień naramienny", "D": "mięsień piszczelowy przedni"}, "poprawna": "A", "wyjasnienie": "Głowa długa mięśnia dwugłowego uda zaczyna się na guzie kulszowym i przechodzi w więzadło krzyżowo-guzowe, a ono łączy się z powięzią i prostownikiem grzbietu.", "zrodlo": "MED.10.4.10"},
  {"id": "MED10-361", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Zmiany odruchowe w segmentach Th1–Th5 po stronie lewej (okolica przedsercowa i przyśrodkowa strona lewej kończyny górnej) mogą być związane z chorobą", "odpowiedzi": {"A": "jelita grubego", "B": "wątroby", "C": "nerek", "D": "serca"}, "poprawna": "D", "wyjasnienie": "Serce jest unerwione z górnych segmentów piersiowych, a ból i przeczulica rzutują na lewą stronę klatki piersiowej i lewą rękę.", "zrodlo": "MED.10.4.9"},
  {"id": "MED10-362", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Przeczulica i zmiany odruchowe w prawej połowie tułowia w segmentach Th6–Th10 mogą wskazywać na chorobę", "odpowiedzi": {"A": "pęcherza moczowego", "B": "wątroby i dróg żółciowych", "C": "trzustki i śledziony po stronie lewej", "D": "serca"}, "poprawna": "B", "wyjasnienie": "Wątroba i pęcherzyk żółciowy rzutują zmiany odruchowe na prawą stronę tułowia i okolicę prawej łopatki.", "zrodlo": "MED.10.4.9"},
  {"id": "MED10-363", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Do chwytów stosowanych w masażu segmentarnym należy", "odpowiedzi": {"A": "krążek stacjonarny", "B": "ruch pompujący", "C": "chwyt piłowania", "D": "chwyt czerpiący"}, "poprawna": "C", "wyjasnienie": "Piłowanie, chwyty nadkolcowe i rozciąganie tkanek to chwyty masażu segmentarnego. Krążki, czerpanie i pompowanie są chwytami drenażu limfatycznego.", "zrodlo": "MED.10.4.9"},
  {"id": "MED10-364", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Przed masażem segmentarnym masażysta ocenia odruchowe zmiany tkankowe, takie jak", "odpowiedzi": {"A": "obrzęk limfatyczny obu kończyn dolnych i objaw Stemmera", "B": "przeczulica skóry, wzmożone napięcie mięśni i zgrubienia tkanki łącznej", "C": "zaburzenia rytmu serca i przewodzenia stwierdzone w spoczynkowym zapisie EKG pacjenta", "D": "zmiany w morfologii krwi i stężeniu glukozy"}, "poprawna": "B", "wyjasnienie": "Choroba narządu daje odczyny w skórze, tkance łącznej, mięśniach i okostnej tych samych segmentów. Masażysta wyszukuje je palpacyjnie.", "zrodlo": "MED.10.4.9"},
  {"id": "MED10-365", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Masaż segmentarny grzbietu rozpoczyna się od segmentów", "odpowiedzi": {"A": "klatki piersiowej i brzucha, a grzbiet opracowuje się dopiero na samym końcu", "B": "najbardziej bolesnych, niezależnie od ich położenia", "C": "szyjnych, a następnie schodzi w dół do kości krzyżowej", "D": "dolnych (okolicy krzyżowo-lędźwiowej) i postępuje ku górze"}, "poprawna": "D", "wyjasnienie": "Masaż odruchowy zaczyna się od segmentów dolnych, a dopiero potem opracowuje się wyższe, co zmniejsza ryzyko niepożądanych przesunięć odruchowych.", "zrodlo": "MED.10.4.9"},
  {"id": "MED10-366", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Masaż segmentarny jest przeciwwskazany u pacjenta z", "odpowiedzi": {"A": "przewlekłym zaparciem nawykowym", "B": "zaburzeniami krążenia obwodowego w okresie przewlekłym", "C": "ostrym stanem zapalnym narządu wewnętrznego z gorączką", "D": "przewlekłym bólem kręgosłupa lędźwiowego"}, "poprawna": "C", "wyjasnienie": "Ostre stany zapalne i gorączka są przeciwwskazaniem do masażu odruchowego. Przewlekłe zaburzenia czynnościowe są wskazaniem.", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-367", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Każdy chwyt manualnego drenażu limfatycznego składa się z", "odpowiedzi": {"A": "fazy ucisku z rozciąganiem skóry i fazy rozluźnienia", "B": "fazy szybkiego oklepywania i fazy silnego ugniatania", "C": "jednej fazy ciągłego, silnego ucisku wykonywanego bez żadnych przerw", "D": "fazy rozgrzania skóry i fazy jej ochłodzenia"}, "poprawna": "A", "wyjasnienie": "Naprzemienny ucisk i rozluźnienie pobudzają rytmiczne skurcze naczyń chłonnych i zasysanie płynu tkankowego.", "zrodlo": "MED.10.4.7"},
  {"id": "MED10-368", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Tempo chwytów w manualnym drenażu limfatycznym powinno być", "odpowiedzi": {"A": "jak najszybsze, by skrócić zabieg", "B": "szybkie i nieregularne", "C": "wolne i rytmiczne", "D": "zmienne, z nagłymi szarpnięciami"}, "poprawna": "C", "wyjasnienie": "Naczynia chłonne kurczą się kilka razy na minutę. Wolne, powtarzalne chwyty wspierają ten rytm.", "zrodlo": "MED.10.4.7"},
  {"id": "MED10-369", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Przy obrzęku pourazowym przedramienia, z zachowanymi węzłami chłonnymi, chłonkę kieruje się do węzłów", "odpowiedzi": {"A": "podkolanowych", "B": "pachowych", "C": "przyusznych", "D": "pachwinowych"}, "poprawna": "B", "wyjasnienie": "Chłonka z kończyny górnej spływa do węzłów pachowych, które w drenażu opracowuje się na początku.", "zrodlo": "MED.10.4.7"},
  {"id": "MED10-370", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Chwyty na brzuchu wykonywane w drenażu limfatycznym w rytmie spokojnego oddechu przeponowego mają na celu", "odpowiedzi": {"A": "rozluźnienie mięśni prostych brzucha przed ćwiczeniami siłowymi", "B": "wywołanie przekrwienia skóry brzucha i wzrost jej ciepłoty", "C": "przyspieszenie wydzielania soku żołądkowego po posiłku", "D": "pobudzenie odpływu chłonki w głębokich pniach chłonnych"}, "poprawna": "D", "wyjasnienie": "Ruchy przepony zmieniają ciśnienie w jamach ciała i „pompują” chłonkę w zbiorniku mleczu i przewodzie piersiowym.", "zrodlo": "MED.10.4.7"},
  {"id": "MED10-371", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Autodrenaż w kompleksowej terapii przeciwobrzękowej to", "odpowiedzi": {"A": "samodzielne wykonywanie przez pacjenta wyuczonych chwytów drenażu", "B": "spontaniczne ustępowanie obrzęku bez żadnego leczenia", "C": "drenaż wykonywany przez dwóch terapeutów jednocześnie", "D": "drenaż wykonywany wyłącznie przez aparat do uciskowego masażu pneumatycznego"}, "poprawna": "A", "wyjasnienie": "Autodrenaż pozwala pacjentowi podtrzymać efekty terapii w domu, zwłaszcza w fazie podtrzymującej.", "zrodlo": "MED.10.4.8"},
  {"id": "MED10-372", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Pielęgnacja skóry jest ważnym elementem terapii obrzęku limfatycznego, ponieważ", "odpowiedzi": {"A": "skóra w obrzęku zawsze jest nadmiernie natłuszczona", "B": "starannie prowadzona pielęgnacja skóry zastępuje drenaż i bandażowanie", "C": "skóra objęta obrzękiem jest podatna na zakażenia, np. różę", "D": "dzięki niej można zrezygnować z kompresjoterapii"}, "poprawna": "C", "wyjasnienie": "Zastój chłonki osłabia miejscową odporność. Nawet drobne skaleczenia mogą prowadzić do zakażeń, które nasilają obrzęk.", "zrodlo": "MED.10.4.8"},
  {"id": "MED10-373", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "Pacjentowi z obrzękiem limfatycznym kończyny należy odradzić", "odpowiedzi": {"A": "noszenie dopasowanego rękawa uciskowego", "B": "korzystanie z sauny i gorących okładów na kończynę", "C": "codzienne nawilżanie skóry kończyny", "D": "wykonywanie zaleconych ćwiczeń w założonym bandażu uciskowym"}, "poprawna": "B", "wyjasnienie": "Ciepło rozszerza naczynia i zwiększa filtrację płynu do tkanek, co nasila obrzęk.", "zrodlo": "MED.10.4.8"},
  {"id": "MED10-374", "dzial": "MED.10.4 Wykonywanie masażu w medycynie", "pytanie": "W fazie podtrzymującej (II) kompleksowej terapii przeciwobrzękowej zamiast bandaży stosuje się zwykle", "odpowiedzi": {"A": "wyłącznie silny masaż klasyczny kończyny raz w miesiącu", "B": "okłady rozgrzewające na całą kończynę", "C": "unieruchomienie kończyny w szynie", "D": "dopasowaną odzież uciskową, np. rękaw lub pończochę"}, "poprawna": "D", "wyjasnienie": "Po zmniejszeniu obrzęku w fazie intensywnej efekt utrzymuje się dobraną odzieżą uciskową, ćwiczeniami i autodrenażem.", "zrodlo": "MED.10.4.8"},
  {"id": "MED10-375", "dzial": "MED.10.3 Podstawy masażu w medycynie", "pytanie": "Przeciwwskazaniem do manualnego drenażu limfatycznego kończyny jest", "odpowiedzi": {"A": "róża (ostre bakteryjne zakażenie skóry) w obrębie kończyny", "B": "obrzęk po skręceniu stawu skokowego w okresie podostrym", "C": "przewlekły obrzęk limfatyczny po usunięciu węzłów pachwinowych", "D": "obrzęk kończyny górnej po mastektomii"}, "poprawna": "A", "wyjasnienie": "Drenaż mógłby rozprzestrzenić ostre zakażenie bakteryjne. Pozostałe obrzęki są typowymi wskazaniami.", "zrodlo": "MED.10.3.3"},
  {"id": "MED10-376", "dzial": "MED.10.2 Podstawy masażu", "pytanie": "Oprócz węzłów pachwinowych węzły chłonne kończyny dolnej skupiają się w", "odpowiedzi": {"A": "dole podkolanowym", "B": "okolicy grzbietu stopy", "C": "okolicy kostki przyśrodkowej", "D": "dole łokciowym"}, "poprawna": "A", "wyjasnienie": "Węzły podkolanowe zbierają chłonkę z części podudzia i stopy. Węzły łokciowe należą do kończyny górnej.", "zrodlo": "MED.10.2.9"},
  {"id": "MED10-377", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Po dostarczeniu automatycznego defibrylatora zewnętrznego (AED) do poszkodowanego bez oddechu należy", "odpowiedzi": {"A": "przerwać uciśnięcia klatki piersiowej na kilka minut, aż urządzenie się nagrzeje", "B": "dotykać poszkodowanego podczas analizy rytmu serca", "C": "włączyć urządzenie i postępować zgodnie z jego poleceniami głosowymi", "D": "przykleić elektrody na ubranie poszkodowanego"}, "poprawna": "C", "wyjasnienie": "AED prowadzi ratownika komunikatami głosowymi. Elektrody nakleja się na odsłoniętą klatkę piersiową, a podczas analizy i wyładowania nikt nie dotyka poszkodowanego.", "zrodlo": "MED.10.1.8"},
  {"id": "MED10-378", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Przytomny dorosły zadławił się i nie może kaszleć ani mówić. Ratownik powinien", "odpowiedzi": {"A": "podać mu wodę do picia, aby popił ciało obce", "B": "ułożyć go w pozycji bocznej bezpiecznej i czekać", "C": "ułożyć go na plecach i od razu rozpocząć oddechy ratownicze metodą usta-usta", "D": "wykonać do 5 uderzeń między łopatki, a potem do 5 uciśnięć nadbrzusza"}, "poprawna": "D", "wyjasnienie": "Przy ciężkiej niedrożności dróg oddechowych u przytomnego dorosłego stosuje się naprzemiennie uderzenia w plecy i uciśnięcia nadbrzusza (rękoczyn Heimlicha).", "zrodlo": "MED.10.1.8"},
  {"id": "MED10-379", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Podczas napadu drgawek padaczkowych u pacjenta w gabinecie masażysta powinien", "odpowiedzi": {"A": "siłą przytrzymywać kończyny i głowę pacjenta, aby jak najszybciej zatrzymać drgawki", "B": "zabezpieczyć głowę pacjenta przed urazem i nie wkładać mu niczego do ust", "C": "polewać pacjenta zimną wodą do ustania drgawek", "D": "włożyć pacjentowi do ust twardy przedmiot"}, "poprawna": "B", "wyjasnienie": "Drgawek nie należy powstrzymywać. Trzeba chronić głowę i usunąć niebezpieczne przedmioty, a po napadzie ułożyć pacjenta w pozycji bezpiecznej.", "zrodlo": "MED.10.1.8"},
  {"id": "MED10-380", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Pacjent z cukrzycą jest przytomny, spocony, drżący i pobudzony. Masażysta podejrzewa hipoglikemię i powinien", "odpowiedzi": {"A": "podać pacjentowi insulinę z jego zestawu", "B": "podać pacjentowi doustnie cukier, np. słodki napój", "C": "zalecić mu dokończenie zabiegu i odpoczynek", "D": "ułożyć go na brzuchu i rozpocząć uciśnięcia klatki piersiowej"}, "poprawna": "B", "wyjasnienie": "Przytomnej osobie, która może połykać, podaje się szybko wchłaniane węglowodany. Insulina pogłębiłaby hipoglikemię.", "zrodlo": "MED.10.1.8"},
  {"id": "MED10-381", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Oceniając oddech u nieprzytomnego poszkodowanego, ratownik po udrożnieniu dróg oddechowych", "odpowiedzi": {"A": "patrzy, słucha i wyczuwa oddech przez nie dłużej niż 10 sekund", "B": "sprawdza tętno na tętnicy promieniowej przez co najmniej 30 sekund", "C": "uciska mostek, aby wywołać kaszel", "D": "liczy oddechy przez pełną minutę"}, "poprawna": "A", "wyjasnienie": "Ocena oddechu trwa do 10 sekund. Brak prawidłowego oddechu oznacza konieczność wezwania pomocy i rozpoczęcia RKO.", "zrodlo": "MED.10.1.8"},
  {"id": "MED10-382", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Odpady medyczne zakaźne, np. materiały skażone krwią, gromadzi się w workach koloru", "odpowiedzi": {"A": "niebieskiego", "B": "zielonego", "C": "czarnego", "D": "czerwonego"}, "poprawna": "D", "wyjasnienie": "Zgodnie z przepisami o odpadach medycznych odpady zakaźne zbiera się do czerwonych worków, a specjalne do żółtych.", "zrodlo": "MED.10.1.7"},
  {"id": "MED10-383", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Obowiązek oceny i dokumentowania ryzyka zawodowego na stanowisku masażysty spoczywa na", "odpowiedzi": {"A": "inspektorze Państwowej Inspekcji Pracy", "B": "lekarzu medycyny pracy", "C": "pracodawcy", "D": "pracowniku zatrudnionym na tym stanowisku"}, "poprawna": "C", "wyjasnienie": "Kodeks pracy nakłada na pracodawcę obowiązek oceny ryzyka zawodowego i poinformowania o nim pracowników.", "zrodlo": "MED.10.1.3"},
  {"id": "MED10-384", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Przed dopuszczeniem nowego masażysty do pracy pracodawca musi zapewnić mu", "odpowiedzi": {"A": "szkolenie z obsługi kasy fiskalnej", "B": "szkolenie wstępne BHP: instruktaż ogólny i stanowiskowy", "C": "kurs języka obcego zawodowego", "D": "wyłącznie szkolenie okresowe BHP, przeprowadzone po pierwszym roku pracy"}, "poprawna": "B", "wyjasnienie": "Szkolenie wstępne (instruktaż ogólny i stanowiskowy) jest warunkiem dopuszczenia do pracy. Szkolenia okresowe powtarza się później.", "zrodlo": "MED.10.1.3"},
  {"id": "MED10-385", "dzial": "MED.10.1 Bezpieczeństwo i higiena pracy", "pytanie": "Przewlekłe przeciążenia nadgarstków i kciuków u masażysty można ograniczyć przez", "odpowiedzi": {"A": "stałe stosowanie ucisku samym kciukiem", "B": "zwiększenie liczby zabiegów w ciągu dnia i rezygnację z przerw", "C": "pracę z użyciem ciężaru ciała i zmienianie chwytów", "D": "pracę z maksymalnie zgiętymi nadgarstkami"}, "poprawna": "C", "wyjasnienie": "Ergonomiczna technika i różnicowanie chwytów rozkładają obciążenie i zapobiegają przeciążeniom stawów rąk.", "zrodlo": "MED.10.1.5"},
  {"id": "MED10-386", "dzial": "MED.10.7 Język obcy zawodowy", "pytanie": "Masażysta mówi do pacjenta: „Take a deep breath, please”. Pacjent powinien", "odpowiedzi": {"A": "obrócić się na plecy", "B": "rozluźnić ramiona", "C": "wstrzymać oddech", "D": "wziąć głęboki wdech"}, "poprawna": "D", "wyjasnienie": "Take a deep breath znaczy „weź głęboki wdech”. Wstrzymać oddech to hold your breath.", "zrodlo": "MED.10.7.2"},
  {"id": "MED10-387", "dzial": "MED.10.7 Język obcy zawodowy", "pytanie": "Polecenie „Please turn onto your back” oznacza:", "odpowiedzi": {"A": "„Proszę obrócić się na plecy”", "B": "„Proszę usiąść na krawędzi stołu”", "C": "„Proszę położyć się na brzuchu”", "D": "„Proszę obrócić głowę w prawo”"}, "poprawna": "A", "wyjasnienie": "Turn onto your back to obrót na plecy. Na brzuch to turn onto your stomach.", "zrodlo": "MED.10.7.2"},
  {"id": "MED10-388", "dzial": "MED.10.7 Język obcy zawodowy", "pytanie": "Masażysta pyta pacjenta: „Is the pressure OK?”. Pyta o to, czy", "odpowiedzi": {"A": "temperatura w gabinecie jest odpowiednia", "B": "pacjent jest gotowy do zabiegu", "C": "ciśnienie krwi jest prawidłowe", "D": "siła nacisku jest odpowiednia"}, "poprawna": "D", "wyjasnienie": "Pressure w kontekście masażu oznacza siłę nacisku. Ciśnienie krwi to blood pressure.", "zrodlo": "MED.10.7.2"},
  {"id": "MED10-389", "dzial": "MED.10.7 Język obcy zawodowy", "pytanie": "Pacjent zgłasza: „I have pain in my lower back”. Ból dotyczy", "odpowiedzi": {"A": "tylnej strony kolana", "B": "dolnej części brzucha", "C": "okolicy lędźwiowej", "D": "karku i obręczy barkowej"}, "poprawna": "C", "wyjasnienie": "Lower back to dolna część pleców, czyli okolica lędźwiowa. Kark to neck.", "zrodlo": "MED.10.7.2"},
  {"id": "MED10-390", "dzial": "MED.10.7 Język obcy zawodowy", "pytanie": "Angielskie słowo „swelling” oznacza", "odpowiedzi": {"A": "obrzęk", "B": "zdrętwienie", "C": "zasinienie", "D": "zaczerwienienie"}, "poprawna": "A", "wyjasnienie": "Swelling to obrzęk, bruise to siniak, redness to zaczerwienienie, a numbness to zdrętwienie.", "zrodlo": "MED.10.7.1"},
  {"id": "MED10-391", "dzial": "MED.10.7 Język obcy zawodowy", "pytanie": "Wyrażenie „contraindication to massage” oznacza", "odpowiedzi": {"A": "skierowanie lekarskie na zabieg masażu", "B": "przeciwwskazanie do masażu", "C": "wskazanie do masażu", "D": "czas trwania masażu"}, "poprawna": "B", "wyjasnienie": "Contraindication to przeciwwskazanie, indication wskazanie, a referral skierowanie.", "zrodlo": "MED.10.7.1"},
  {"id": "MED10-392", "dzial": "MED.10.7 Język obcy zawodowy", "pytanie": "Angielskie słowo „ankle” oznacza", "odpowiedzi": {"A": "staw łokciowy", "B": "staw promieniowo-nadgarstkowy", "C": "staw kolanowy", "D": "staw skokowy (kostkę)"}, "poprawna": "D", "wyjasnienie": "Ankle to staw skokowy, knee kolano, wrist nadgarstek, a elbow łokieć.", "zrodlo": "MED.10.7.1"},
  {"id": "MED10-393", "dzial": "MED.10.8 Kompetencje personalne i społeczne", "pytanie": "Przykładem komunikatu „ja” jest wypowiedź:", "odpowiedzi": {"A": "„Czuję niepokój, gdy pacjent spóźnia się bez uprzedzenia, bo skraca to czas kolejnego zabiegu”", "B": "„Wszyscy pacjenci są nieodpowiedzialni i nie szanują mojej pracy”", "C": "„Pani nigdy nie słucha tego, co mówię, i zawsze robi Pani wszystko po swojemu, wbrew zaleceniom”", "D": "„Pan zawsze się spóźnia i przez Pana wszystko się opóźnia!”"}, "poprawna": "A", "wyjasnienie": "Komunikat „ja” opisuje własne uczucia i konkretne zachowanie bez oceniania osoby, co ułatwia rozwiązanie konfliktu.", "zrodlo": "MED.10.8.8"},
  {"id": "MED10-394", "dzial": "MED.10.8 Kompetencje personalne i społeczne", "pytanie": "Do elementów komunikacji niewerbalnej masażysty należą", "odpowiedzi": {"A": "treść pisemnego skierowania na zabieg", "B": "mimika, postawa ciała, ton głosu i dotyk", "C": "fachowe nazwy technik zapisane w dokumentacji zabiegowej", "D": "słowa użyte w karcie zabiegów"}, "poprawna": "B", "wyjasnienie": "Komunikacja niewerbalna to przekaz bez słów: wyraz twarzy, gesty, postawa, dystans, ton głosu oraz dotyk, szczególnie ważny w pracy masażysty.", "zrodlo": "MED.10.8.8"},
  {"id": "MED10-395", "dzial": "MED.10.8 Kompetencje personalne i społeczne", "pytanie": "Trening relaksacyjny Jacobsona, pomocny w radzeniu sobie ze stresem, polega na", "odpowiedzi": {"A": "długotrwałym wstrzymywaniu oddechu", "B": "ograniczeniu snu w celu zwiększenia odporności", "C": "naprzemiennym napinaniu i rozluźnianiu kolejnych grup mięśni", "D": "wielogodzinnym, intensywnym wysiłku wytrzymałościowym bez przerw"}, "poprawna": "C", "wyjasnienie": "Progresywna relaksacja mięśni uczy rozpoznawać napięcie i świadomie je rozluźniać, co obniża poziom stresu.", "zrodlo": "MED.10.8.6"},
  {"id": "MED10-396", "dzial": "MED.10.8 Kompetencje personalne i społeczne", "pytanie": "Rozmawiając z pacjentem z niedosłuchem, masażysta powinien", "odpowiedzi": {"A": "mówić bardzo szybko, aby skrócić rozmowę", "B": "odwrócić się plecami i znacznie podnieść głos", "C": "mówić wyraźnie, zwrócony twarzą do pacjenta, w dobrze oświetlonym miejscu", "D": "porozumiewać się wyłącznie z osobą towarzyszącą, pomijając samego pacjenta"}, "poprawna": "C", "wyjasnienie": "Widoczna twarz ułatwia odczytywanie mowy z ust. Pacjent powinien być bezpośrednim uczestnikiem rozmowy.", "zrodlo": "MED.10.8.8"},
  {"id": "MED10-397", "dzial": "MED.10.8 Kompetencje personalne i społeczne", "pytanie": "Pacjent jest zdenerwowany, bo zabieg rozpoczął się 15 minut później. Masażysta powinien", "odpowiedzi": {"A": "zignorować uwagi pacjenta i rozpocząć zabieg w milczeniu", "B": "spokojnie przeprosić, wyjaśnić przyczynę i zaproponować rozwiązanie", "C": "skrócić zabieg bez informowania o tym pacjenta", "D": "obwinić poprzedniego pacjenta za opóźnienie w obecności innych oczekujących osób"}, "poprawna": "B", "wyjasnienie": "Rzeczowa komunikacja i szacunek dla pacjenta łagodzą konflikt i budują zaufanie. To element wysokiej jakości usług.", "zrodlo": "MED.10.8.8"},
  {"id": "MED10-398", "dzial": "MED.10.9 Organizacja pracy małych zespołów", "pytanie": "Cel sformułowany zgodnie z zasadą SMART powinien być m.in.", "odpowiedzi": {"A": "niemożliwy do osiągnięcia, aby motywował", "B": "znany wyłącznie kierownikowi zespołu", "C": "ogólny i bez terminu realizacji", "D": "mierzalny i określony w czasie"}, "poprawna": "D", "wyjasnienie": "SMART: konkretny, mierzalny, osiągalny, istotny i określony w czasie.", "zrodlo": "MED.10.9.1"},
  {"id": "MED10-399", "dzial": "MED.10.9 Organizacja pracy małych zespołów", "pytanie": "Burza mózgów to metoda pracy zespołu polegająca na", "odpowiedzi": {"A": "zgłaszaniu jak największej liczby pomysłów bez ich oceniania w pierwszym etapie", "B": "podejmowaniu decyzji wyłącznie przez kierownika", "C": "losowym podziale zadań między członków zespołu", "D": "szczegółowym krytykowaniu każdego pomysłu przez cały zespół zaraz po jego zgłoszeniu"}, "poprawna": "A", "wyjasnienie": "Odroczenie krytyki sprzyja kreatywności. Pomysły ocenia się i wybiera dopiero w drugim etapie.", "zrodlo": "MED.10.9.5"},
  {"id": "MED10-400", "dzial": "MED.10.9 Organizacja pracy małych zespołów", "pytanie": "Kontrola bieżąca w pracy zespołu jest prowadzona", "odpowiedzi": {"A": "dopiero po zakończeniu całego projektu", "B": "tylko raz w roku podczas oceny okresowej", "C": "w trakcie wykonywania zadań", "D": "wyłącznie przed rozpoczęciem zadań"}, "poprawna": "C", "wyjasnienie": "Kontrola wstępna poprzedza działanie, bieżąca trwa w jego trakcie, a końcowa ocenia wynik. Kontrola bieżąca pozwala szybko korygować błędy.", "zrodlo": "MED.10.9.3"},
  {"id": "MED10-401", "dzial": "MED.10.9 Organizacja pracy małych zespołów", "pytanie": "Przekazując zadanie członkowi zespołu (delegowanie), kierownik powinien", "odpowiedzi": {"A": "wyznaczyć termin, nie określając oczekiwanego rezultatu", "B": "przekazać zadanie bez żadnych wyjaśnień, aby sprawdzić samodzielność i zaradność pracownika", "C": "przekazać zadanie osobie bez wymaganych kwalifikacji", "D": "jasno określić zadanie, termin i oczekiwany rezultat oraz zapewnić potrzebne środki"}, "poprawna": "D", "wyjasnienie": "Skuteczne delegowanie wymaga jasnych oczekiwań, kompetentnego wykonawcy i odpowiednich zasobów. Kierownik nadal odpowiada za efekt.", "zrodlo": "MED.10.9.2"}
];
